#[tokio::main]
async fn main() {
    let launch = match parse_launch_args(std::env::args_os()) {
        Ok(launch) => launch,
        Err(error) => error.exit(),
    };
    let exit_code = match launch {
        LaunchArgs::Serve(cli) => service::run_production(cli).await,
        LaunchArgs::Acp(cli) => acp::run_production(cli).await,
        LaunchArgs::Attach(cli) => service::run_attach(cli).await,
        LaunchArgs::Schedule(cli) => schedule::run_cli(cli).await,
        LaunchArgs::ScheduleWorker(cli) => run_schedule_worker(cli).await,
        LaunchArgs::Automation(cli) => automation::run_cli(cli).await,
        LaunchArgs::AutomationEngine(cli) => automation_engine_cli::run_cli(cli).await,
        LaunchArgs::RoleRun(cli) => role_run::run_cli(cli).await,
        LaunchArgs::LearningBridge(cli) => learning::run_bridge_cli(cli),
        LaunchArgs::Email(cli) => email::gateway::run_cli(cli).await,
        #[cfg(feature = "planner-executor-experiment")]
        LaunchArgs::ReasoningExperimentBroker => {
            reasoning_experiment_worker::run_provider_broker_stdio().await
        }
        #[cfg(feature = "planner-executor-experiment")]
        LaunchArgs::ReasoningExperimentBrokerPreflight => {
            reasoning_experiment_worker::run_provider_broker_preflight().await
        }
        #[cfg(feature = "planner-executor-experiment")]
        LaunchArgs::ReasoningExperimentToolWorker => {
            reasoning_experiment_worker::run_tool_worker_stdio().await
        }
        #[cfg(feature = "planner-executor-experiment")]
        LaunchArgs::ReasoningExperimentToolWorkerPreflight => {
            reasoning_experiment_worker::run_tool_worker_preflight().await
        }
        LaunchArgs::Plugin(cli) => plugin::run_cli(cli).await,
        LaunchArgs::Pricing(cli) => pricing::run_cli(cli).await,
        LaunchArgs::Skill(cli) => skill_cli::run_cli(cli),
        LaunchArgs::Memory(cli) => memory_benchmark_cli::run(cli).await,
        LaunchArgs::Learn(cli) => codex_learning::run_cli(cli).await,
        LaunchArgs::Audit(cli) => security_audit::run_cli(cli),
        LaunchArgs::Runtime(cli) => external_runtime::run_cli(cli).await,
        LaunchArgs::Local(cli) => local_models::run_cli(cli).await,
        LaunchArgs::Update(cli) => self_update::run_cli(cli).await,
        LaunchArgs::ShellIntegration(cli) => shell_integration::run_cli(cli),
        LaunchArgs::Repo(cli) => worktree_setup::run_cli(cli).await,
        LaunchArgs::SupportBundle(cli) => support_bundle::run_support_bundle_cli(cli),
        LaunchArgs::ConfigExplain(cli) => support_bundle::run_config_explain_cli(cli),
        LaunchArgs::FilterCheck(cli) => run_filter_check(cli),
        LaunchArgs::SetupImport(cli) => setup_import::run_cli(cli),
        LaunchArgs::HarnessWorker => harness_worker::run_stdio().await,
        LaunchArgs::HarnessVerifier => harness_verifier::run_stdio().await,
        LaunchArgs::HarnessBuildIdentity => {
            println!("{}", env!("CA_BUILD_DIGEST"));
            0
        }
        LaunchArgs::Harness(args) => {
            if args.first().and_then(|argument| argument.to_str()) == Some("questionnaire") {
                harness_questionnaire_cli::run_cli(&args[1..]).await
            } else if matches!(
                args.first().and_then(|s| s.to_str()),
                Some("run" | "create" | "rollback" | "discover" | "review" | "promote" | "migrate")
            ) {
                let result = if args[0] == "discover" {
                    harness_control::discover(&args).await
                } else if args[0] == "create" {
                    harness_control::create_cycle(&args).await
                } else if args[0] == "rollback" {
                    harness_control::rollback(&args).await
                } else if args[0] == "review" {
                    harness_control::review(&args).await
                } else if args[0] == "migrate" {
                    harness_control::migrate_vault(&args).await
                } else if args[0] == "promote" {
                    harness_control::promote(&args).await
                } else {
                    harness_control::run_evaluation(&args).await
                };
                match result {
                    Ok(()) => 0,
                    Err(error) => {
                        eprintln!("{error}");
                        1
                    }
                }
            } else {
                run_harness_cli(args)
            }
        }
        LaunchArgs::Standard(cli) => run_standard(*cli).await,
    };
    browser::BrowserManager::process().shutdown().await;
    process_watch::ProcessWatchManager::process()
        .shutdown()
        .await;
    jobs::JobManager::process().shutdown().await;
    keep_awake::shutdown_process().await;
    if exit_code != 0 {
        std::process::exit(exit_code);
    }
}

async fn run_standard(cli: CliArgs) -> i32 {
    if let Some(required) = cli.min_version.as_ref() {
        if let Err(error) = local_automation::require_minimum_version(required) {
            eprintln!("ca: {error}");
            return 2;
        }
    }
    let trace_hub = match initialize_provider_trace(&cli.active_profile, cli.trace) {
        Ok(hub) => hub,
        Err(error) => {
            eprintln!("ca: {error}");
            return 3;
        }
    };
    provider_trace::install_process_hub(trace_hub.clone());
    let agent_launch = !cli.list_models && !cli.doctor && cli.test_script.is_none();
    let runtime_diagnostics = if agent_launch {
        initialize_runtime_diagnostics(&cli.active_profile)
    } else {
        runtime_diagnostics::RuntimeDiagnostics::disabled()
    };
    runtime_diagnostics::install_process(runtime_diagnostics.clone());
    if let Some(bytes) = agent_launch
        .then(runtime_diagnostics::current_resident_bytes)
        .flatten()
    {
        runtime_diagnostics.sample_memory(bytes);
    }
    let exit_code = if cli.list_models {
        match list_models_and_exit(&cli.active_profile) {
            Ok(()) => 0,
            Err(error) => {
                eprintln!("ca: {error:#}");
                3
            }
        }
    } else if cli.doctor {
        run_doctor(&cli).await
    } else if let Some(script) = cli.test_script.as_deref() {
        match test::run_test(script, &cli.tool_policy).await {
            Ok(()) => 0,
            Err(error) => {
                eprintln!("ca: {error:#}");
                1
            }
        }
    } else {
        let is_tty = std::io::IsTerminal::is_terminal(&std::io::stdin());
        if cli.one_shot_prompt.is_some()
            || !is_tty
            || cli.check_mode.enabled()
            || cli.output_schema.is_some()
            || cli.printenv
        {
            run_headless(cli).await.code
        } else {
            match run_tui(cli).await {
                Ok(handoff) => {
                    if let Some(handoff) = handoff {
                        print!("{handoff}");
                    }
                    0
                }
                Err(error) => {
                    eprintln!("ca: {error:#}");
                    1
                }
            }
        }
    };
    if let Some(diagnostic) = provider_trace::process_hub()
        .as_ref()
        .and_then(provider_trace::ProviderTraceHub::take_diagnostic)
    {
        eprintln!("ca: {diagnostic}");
    }
    trace_hub.stop_and_flush(std::time::Duration::from_secs(2));
    if let Some(diagnostic) = trace_hub.take_diagnostic() {
        eprintln!("ca: {diagnostic}");
    }
    if let Some(bytes) = runtime_diagnostics::current_resident_bytes() {
        runtime_diagnostics.sample_memory(bytes);
    }
    runtime_diagnostics
        .hub()
        .finish(true, runtime_diagnostics.peak_memory_bytes());
    if let Some(error) = runtime_diagnostics.hub().take_error() {
        eprintln!("ca: runtime logging stopped: {error}");
    }
    exit_code
}

#[cfg(not(test))]
fn configure_keep_awake_for_launch(
    cli: &CliArgs,
    config: &CaConfig,
) -> keep_awake::KeepAwakeAvailability {
    keep_awake::configure_process(cli.keep_awake.unwrap_or(config.agent.keep_awake))
}

#[cfg(test)]
fn configure_keep_awake_for_launch(
    _cli: &CliArgs,
    _config: &CaConfig,
) -> keep_awake::KeepAwakeAvailability {
    keep_awake::configure_process(false)
}

fn initialize_runtime_diagnostics(
    profile: &runtime::ActiveProfile,
) -> runtime_diagnostics::RuntimeDiagnostics {
    if matches!(profile, runtime::ActiveProfile::Bare) {
        return runtime_diagnostics::RuntimeDiagnostics::disabled();
    }
    let Ok(paths) = runtime::RuntimePaths::discover() else {
        eprintln!("ca: runtime logging unavailable: runtime paths are unavailable");
        return runtime_diagnostics::RuntimeDiagnostics::disabled();
    };
    let hub = runtime_diagnostics::RuntimeLogHub::new(paths.runtime_log_dir(profile), true);
    if let Err(error) = hub.start() {
        eprintln!("ca: runtime logging unavailable: {error}");
        return runtime_diagnostics::RuntimeDiagnostics::disabled();
    }
    runtime_diagnostics::RuntimeDiagnostics::new(hub)
}

fn initialize_provider_trace(
    profile: &runtime::ActiveProfile,
    enabled: bool,
) -> Result<provider_trace::ProviderTraceHub, provider_trace::TraceError> {
    let paths = match runtime::RuntimePaths::discover() {
        Ok(paths) => paths,
        Err(_) if !enabled => {
            return Ok(provider_trace::ProviderTraceHub::new(
                std::path::PathBuf::new(),
                false,
            ));
        }
        Err(_) => {
            return Err(provider_trace::TraceError::Storage(
                "runtime paths are unavailable".into(),
            ));
        }
    };
    let hub = provider_trace::ProviderTraceHub::new(
        paths.provider_trace_dir(profile),
        !matches!(profile, runtime::ActiveProfile::Bare),
    );
    if enabled {
        hub.start()?;
    }
    Ok(hub)
}

fn register_provider_trace_secrets(config: &CaConfig) {
    if let Some(hub) = provider_trace::process_hub() {
        hub.add_configured_secrets(
            config
                .providers
                .values()
                .map(|provider| provider.api_key.as_str()),
        );
    }
}

#[cfg(test)]
mod session_portability_orchestration_tests {
    use super::*;
    use chrono::Utc;

    fn message(role: Role, content: &str) -> Message {
        Message {
            role,
            content: content.into(),
            tool_calls: None,
            thinking: None,
            timestamp: Utc::now(),
            response_items: Vec::new(),
        }
    }

    fn state_with_history(workspace: &std::path::Path) -> AppState {
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.cwd = workspace.to_string_lossy().into_owned();
        state.session_name = "Imported source".into();
        state.current_model = Some(ModelInfo {
            provider: "safe".into(),
            id: "model".into(),
            display_name: "model".into(),
        });
        state.messages = vec![message(Role::User, "hello"), message(Role::Assistant, "hi")];
        state
    }

    #[test]
    fn export_argument_parsing_preserves_space_paths_and_json_inference() {
        let root = tempfile::tempdir().unwrap();
        let mut state = state_with_history(root.path());
        begin_session_export(&mut state, "exports/my session.json");
        let request = state.session_portability_request.unwrap();
        assert_eq!(request.path, root.path().join("exports/my session.json"));
        assert_eq!(
            request.operation,
            crate::app::SessionPortabilityOperation::Export {
                format: session_portability::ExportFormat::Json,
                overwrite: false,
            }
        );

        let mut state = state_with_history(root.path());
        begin_session_export(&mut state, "markdown 'notes/my session.md'");
        assert_eq!(
            state.session_portability_request.unwrap().path,
            root.path().join("notes/my session.md")
        );
    }

    #[test]
    fn bare_and_no_session_import_are_rejected_before_file_io() {
        for profile in [
            runtime::ActiveProfile::Bare,
            runtime::ActiveProfile::Default,
        ] {
            let mut state = AppState::new(context::ShellHistory::in_memory());
            state.active_profile = profile.clone();
            state.run_capabilities = if matches!(profile, runtime::ActiveProfile::Bare) {
                runtime::RunCapabilities::for_profile(&profile)
            } else {
                runtime::RunCapabilities::for_run(&profile, true)
            };
            begin_session_import(&mut state, "/does/not/exist.json");
            assert!(state.session_portability_request.is_none());
            assert!(state
                .status_message
                .as_deref()
                .unwrap()
                .contains("unavailable"));
        }
    }

    #[test]
    fn claude_setup_slash_import_previews_project_scope_without_session_authority() {
        let root = tempfile::tempdir().unwrap();
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.cwd = root.path().to_string_lossy().into_owned();
        state.run_capabilities =
            runtime::RunCapabilities::for_run(&runtime::ActiveProfile::Default, true);
        begin_session_import(&mut state, "setup claude './foreign setup'");
        let request = state.setup_import_request.unwrap();
        assert_eq!(request.source, root.path().join("foreign setup"));
        assert_eq!(request.scope, setup_import::SetupImportScope::Project);
        assert_eq!(request.operation, crate::app::SetupImportOperation::Preview);

        let mut bare = AppState::new(context::ShellHistory::in_memory());
        bare.active_profile = runtime::ActiveProfile::Bare;
        bare.run_capabilities = runtime::RunCapabilities::for_profile(&bare.active_profile);
        begin_session_import(&mut bare, "setup claude /does/not/exist");
        assert!(bare.setup_import_request.is_none());
        assert!(bare.status_message.unwrap().contains("bare profile"));
    }

    #[test]
    fn successful_import_is_new_inert_saved_history_and_does_not_replace_current() {
        let root = tempfile::tempdir().unwrap();
        let active = root.path().join("sessions");
        let archive = root.path().join("archive");
        let store = session::SessionStore::with_archive(&active, &archive);
        let source_state = state_with_history(root.path());
        let source = portable_session_snapshot(&source_state);
        let input = root.path().join("portable.json");
        std::fs::write(
            &input,
            session_portability::encode_session(&source, session_portability::ExportFormat::Json)
                .unwrap(),
        )
        .unwrap();

        let mut state = state_with_history(root.path());
        let mut current = session::SessionV2::new(
            "Current",
            root.path().to_string_lossy(),
            "safe",
            "model",
            state.messages.clone(),
        );
        store.save(&mut current).unwrap();
        let current_id = current.id;
        state.current_session = Some(current);
        state.session_portability_generation = 3;
        state.session_portability = Some(crate::app::SessionPortabilityState {
            operation: crate::app::SessionPortabilityOperation::Import,
            path: input.clone(),
            generation: 3,
            busy: true,
            awaiting_overwrite: false,
            overwrite_selected: false,
            import_selected: false,
            import_learning_eligible: false,
            import_preview: None,
            error: None,
        });
        let result = perform_session_import(
            &store,
            input,
            session_portability::ImportDefaults {
                workspace: root.path().to_string_lossy().into_owned(),
                provider: "safe".into(),
                model: "model".into(),
                reasoning_effort: None,
            },
            3,
        );
        apply_session_portability_result(&mut state, result);

        assert_eq!(state.current_session.as_ref().unwrap().id, current_id);
        assert!(state.session_picker_open);
        let selected = &state.session_list[state.selected_session_idx];
        assert_ne!(selected.id, current_id);
        let imported = store.load(&selected.storage_key).unwrap();
        assert!(imported.parent.is_none());
        assert!(imported.queued_inputs.is_empty());
        assert!(imported.agent_summaries.is_empty());
        assert_eq!(imported.messages.len(), 2);
    }

    #[test]
    fn failed_and_stale_import_results_never_change_session_state() {
        let root = tempfile::tempdir().unwrap();
        let store = session::SessionStore::with_archive(
            root.path().join("sessions"),
            root.path().join("archive"),
        );
        let input = root.path().join("invalid.json");
        std::fs::write(&input, b"{\"schema\":\"wrong\"}").unwrap();
        let mut state = state_with_history(root.path());
        let canonical = serde_json::to_string(&state.messages).unwrap();
        state.session_portability_generation = 8;
        state.session_portability = Some(crate::app::SessionPortabilityState {
            operation: crate::app::SessionPortabilityOperation::Import,
            path: input.clone(),
            generation: 8,
            busy: true,
            awaiting_overwrite: false,
            overwrite_selected: false,
            import_selected: false,
            import_learning_eligible: false,
            import_preview: None,
            error: None,
        });
        let stale = perform_session_import(
            &store,
            input.clone(),
            session_portability::ImportDefaults {
                workspace: state.cwd.clone(),
                provider: "safe".into(),
                model: "model".into(),
                reasoning_effort: None,
            },
            7,
        );
        apply_session_portability_result(&mut state, stale);
        assert!(state.session_portability.as_ref().unwrap().busy);

        let current = perform_session_import(
            &store,
            input,
            session_portability::ImportDefaults {
                workspace: state.cwd.clone(),
                provider: "safe".into(),
                model: "model".into(),
                reasoning_effort: None,
            },
            8,
        );
        apply_session_portability_result(&mut state, current);
        assert!(state
            .session_portability
            .as_ref()
            .unwrap()
            .error
            .as_deref()
            .unwrap()
            .contains("Session import failed"));
        assert_eq!(serde_json::to_string(&state.messages).unwrap(), canonical);
        assert!(store.list().unwrap().is_empty());
    }

    #[test]
    fn foreign_import_is_previewed_before_fresh_inert_sessions_are_saved() {
        let root = tempfile::tempdir().unwrap();
        let store = session::SessionStore::with_archive(
            root.path().join("sessions"),
            root.path().join("archive"),
        );
        let input = root.path().join("codex history.jsonl");
        std::fs::write(
            &input,
            concat!(
                "{\"type\":\"session_meta\",\"payload\":{\"id\":\"foreign-session\"}}\n",
                "{\"type\":\"response_item\",\"payload\":{\"type\":\"message\",\"role\":\"user\",\"content\":[{\"type\":\"input_text\",\"text\":\"question\"}]}}\n",
                "{\"type\":\"response_item\",\"payload\":{\"type\":\"message\",\"role\":\"assistant\",\"content\":[{\"type\":\"output_text\",\"text\":\"answer\"}]}}\n"
            ),
        )
        .unwrap();
        let mut state = state_with_history(root.path());
        let current = session::SessionV2::new(
            "Current",
            root.path().to_string_lossy(),
            "safe",
            "model",
            state.messages.clone(),
        );
        let current_id = current.id;
        state.current_session = Some(current);
        begin_session_import(&mut state, &format!("codex '{}'", input.to_string_lossy()));
        let preview_request = state.session_portability_request.take().unwrap();
        assert_eq!(
            preview_request.operation,
            crate::app::SessionPortabilityOperation::ForeignImport {
                source: crate::session::ForeignTranscriptSource::Codex,
                commit: false,
                learning_eligible: false,
            }
        );
        let defaults = session_portability::ImportDefaults {
            workspace: state.cwd.clone(),
            provider: "safe".into(),
            model: "model".into(),
            reasoning_effort: None,
        };
        let preview = perform_foreign_session_import(
            &store,
            input.clone(),
            defaults.clone(),
            crate::session::ForeignTranscriptSource::Codex,
            false,
            false,
            preview_request.generation,
        );
        apply_session_portability_result(&mut state, preview);
        assert!(store.list().unwrap().is_empty());
        let overlay = state.session_portability.as_ref().unwrap();
        assert!(!overlay.busy);
        assert_eq!(overlay.import_preview.as_ref().unwrap().sessions, 1);

        let operation = crate::app::SessionPortabilityOperation::ForeignImport {
            source: crate::session::ForeignTranscriptSource::Codex,
            commit: true,
            learning_eligible: false,
        };
        let overlay = state.session_portability.as_mut().unwrap();
        overlay.operation = operation;
        overlay.busy = true;
        let committed = perform_foreign_session_import(
            &store,
            input,
            defaults,
            crate::session::ForeignTranscriptSource::Codex,
            true,
            false,
            preview_request.generation,
        );
        apply_session_portability_result(&mut state, committed);
        assert_eq!(state.current_session.as_ref().unwrap().id, current_id);
        assert!(state.session_picker_open);
        let summaries = store.list().unwrap();
        assert_eq!(summaries.len(), 1);
        let imported = store.load(&summaries[0].storage_key).unwrap();
        assert_ne!(imported.id, current_id);
        assert_eq!(imported.provider, "safe");
        assert_eq!(imported.model, "model");
        assert_eq!(imported.messages.len(), 2);
        assert!(imported.messages.iter().all(|message| {
            message.thinking.is_none()
                && message.tool_calls.is_none()
                && message.response_items.is_empty()
        }));
        assert!(
            !imported
                .import_provenance
                .as_ref()
                .unwrap()
                .learning_eligible
        );
    }
}

#[cfg(test)]
mod session_retention_orchestration_tests {
    use super::*;

    #[test]
    fn opening_loads_asynchronously_and_no_session_stays_store_free() {
        let config = CaConfig::default_config();
        let mut state = AppState::new(context::ShellHistory::in_memory());
        open_session_retention(&mut state, &config);
        assert_eq!(
            state.session_retention.as_ref().unwrap().busy,
            Some(crate::app::SessionRetentionBusy::Loading)
        );
        assert!(matches!(
            state.session_retention_request,
            Some(crate::app::SessionRetentionRequest {
                operation: crate::app::SessionRetentionOperation::Load,
                ..
            })
        ));

        let mut no_session = AppState::new(context::ShellHistory::in_memory());
        no_session.run_capabilities =
            runtime::RunCapabilities::for_run(&runtime::ActiveProfile::Default, true);
        open_session_retention(&mut no_session, &config);
        let manager = no_session.session_retention.as_ref().unwrap();
        assert!(manager.busy.is_none());
        assert!(!manager.sessions_enabled);
        assert!(manager.writes_enabled);
        assert!(no_session.session_retention_request.is_none());
    }

    #[test]
    fn saving_updates_config_without_deleting_and_stale_results_are_ignored() {
        let root = tempfile::tempdir().unwrap();
        let config_path = root.path().join("config.toml");
        let config_store = ConfigStore::new(&config_path);
        let mut config = config_store.load().unwrap();
        let session_store = session::SessionStore::with_archive(
            root.path().join("sessions"),
            root.path().join("archive"),
        );
        let mut saved = session::SessionV2::new("Keep", "/workspace", "local", "coder", Vec::new());
        session_store.save(&mut saved).unwrap();

        let mut state = AppState::new(context::ShellHistory::in_memory());
        open_session_retention(&mut state, &config);
        let load_request = state.session_retention_request.take().unwrap();
        let load_result = perform_session_retention(&session_store, &config_store, load_request);
        apply_session_retention_result(&mut state, &mut config, load_result);
        assert_eq!(state.session_retention.as_ref().unwrap().active_count, 1);

        let generation = state.session_retention_generation + 1;
        state.session_retention_generation = generation;
        state.session_retention.as_mut().unwrap().generation = generation;
        let save_result = perform_session_retention(
            &session_store,
            &config_store,
            crate::app::SessionRetentionRequest {
                generation,
                operation: crate::app::SessionRetentionOperation::Save(
                    session_retention::RetentionSettings {
                        days: Some(45),
                        count: Some(10),
                    },
                ),
            },
        );
        apply_session_retention_result(&mut state, &mut config, save_result);
        assert_eq!(
            config.session_retention_settings().unwrap(),
            session_retention::RetentionSettings {
                days: Some(45),
                count: Some(10),
            }
        );
        assert_eq!(session_store.list().unwrap().len(), 1);
        assert!(state
            .session_retention
            .as_ref()
            .unwrap()
            .notice
            .as_deref()
            .unwrap()
            .contains("no sessions deleted"));

        let stale = SessionRetentionTaskResult {
            generation: generation - 1,
            outcome: SessionRetentionTaskOutcome::Loaded(SessionRetentionLists {
                active: Ok(Vec::new()),
                archived: Ok(Vec::new()),
            }),
        };
        apply_session_retention_result(&mut state, &mut config, stale);
        assert_eq!(state.session_list.len(), 1);
    }

    #[test]
    fn failed_confirmed_delete_refreshes_and_remains_in_preview() {
        let root = tempfile::tempdir().unwrap();
        let config_path = root.path().join("config.toml");
        let config_store = ConfigStore::new(&config_path);
        let mut config = config_store.load().unwrap();
        let session_store = session::SessionStore::with_archive(
            root.path().join("sessions"),
            root.path().join("archive"),
        );
        let mut pinned =
            session::SessionV2::new("Pinned", "/workspace", "local", "coder", Vec::new());
        pinned.pinned = true;
        let path = session_store.save(&mut pinned).unwrap();
        let candidate = session_retention::RetentionCandidate {
            storage_key: path.file_stem().unwrap().to_str().unwrap().into(),
            id: pinned.id,
            title: pinned.title.clone(),
            updated_at: pinned.updated_at,
            reason: session_retention::RetentionReason::Age,
        };
        let settings = session_retention::RetentionSettings {
            days: Some(1),
            count: None,
        };
        let generation = 4;
        let preview = session_retention::RetentionPreview {
            settings,
            generated_at: chrono::Utc::now(),
            active_count: 1,
            protected_current: 0,
            protected_pinned: 0,
            candidates: vec![candidate],
        };
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.session_retention_generation = generation;
        state.session_retention = Some(crate::app::SessionRetentionState {
            settings,
            mode: crate::app::SessionRetentionMode::Preview,
            field: crate::app::SessionRetentionField::Days,
            days_input: "1".into(),
            count_input: String::new(),
            cursor: 1,
            preview: Some(preview.clone()),
            preview_selected_idx: 0,
            delete_selected: true,
            busy: Some(crate::app::SessionRetentionBusy::Deleting),
            writes_enabled: true,
            sessions_enabled: true,
            active_count: 1,
            archived_count: 0,
            generation,
            notice: None,
            error: None,
        });
        let result = perform_session_retention(
            &session_store,
            &config_store,
            crate::app::SessionRetentionRequest {
                generation,
                operation: crate::app::SessionRetentionOperation::Delete {
                    preview,
                    current_id: None,
                },
            },
        );
        apply_session_retention_result(&mut state, &mut config, result);

        let manager = state.session_retention.as_ref().unwrap();
        assert_eq!(manager.mode, crate::app::SessionRetentionMode::Preview);
        assert!(manager.busy.is_none());
        assert!(manager.error.as_deref().unwrap().contains("pinned"));
        assert!(path.is_file());
    }
}

#[derive(Debug, Parser)]
#[command(
    name = "ca",
    version,
    about = "Cursor-compatible terminal coding agent",
    after_help = "Commands:\n  dashboard                           Open the agent dashboard\n  serve [--stdio | --listen IP:PORT]  Run the versioned JSONL service\n  acp                                 Run the stable ACP v1 stdio agent\n  attach ws://IP:PORT                 Bridge JSONL to an authenticated loopback service\n  schedule <COMMAND>                  Manage explicit profile-scoped scheduled runs\n  automation <COMMAND>                Manage confirmed local automations and results\n  automation-engine <COMMAND>         Operate durable typed automations without a provider\n  role-run --profile NAME             Run one restricted orchestrator role\n  learning-bridge <COMMAND>           Exchange sanitized enrolled learning evidence\n  email <COMMAND>                     Manage the dedicated draft-only email gateway\n  skill <COMMAND>                     Inspect and manage portable Agent Skills\n  learn <COMMAND>                     Operate continuous local Dream/Distill learning\n  audit                               Audit the local agent harness without execution\n  support-bundle                      Create a private metadata-only support archive\n  config explain [SELECTOR]           Explain setting origins without showing values\n  filter check [--text TEXT|--file PATH] [--hide WORD] [--hide-urls] [--pages SPEC]  Print the armed provider filter without contacting a provider\n  import setup claude                 Preview/apply inert Claude setup assets\n  plugin <COMMAND>                    Manage explicit local plugin bundles\n  pricing <COMMAND>                   Inspect or refresh official route pricing\n  runtime <COMMAND>                   Manage explicitly selected signed runtimes\n  local <COMMAND>                     Manage explicit GGUF models and local runs\n  update <COMMAND>                    Explicitly verify and install signed ca releases\n  repo info|status|worktree-setup     Inspect local repository state and setup\n  shell-integration zsh               Print zsh completion and terminal-key setup\n  install-shell-integration           Install the managed zsh integration block\n  uninstall-shell-integration         Remove only the managed zsh integration block\n\nAttachments may be supplied as @path positional arguments."
)]
struct RawCliArgs {
    /// Fail before initialization unless this CA version satisfies the strict SemVer minimum
    #[arg(long, value_name = "SEMVER")]
    min_version: Option<String>,

    /// Continue the most recently updated session
    #[arg(short = 'c', long = "continue")]
    continue_last: bool,

    /// Open the saved-session picker
    #[arg(short = 'r', long = "resume-list")]
    browse_sessions: bool,

    /// Open the agent dashboard
    #[arg(long = "dashboard")]
    dashboard: bool,

    /// Set the session display name
    #[arg(long = "name", value_name = "NAME")]
    session_name: Option<String>,

    /// Run one prompt without opening the TUI
    #[arg(short = 'p', long = "prompt", value_name = "PROMPT")]
    prompt: Option<String>,

    /// Resume by ses_ identifier, UUID, or legacy storage key
    #[arg(short = 's', long = "session", value_name = "ID")]
    resume_session: Option<String>,

    /// Run a scripted .ca test case
    #[arg(long = "test", value_name = "SCRIPT_FILE")]
    test_script: Option<String>,

    /// Select human text, aggregate JSON, or streaming JSONL output
    #[arg(long, value_enum, default_value_t = headless::OutputFormat::Text)]
    output_format: headless::OutputFormat,

    /// Include provider reasoning events when supported
    #[arg(long)]
    show_thinking: bool,

    /// Automatically execute read-only tools in headless mode using CA-local safe-tool evaluation (not a remote classifier)
    #[arg(long, conflicts_with = "yolo")]
    auto_review: bool,

    /// Bypass interactive approval prompts (boundaries still apply; exclusive with --auto-review)
    #[arg(long, conflicts_with = "auto_review")]
    yolo: bool,

    /// Permit approved network-capable tools in headless mode
    #[arg(long)]
    allow_network: bool,

    /// Persist a redacted provider exchange trace for this run
    #[arg(long)]
    trace: bool,

    /// Arm the configured provider filter for this process without writing the config file
    #[arg(long)]
    filter: bool,

    /// Atomically write the terminal assistant message to a file
    #[arg(long, value_name = "PATH")]
    output_last_message: Option<std::path::PathBuf>,

    /// Run a fresh-context verification pass after a successful headless task
    #[arg(long)]
    check: bool,

    /// Permit the verification pass to propose repairs through normal tool policy
    #[arg(long, requires = "check")]
    check_repair: bool,

    /// Require two explicitly configured isolated reviewers to pass
    #[arg(long, requires = "check")]
    check_converge: bool,

    /// Acknowledge unknown pricing for this one convergent review run
    #[arg(long, requires = "check_converge")]
    check_converge_unpriced: bool,

    /// Require the headless result to match a bounded local JSON Schema
    #[arg(long, value_name = "PATH")]
    output_schema: Option<std::path::PathBuf>,

    /// Activate an exact filesystem skill ID (repeatable)
    #[arg(long = "skill", value_name = "ID")]
    skills: Vec<String>,

    /// Replace the default model-visible tools (repeatable or comma-delimited)
    #[arg(long = "tools", value_name = "TOOL[,TOOL]", action = clap::ArgAction::Append)]
    tools: Option<Vec<String>>,

    /// Add model-visible tools after the default or replacement set
    #[arg(long = "include-tools", value_name = "TOOL[,TOOL]", action = clap::ArgAction::Append)]
    include_tools: Vec<String>,

    /// Remove model-visible tools after replacement and inclusion
    #[arg(long = "exclude-tools", value_name = "TOOL[,TOOL]", action = clap::ArgAction::Append)]
    exclude_tools: Vec<String>,

    /// List configured models and exit
    #[arg(long)]
    list_models: bool,

    /// Check local ca readiness and exit without contacting providers
    #[arg(long)]
    doctor: bool,

    /// Include one isolated provider request per configured provider
    #[arg(long, requires = "doctor")]
    connect: bool,

    /// Verify one first-party provider contract with at most two no-retry requests (repeatable)
    #[arg(
        long = "provider-contract",
        value_enum,
        action = clap::ArgAction::Append,
        requires_all = ["doctor", "connect"],
        conflicts_with = "trace"
    )]
    provider_contracts: Vec<provider_contract_verifier::ProviderContractTarget>,

    /// Keep this run and its branches in memory without reading or writing saved sessions
    #[arg(long)]
    no_session: bool,

    /// Do not wait for automatic background-job completion follow-ups
    #[arg(long)]
    single_turn: bool,

    /// Keep the machine awake only while an interactive turn or model-owned job is active
    #[arg(long, conflicts_with = "no_keep_awake")]
    keep_awake: bool,

    /// Disable active-work sleep inhibition for this process
    #[arg(long, conflicts_with = "keep_awake")]
    no_keep_awake: bool,

    /// Seed this process from a bounded ca.session-export.v1 file without importing it
    #[arg(long, value_name = "FILE")]
    conversation_history_file: Option<std::path::PathBuf>,

    /// Omit automatically sourced workspace context for this process
    #[arg(long)]
    exclude_workspace_context: bool,

    /// Select the UUID for a fresh persistent interactive session
    #[arg(long, value_name = "UUID")]
    new_session_id: Option<String>,

    /// Attach a bounded host-captured local Git snapshot to the first turn
    #[arg(long)]
    with_diffs: bool,

    /// Emit redacted child-environment changes after commands in structured headless output
    #[arg(long)]
    printenv: bool,

    /// Select a whole-file run profile (`default`, `bare`, or a named profile)
    #[arg(long, value_name = "NAME")]
    profile: Option<String>,

    /// Start from a saved workspace name or directory path
    #[arg(long, value_name = "PATH_OR_NAME")]
    workspace: Option<String>,

    /// Add a process-only workspace root (repeatable)
    #[arg(long = "add-dir", value_name = "PATH", action = clap::ArgAction::Append)]
    add_dirs: Vec<std::path::PathBuf>,

    /// Load a validated local plugin directory for this process only (repeatable)
    #[arg(long = "plugin-dir", value_name = "DIR", action = clap::ArgAction::Append)]
    plugin_dirs: Vec<std::path::PathBuf>,

    /// Evaluate the primary workspace's .envrc for this trusted process only
    #[arg(long)]
    direnv: bool,

    /// Start in plan or ask mode for this process only
    #[arg(long, value_enum, value_name = "MODE", conflicts_with = "plan")]
    mode: Option<LaunchMode>,

    /// Start in plan mode for this process only
    #[arg(long, conflicts_with = "mode")]
    plan: bool,

    /// Override the configured sandbox for this process only
    #[arg(long, value_enum, value_name = "MODE")]
    sandbox: Option<sandbox::SandboxMode>,

    /// Trust the fresh workspace for this headless process only
    #[arg(long)]
    trust: bool,

    /// Create and launch in a registered worktree (optional name requires '=')
    #[arg(
        long,
        value_name = "NAME",
        num_args = 0..=1,
        require_equals = true,
        default_missing_value = "launch"
    )]
    worktree: Option<String>,

    /// Select the Git base for a launch-created worktree
    #[arg(long, value_name = "REF", requires = "worktree")]
    worktree_base: Option<String>,

    /// Skip repository-defined setup for the launch-created worktree
    #[arg(long, requires = "worktree", conflicts_with = "worktree_setup_digest")]
    skip_worktree_setup: bool,

    /// Authorize the exact headless worktree setup preview
    #[arg(long, value_name = "SHA256", requires = "worktree")]
    worktree_setup_digest: Option<String>,

    /// Start one exact managed GGUF for this process-only run
    #[arg(long, value_name = "MODEL_ID", requires = "local_runtime")]
    local_model: Option<String>,

    /// Select the exact managed runtime containing the llama-server entrypoint
    #[arg(long, value_name = "RUNTIME_ID", requires = "local_model")]
    local_runtime: Option<String>,

    /// Context size for an explicitly managed local run
    #[arg(long, default_value_t = 4096, value_parser = clap::value_parser!(u32).range(512..=1_048_576))]
    local_context_size: u32,

    /// Maximum seconds to wait for an explicitly managed local server
    #[arg(long, default_value_t = 300, value_parser = clap::value_parser!(u64).range(1..=600))]
    local_startup_timeout: u64,

    /// One-shot prompt and optional @path attachments
    #[arg(value_name = "PROMPT_OR_@FILE")]
    positional: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
enum LaunchMode {
    Plan,
    Ask,
}

impl LaunchMode {
    fn agent_mode(self) -> AgentMode {
        match self {
            Self::Plan => AgentMode::Plan,
            Self::Ask => AgentMode::Ask,
        }
    }

    fn tool_profile(self) -> agent::registry::ToolProfile {
        match self {
            Self::Plan => agent::registry::ToolProfile::Plan,
            Self::Ask => agent::registry::ToolProfile::Main,
        }
    }
}

