                            evidence.reason_codes = diagnosis.reason_codes.clone();
                            evidence.failure_cause = diagnosis.failure_cause.clone();
                            evidence.package = diagnosis.package.clone();
                            evidence.target = diagnosis.target.clone();
                            evidence.selected_paths = diagnosis.likely_responsible_paths.clone();
