enum UiSaveRequest {
    Theme(ui_settings::UiTheme),
    Notification(ui_settings::NotificationStyle),
    Mouse(ui_settings::MouseMode),
    CommandOutput(config::CommandOutputPolicy),
    Delegation(Option<config::DelegationRoute>),
    DelegationMode(config::DelegationMode),
    Statusline(ui_settings::StatuslineUpdate),
    RoutePreset {
        name: String,
        preset: config::RoutePreset,
    },
}

struct UiSaveSuccess {
    config: CaConfig,
    request: UiSaveRequest,
}

type UiSaveResult = Result<UiSaveSuccess, String>;

fn perform_ui_save(config_store: &ConfigStore, request: UiSaveRequest) -> UiSaveResult {
    match &request {
        UiSaveRequest::Theme(theme) => config_store.update_ui_theme(*theme),
        UiSaveRequest::Notification(notification) => {
            config_store.update_notification(*notification)
        }
        UiSaveRequest::Mouse(mouse) => config_store.update_mouse(*mouse),
        UiSaveRequest::CommandOutput(policy) => config_store.update_command_output(*policy),
        UiSaveRequest::Delegation(route) => config_store.update_delegation_route(route.as_ref()),
        UiSaveRequest::DelegationMode(mode) => config_store.update_delegation_mode(*mode),
        UiSaveRequest::Statusline(update) => config_store.update_statusline(update),
        UiSaveRequest::RoutePreset { name, preset } => {
            config_store.update_route_preset(name, preset)
        }
    }
    .map_err(|error| error.to_string())?;
    let config = config_store
        .load()
        .map_err(|error| format!("saved, but could not reload config: {error}"))?;
    Ok(UiSaveSuccess { config, request })
}

fn start_ui_save(
    config_store: ConfigStore,
    tx: mpsc::UnboundedSender<StreamMsg>,
    request: UiSaveRequest,
) -> tokio::task::JoinHandle<()> {
    tokio::task::spawn_blocking(move || {
        let result = perform_ui_save(&config_store, request);
        let _ = tx.send(StreamMsg::UiSaved(Box::new(result)));
    })
}

fn apply_ui_save_result(state: &mut AppState, config: &mut CaConfig, result: UiSaveResult) {
    match result {
        Ok(saved) => {
            *config = saved.config;
            match saved.request {
                UiSaveRequest::Theme(theme) => {
                    state.ui_theme = theme;
                    state.terminal_theme_auto = false;
                    state.terminal_appearance = None;
                    state.theme_manager = None;
                    state.status_message = Some(format!("Theme saved: {}", theme.label()));
                }
                UiSaveRequest::Notification(notification) => {
                    state.notification_style = notification;
                    state.notification_picker = None;
                    state.status_message = Some(format!(
                        "Completion notification saved: {}",
                        notification.label()
                    ));
                }
                UiSaveRequest::Mouse(mouse) => {
                    state.mouse_mode = mouse;
                    state.status_message =
                        Some(format!("Trackpad scrolling saved: {}", mouse.label()));
                }
                UiSaveRequest::CommandOutput(policy) => {
                    state.command_output_policy = policy;
                    state.command_output_picker = None;
                    state.status_message =
                        Some(format!("Command output saved: {}", policy.label()));
                }
                UiSaveRequest::Delegation(route) => {
                    if let Some(manager) = &state.agents {
                        configure_agent_delegation(manager, config);
                    }
                    state.status_message = Some(route.map_or_else(
                        || "Delegated agent saved: same as current agent".into(),
                        |route| {
                            format!("Delegated agent saved: {}/{}", route.provider, route.model)
                        },
                    ));
                }
                UiSaveRequest::DelegationMode(mode) => {
                    if let Some(manager) = &state.agents {
                        configure_agent_delegation(manager, config);
                    }
                    state.status_message =
                        Some(format!("Delegation policy saved: {}", mode.label()));
                }
                UiSaveRequest::Statusline(_) => {
                    state.statusline_fields = config.ui.statusline.fields.clone();
                    state.statusline_custom_configured =
                        config.ui.statusline.custom_command.is_some();
                    state.statusline_custom_enabled = config.ui.statusline.custom_enabled
                        && !matches!(state.active_profile, runtime::ActiveProfile::Bare);
                    state.statusline_refresh_secs = config.ui.statusline.refresh_secs;
                    state.status_command.output = None;
                    state.status_command.error = None;
                    state.status_command.requested = state.statusline_custom_enabled
                        && state
                            .statusline_fields
                            .contains(&ui_settings::StatusField::Custom);
                    state.statusline_manager = None;
                    state.status_message = Some("Statusline saved".into());
                }
                UiSaveRequest::RoutePreset { name, .. } => {
                    state.route_preset_overwrite = None;
                    state.status_message = Some(format!("Route preset saved: {name}"));
                }
            }
        }
        Err(error) => {
            if let Some(manager) = state.theme_manager.as_mut() {
                manager.busy = false;
                manager.notice = None;
                manager.error = Some(format!("Could not save theme: {error}"));
            }
            if let Some(manager) = state.statusline_manager.as_mut() {
                manager.busy = false;
                manager.notice = None;
                manager.error = Some(format!("Could not save statusline: {error}"));
            }
            if let Some(picker) = state.notification_picker.as_mut() {
                picker.busy = false;
                picker.error = Some(format!("Could not save notification setting: {error}"));
            }
            if let Some(picker) = state.command_output_picker.as_mut() {
                picker.busy = false;
                picker.error = Some(format!("Could not save command output: {error}"));
            }
            if let Some(confirmation) = state.route_preset_overwrite.as_mut() {
                confirmation.busy = false;
                confirmation.save_selected = false;
                confirmation.error = Some(format!("Could not save route preset: {error}"));
            } else if state.status_message.as_deref() == Some("Saving route preset…") {
                state.status_message = Some(format!("Could not save route preset: {error}"));
            } else {
                state.status_message = Some(format!("Could not save setting: {error}"));
            }
        }
    }
}

fn apply_status_command_result(
    state: &mut AppState,
    generation: u64,
    result: Result<ui_settings::StatusCommandOutput, ui_settings::StatusCommandError>,
) -> bool {
    if generation != state.status_command.generation {
        return false;
    }
    state.status_command.running = false;
    match result {
        Ok(output) => {
            state.status_command.output = Some(output.text);
            state.status_command.error = None;
            if let Some(manager) = state.statusline_manager.as_mut() {
                manager.testing = false;
                manager.error = None;
                manager.notice = Some(if output.truncated {
                    "Custom status succeeded; output was bounded".into()
                } else {
                    "Custom status succeeded".into()
                });
            }
        }
        Err(error) => {
            let safe = error.to_string();
            state.status_command.output = None;
            state.status_command.error = Some(safe.clone());
            if let Some(manager) = state.statusline_manager.as_mut() {
                manager.testing = false;
                manager.notice = None;
                manager.error = Some(safe);
            }
        }
    }
    true
}

fn perform_sandbox_save(
    config_store: &ConfigStore,
    mode: sandbox::SandboxMode,
) -> SandboxSaveResult {
    config_store
        .update_sandbox_mode(mode)
        .map_err(|error| error.to_string())?;
    let config = config_store
        .load()
        .map_err(|error| format!("saved, but could not reload config: {error}"))?;
    Ok(SandboxSaveSuccess { config, mode })
}

fn apply_sandbox_save_result(
    state: &mut AppState,
    config: &mut CaConfig,
    result: SandboxSaveResult,
) {
    let Some(hub) = state.sandbox_hub.as_mut() else {
        return;
    };
    hub.busy = false;
    match result {
        Ok(saved) => {
            *config = saved.config;
            hub.saved_mode = saved.mode;
            hub.selected_idx = crate::app::SandboxHubState::MODES
                .iter()
                .position(|mode| *mode == saved.mode)
                .unwrap_or(0);
            hub.confirmation = None;
            hub.error = None;
            hub.notice = Some(format!(
                "Saved {}. Restart ca to make it effective",
                saved.mode
            ));
        }
        Err(error) => {
            hub.notice = None;
            hub.error = Some(format!("Could not save sandbox mode: {error}"));
        }
    }
}

