fn execute_scratch_command(state: &mut AppState, arguments: &str) {
    let Some(store) = scratch::active_store() else {
        state.status_message = Some("Project scratch is unavailable".into());
        return;
    };
    let trimmed = arguments.trim();
    if trimmed.is_empty() {
        match store.render(None) {
            Ok(report) => {
                state.pager_content = report;
                state.pager_scroll = 0;
                state.pager_open = true;
            }
            Err(error) => state.status_message = Some(error),
        }
        return;
    }
    if !store.writable() {
        state.status_message = Some("Scratch persistence is unavailable in bare mode".into());
        return;
    }
    let (verb, rest) = trimmed.split_once(' ').unwrap_or((trimmed, ""));
    let result = match verb {
        "note" => store.add_text(scratch::ScratchCategory::Note, rest).map(|_| ()),
        "todo" => store.add_text(scratch::ScratchCategory::Todo, rest).map(|_| ()),
        "edit" => rest
            .split_once(' ')
            .ok_or_else(|| "Usage: /scratch edit <id> <text>".to_string())
            .and_then(|(id, text)| uuid::Uuid::parse_str(id).map_err(|_| "invalid scratch ID".to_string()).and_then(|id| store.edit(id, text))),
        "toggle" => uuid::Uuid::parse_str(rest)
            .map_err(|_| "Usage: /scratch toggle <id>".to_string())
            .and_then(|id| store.toggle(id)),
        "plan" if rest.is_empty() => {
            let plan = state.work_state.lock().unwrap_or_else(|e| e.into_inner()).plan.clone();
            plan.ok_or_else(|| "No current session plan is available".to_string())
                .and_then(|plan| store.save_plan(&plan.id.to_string(), plan.revision).map(|_| ()))
        }
        "delete" => match uuid::Uuid::parse_str(rest) {
            Ok(id) => {
                if store.load().is_ok_and(|entries| entries.iter().any(|entry| entry.id == id)) {
                    state.scratch_delete_confirmation = Some(crate::app::ScratchDeleteConfirmation { id, delete_selected: false, error: None });
                    return;
                }
                Err("scratch entry was not found".into())
            }
            Err(_) => Err("Usage: /scratch delete <id>".into()),
        },
        _ => Err("Usage: /scratch [note <text>|todo <text>|edit <id> <text>|toggle <id>|plan|delete <id>]".into()),
    };
    state.status_message = Some(match result {
        Ok(()) => "Project scratch updated".into(),
        Err(error) => error,
    });
}

