fn permission_manager_entries(
    config: &CaConfig,
    grants: &crate::permission::SessionGrantStore,
) -> Vec<crate::app::PermissionManagerEntry> {
    let mut entries = Vec::new();
    for (index, rule) in config.approval_rules.iter().enumerate() {
        let (decision, matcher) = match rule {
            config::ApprovalRule::AllowTool(tool) => {
                (crate::permission::PermissionDecision::Allow, tool.clone())
            }
            config::ApprovalRule::DenyTool(tool) => {
                (crate::permission::PermissionDecision::Deny, tool.clone())
            }
            config::ApprovalRule::AllowPath { tool, path_pattern } => (
                crate::permission::PermissionDecision::Allow,
                format!("{tool} · {path_pattern}"),
            ),
            config::ApprovalRule::DenyPath { tool, path_pattern } => (
                crate::permission::PermissionDecision::Deny,
                format!("{tool} · {path_pattern}"),
            ),
        };
        entries.push(crate::app::PermissionManagerEntry {
            source: crate::app::PermissionEntrySource::Legacy(index),
            decision,
            matcher,
        });
    }
    entries.extend(
        config
            .permission_rules
            .iter()
            .enumerate()
            .map(|(index, rule)| crate::app::PermissionManagerEntry {
                source: crate::app::PermissionEntrySource::Rich(index),
                decision: rule.decision,
                matcher: rule.matcher.safe_label(),
            }),
    );
    entries.extend(grants.grants().iter().enumerate().map(|(index, matcher)| {
        crate::app::PermissionManagerEntry {
            source: crate::app::PermissionEntrySource::Session(index),
            decision: crate::permission::PermissionDecision::Allow,
            matcher: matcher.safe_label(),
        }
    }));
    entries
}

fn open_permission_manager(state: &mut AppState, config: &CaConfig, filter: String) {
    if filter.trim() == "why" {
        state.permission_manager = None;
        state.pager_content = approval::render_recent_explanations();
        state.pager_scroll = 0;
        state.pager_selection = Default::default();
        state.pager_open = true;
        return;
    }
    state.permission_manager_generation = state.permission_manager_generation.wrapping_add(1);
    state.permission_manager = Some(crate::app::PermissionManagerState {
        filter,
        selected_idx: 0,
        entries: permission_manager_entries(
            config,
            &state
                .session_grants
                .lock()
                .unwrap_or_else(|poison| poison.into_inner()),
        ),
        confirmation: None,
        busy: false,
        writes_enabled: state.run_capabilities.config_writes,
        generation: state.permission_manager_generation,
        error: None,
        notice: None,
    });
}

