async fn run_privilege_post_hook(
    invocation: &crate::privilege::PreparedPrivilegeInvocation,
    execution: &crate::agent::registry::ToolExecutionResult,
    hook_runner: &hooks::HookRunner,
    session_id: Option<&str>,
) {
    let event = if execution.is_success() {
        hooks::HookEvent::PostToolUse
    } else {
        hooks::HookEvent::PostToolUseFailure
    };
    let mut extra = invocation.hook_metadata();
    if let Some(object) = extra.as_object_mut() {
        object.insert(
            "tool_result".into(),
            serde_json::Value::String(execution.model_text().into()),
        );
    }
    let payload = hooks::HookPayload {
        hook_event_name: event.as_str().into(),
        session_id: session_id.map(str::to_string),
        cwd: invocation.cwd.to_string_lossy().into_owned(),
        extra,
    };
    let _ = hook_runner
        .run_event(&hook_runner.owner(), event, &payload, &invocation.roots)
        .await;
}

async fn execute_privilege_after_secret(
    invocation: crate::privilege::PreparedPrivilegeInvocation,
    secret: crate::interaction::SecretHandle,
    owner: jobs::JobOwner,
    timeout_secs: u64,
    hook_runner: &hooks::HookRunner,
    session_id: Option<&str>,
) -> crate::agent::registry::ToolExecutionResult {
    let execution = match crate::privilege::authenticate(&invocation, owner, secret).await {
        Ok(pattern) => {
            crate::privilege::execute(
                &invocation,
                owner,
                std::time::Duration::from_secs(timeout_secs),
                Some(pattern),
            )
            .await
        }
        Err(error) => crate::agent::registry::ToolExecutionResult::Failure(error),
    };
    run_privilege_post_hook(&invocation, &execution, hook_runner, session_id).await;
    execution
}

async fn begin_privilege_execution(
    invocation: crate::privilege::PreparedPrivilegeInvocation,
    owner: jobs::JobOwner,
    timeout_secs: u64,
    hook_runner: &hooks::HookRunner,
    session_id: Option<&str>,
) -> Result<
    crate::agent::registry::ToolExecutionResult,
    crate::privilege::PreparedPrivilegeInvocation,
> {
    if let Err(error) = invocation.revalidate(owner) {
        return Ok(crate::agent::registry::ToolExecutionResult::Failure(error));
    }
    let pre_payload = hooks::HookPayload {
        hook_event_name: hooks::HookEvent::PreToolUse.as_str().into(),
        session_id: session_id.map(str::to_string),
        cwd: invocation.cwd.to_string_lossy().into_owned(),
        extra: invocation.hook_metadata(),
    };
    let pre = hook_runner
        .run_event(
            &hook_runner.owner(),
            hooks::HookEvent::PreToolUse,
            &pre_payload,
            &invocation.roots,
        )
        .await;
    if let Some(reason) = pre.denied {
        return Ok(crate::agent::registry::ToolExecutionResult::Denied(reason));
    }
    match crate::privilege::check_cached_authorization(&invocation, owner).await {
        Ok(crate::privilege::CachedAuthorization::Available) => {
            let execution = crate::privilege::execute(
                &invocation,
                owner,
                std::time::Duration::from_secs(timeout_secs),
                None,
            )
            .await;
            run_privilege_post_hook(&invocation, &execution, hook_runner, session_id).await;
            Ok(execution)
        }
        Ok(crate::privilege::CachedAuthorization::PasswordRequired) => Err(invocation),
        Err(error) => {
            let execution = crate::agent::registry::ToolExecutionResult::Failure(error);
            run_privilege_post_hook(&invocation, &execution, hook_runner, session_id).await;
            Ok(execution)
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn execute_approved_email_dispatch(
    email_manager: Option<&std::sync::Arc<email::EmailManager>>,
    tool_name: &str,
    draft_ref: &str,
    preview: Option<&email::types::ExternalCommunicationPreview>,
    tool_call_id: &str,
    session_id: &str,
    workspace: &workspace::WorkspaceContext,
    hook_runner: &hooks::HookRunner,
) -> crate::agent::registry::ToolExecutionResult {
    let Some(manager) = email_manager else {
        return crate::agent::registry::ToolExecutionResult::Failure(
            "Email manager is unavailable for this run".into(),
        );
    };
    let marker =
        serde_json::from_str::<serde_json::Value>(&email::private_arguments_marker(tool_name))
            .unwrap_or_else(|_| serde_json::json!({"private": true}));
    let hook_metadata = preview
        .and_then(|preview| email::service_approval_metadata(preview).ok())
        .map(|(_, metadata)| {
            serde_json::json!({
                "tool_name": tool_name,
                "email": {
                    "external_private": true,
                    "operation": tool_name.strip_prefix("email_").unwrap_or("email"),
                    "approval": metadata,
                }
            })
        })
        .unwrap_or_else(|| email::metadata_only(tool_name, &marker, None));
    let hook_roots = workspace.execution_roots();
    let pre_payload = hooks::HookPayload {
        hook_event_name: hooks::HookEvent::PreToolUse.as_str().into(),
        session_id: Some(session_id.into()),
        cwd: workspace.cwd().to_string_lossy().to_string(),
        extra: hook_metadata.clone(),
    };
    let pre = hook_runner
        .run_event(
            &hook_runner.owner(),
            hooks::HookEvent::PreToolUse,
            &pre_payload,
            &hook_roots,
        )
        .await;
    if let Some(reason) = pre.denied {
        return crate::agent::registry::ToolExecutionResult::Denied(reason);
    }

    let result = match manager
        .authorize_once(
            draft_ref,
            tool_call_id,
            session_id,
            std::time::Duration::from_secs(120),
        )
        .await
    {
        Ok(nonce) => manager
            .send_approved(
                &email::types::EmailSendArgs {
                    draft_ref: draft_ref.into(),
                },
                &nonce,
                tool_call_id,
                session_id,
            )
            .await
            .map_err(|error| error.to_string()),
        Err(error) => Err(error.to_string()),
    };
    let execution = match result {
        Ok(receipt) => match serde_json::to_string(&receipt) {
            Ok(live) => crate::agent::registry::ToolExecutionResult::ExternalPrivateSuccess {
                live,
                persistent: email::private_result_marker(tool_name),
            },
            Err(_) => crate::agent::registry::ToolExecutionResult::Failure(
                "email receipt serialization failed".into(),
            ),
        },
        Err(error) => crate::agent::registry::ToolExecutionResult::Failure(error),
    };
    let event = if execution.is_success() {
        hooks::HookEvent::PostToolUse
    } else {
        hooks::HookEvent::PostToolUseFailure
    };
    let post_payload = hooks::HookPayload {
        hook_event_name: event.as_str().into(),
        session_id: Some(session_id.into()),
        cwd: workspace.cwd().to_string_lossy().to_string(),
        extra: serde_json::json!({
            "tool_name": tool_name,
            "email": {
                "metadata": hook_metadata.get("email").cloned().unwrap_or_default(),
                "outcome": if execution.is_success() { "success" } else { "failure" },
            }
        }),
    };
    let _ = hook_runner
        .run_event(&hook_runner.owner(), event, &post_payload, &hook_roots)
        .await;
    execution
}

