#[allow(clippy::too_many_arguments)]
async fn execute_tool_dispatch_with_email(
    name: &str,
    arguments: &serde_json::Value,
    workspace: &workspace::WorkspaceContext,
    timeout_secs: u64,
    sandbox_mode: sandbox::SandboxMode,
    network_allowed: bool,
    job_owner: jobs::JobOwner,
    skills: &std::sync::Arc<std::sync::Mutex<skills::SkillRegistry>>,
    work_state: &std::sync::Arc<std::sync::Mutex<work::WorkState>>,
    agents: Option<&std::sync::Arc<agent::subagent::AgentManager>>,
    mcp_manager: Option<&std::sync::Arc<mcp::McpManager>>,
    lsp_manager: Option<&std::sync::Arc<lsp::LspManager>>,
    email_manager: Option<&std::sync::Arc<email::EmailManager>>,
    hook_runner: &hooks::HookRunner,
    session_id: Option<&str>,
) -> crate::agent::registry::ToolExecutionResult {
    let extra = if email::is_email_tool(name) {
        email::metadata_only(name, arguments, None)
    } else {
        serde_json::json!({
            "tool_name": name,
            "tool_input": arguments,
        })
    };
    let payload = hooks::HookPayload {
        hook_event_name: hooks::HookEvent::PreToolUse.as_str().into(),
        session_id: session_id.map(str::to_string),
        cwd: workspace.cwd().to_string_lossy().to_string(),
        extra,
    };
    let hook_roots = workspace.execution_roots();
    let pre = hook_runner
        .run_event(
            &hook_runner.owner(),
            hooks::HookEvent::PreToolUse,
            &payload,
            &hook_roots,
        )
        .await;
    if let Some(reason) = pre.denied {
        return crate::agent::registry::ToolExecutionResult::Denied(reason);
    }

    let mut execution = execute_tool_dispatch_unhooked(
        name,
        arguments,
        workspace,
        timeout_secs,
        sandbox_mode,
        network_allowed,
        job_owner,
        skills,
        work_state,
        agents,
        mcp_manager,
        lsp_manager,
        email_manager,
    )
    .await;
    record_plan_workflow_command(name, arguments, &mut execution, work_state);
    let event = if execution.is_success() {
        hooks::HookEvent::PostToolUse
    } else {
        hooks::HookEvent::PostToolUseFailure
    };
    let extra = if email::is_email_tool(name) {
        email::metadata_only(name, arguments, Some(execution.persistent_text()))
    } else {
        serde_json::json!({
            "tool_name": name,
            "tool_input": arguments,
            "tool_result": execution.model_text(),
        })
    };
    let payload = hooks::HookPayload {
        hook_event_name: event.as_str().into(),
        session_id: session_id.map(str::to_string),
        cwd: workspace.cwd().to_string_lossy().to_string(),
        extra,
    };
    let _ = hook_runner
        .run_event(&hook_runner.owner(), event, &payload, &hook_roots)
        .await;
    execution
}

#[allow(clippy::too_many_arguments)]
async fn execute_tool_dispatch_unhooked(
    name: &str,
    arguments: &serde_json::Value,
    workspace: &workspace::WorkspaceContext,
    timeout_secs: u64,
    sandbox_mode: sandbox::SandboxMode,
    network_allowed: bool,
    job_owner: jobs::JobOwner,
    skills: &std::sync::Arc<std::sync::Mutex<skills::SkillRegistry>>,
    work_state: &std::sync::Arc<std::sync::Mutex<work::WorkState>>,
    agents: Option<&std::sync::Arc<agent::subagent::AgentManager>>,
    mcp_manager: Option<&std::sync::Arc<mcp::McpManager>>,
    lsp_manager: Option<&std::sync::Arc<lsp::LspManager>>,
    email_manager: Option<&std::sync::Arc<email::EmailManager>>,
) -> crate::agent::registry::ToolExecutionResult {
    if let Some(discovery) = owned_tools::current_discovery() {
        if name == tool_discovery::SEARCH_TOOLS_NAME {
            return discovery.search(arguments);
        }
        discovery.touch(name);
    } else if name == tool_discovery::SEARCH_TOOLS_NAME {
        return crate::agent::registry::ToolExecutionResult::Failure(
            "Tool discovery requires owned session execution.".into(),
        );
    }
    if name == "list_local_automations" {
        return match owned_tools::current_automation() {
            Some(scope) => automation_ui::list_model_metadata(scope, arguments, timeout_secs).await,
            None => crate::agent::registry::ToolExecutionResult::Failure(
                "Automation metadata requires owned persistent interactive execution.".into(),
            ),
        };
    }
    if name == "plan_workflow" {
        use crate::agent::registry::ToolExecutionResult;
        if agents.is_none() {
            return ToolExecutionResult::Failure(
                "Plan workflows require an active agent manager.".into(),
            );
        }
        let request =
            match serde_json::from_value::<plan_workflow::PlanWorkflowArgs>(arguments.clone()) {
                Ok(request) => request,
                Err(error) => {
                    return ToolExecutionResult::Failure(format!("Invalid plan workflow: {error}"))
                }
            };
        let mut work = work_state
            .lock()
            .unwrap_or_else(|poison| poison.into_inner());
        if matches!(request, plan_workflow::PlanWorkflowArgs::Status) {
            return ToolExecutionResult::Success(work.plan_workflow.as_ref().map_or_else(
                || "No plan workflow. Use plan_workflow action=start to create one.".into(),
                |workflow| {
                    serde_json::to_string(workflow)
                        .unwrap_or_else(|_| "Plan workflow status unavailable.".into())
                },
            ));
        }
        if work.pending_plan_workflow.is_some() {
            return ToolExecutionResult::Failure("A plan workflow action is already queued. Finish this reply so the host can apply it.".into());
        }
        let Some(source) = owned_tools::current_plan_workflow_source() else {
            return ToolExecutionResult::Failure(
                "Plan workflow control requires an originating interactive user turn.".into(),
            );
        };
        work.pending_plan_workflow = Some(plan_workflow::PendingPlanWorkflow {
            args: request,
            source,
        });
        return ToolExecutionResult::Success("Plan workflow action queued. Finish this reply now; the host will save and run the requested stages. Inspect progress with /plan graph.".into());
    }
    if let Some(result) = work::execute_model_tool(name, arguments, work_state) {
        return result
            .map(crate::agent::registry::ToolExecutionResult::Success)
            .unwrap_or_else(|error| {
                crate::agent::registry::ToolExecutionResult::Failure(error.to_string())
            });
    }
    if let Some(manager) = agents {
        if let Some(result) =
            agent::subagent::execute_manager_tool(name, arguments, manager, work_state, workspace)
                .await
        {
            return result;
        }
    }
    if let Some(manager) = mcp_manager.filter(|manager| {
        manager.mechanistic_config().enabled
            && mechanistic_delegation::is_transparent_tool(name)
            && (manager.mechanistic_config().transparent_routing
                || mechanistic_delegation::is_automation_setup_tool(name))
    }) {
        let request = mechanistic_delegation::TransparentToolRequest {
            name: name.to_string(),
            arguments: arguments.clone(),
        };
        match mechanistic_delegation::execute_transparent_batch(
            manager.clone(),
            std::slice::from_ref(&request),
            manager.mechanistic_config().allow_unisolated_evidence,
        )
        .await
        {
            Ok(mut batch) => {
                if let Some(capsule) = batch.capsule.as_ref() {
                    let _ = mechanistic_delegation::record_process_event(
                        mechanistic_delegation::MechanisticProcessEvent {
                            kind:
                                mechanistic_delegation::MechanisticEventKind::DelegationCompletion,
                            origin: &capsule.digest,
                            revision: Some(&capsule.revision),
                            action_digest: Some(&capsule.action_digest),
                        },
                    );
                }
                return batch.executions.pop().unwrap_or_else(|| {
                    crate::agent::registry::ToolExecutionResult::Failure(
                        "Mechanistic routing returned no tool result".into(),
                    )
                });
            }
            Err(mechanistic_delegation::TransparentRoutingError::Ineligible) => {
                return crate::agent::registry::ToolExecutionResult::Failure(
                    "Transparent routing refused an argument outside codex-team's pinned repository"
                        .into(),
                );
            }
            Err(mechanistic_delegation::TransparentRoutingError::Unavailable {
                message,
                binding,
            }) => {
                let ordinary_fallback =
                    matches!(name, "read_file" | "search_files" | "list_dir" | "glob")
                        && binding.as_ref().is_some_and(|binding| {
                            mechanistic_delegation::binding_matches_workspace(binding, workspace)
                        });
                if !ordinary_fallback {
                    return crate::agent::registry::ToolExecutionResult::Failure(message);
                }
                mechanistic_delegation::mark_transparent_routing_degraded(&message);
            }
            Err(mechanistic_delegation::TransparentRoutingError::Invalid(message)) => {
                return crate::agent::registry::ToolExecutionResult::Failure(message);
            }
        }
    }
    if name == "delegate_mechanistic" {
        let Some(manager) = mcp_manager else {
            return crate::agent::registry::ToolExecutionResult::Failure(
                "Mechanistic delegation is unavailable for this run".into(),
            );
        };
        return mechanistic_delegation::execute(manager.clone(), arguments).await;
    }
    if name == "search_mcp_tools" {
        let Some(manager) = mcp_manager else {
            return crate::agent::registry::ToolExecutionResult::Failure(
                "MCP discovery is unavailable for this run".into(),
            );
        };
        let query = arguments
            .get("query")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        let server = arguments.get("server").and_then(serde_json::Value::as_str);
        let limit = arguments
            .get("limit")
            .and_then(serde_json::Value::as_u64)
            .and_then(|value| usize::try_from(value).ok())
            .unwrap_or(5);
        return manager.search_tools(query, server, limit).await;
    }
    if let Some(manager) = mcp_manager {
        if manager.has_active_tool(name).await {
            return manager
                .call_tool(name, arguments.clone())
                .await
                .unwrap_or_else(|error| {
                    crate::agent::registry::ToolExecutionResult::Failure(error.to_string())
                });
        }
    }
    if lsp::is_lsp_tool(name) {
        let Some(manager) = lsp_manager else {
            return crate::agent::registry::ToolExecutionResult::Failure(
                "LSP navigation is unavailable for this run".into(),
            );
        };
        manager.update_workspace(workspace.clone()).await;
        return manager.execute(name, arguments).await;
    }
    if email::is_email_tool(name) {
        let Some(manager) = email_manager else {
            return crate::agent::registry::ToolExecutionResult::Failure(
                "Email manager is unavailable for this run".into(),
            );
        };
        if email::is_outbound_tool(name) {
            return crate::agent::registry::ToolExecutionResult::Failure(
                "Exact external-communication approval is required".into(),
            );
        }
        return manager.execute_read_or_draft(name, arguments).await;
    }
    let mut result = agent::tools::execute_prepared_tool_in_workspace_policy_owned_with_skills(
        name,
        arguments,
        workspace,
        timeout_secs,
        sandbox_mode,
        network_allowed,
        job_owner,
        skills,
    )
    .await;
    if let Some(receipt) = result.mutation().cloned() {
        let diagnostics = if let Some(manager) = lsp_manager {
            manager.update_workspace(workspace.clone()).await;
            manager
                .diagnostics_after_mutation(&receipt)
                .await
                .into_report()
        } else {
            None
        };
        if let Some(diagnostics) = diagnostics {
            append_mutation_diagnostics(&mut result, &diagnostics);
        }
    }
    result
}

fn record_plan_workflow_command(
    name: &str,
    arguments: &serde_json::Value,
    result: &mut crate::agent::registry::ToolExecutionResult,
    work_state: &std::sync::Arc<std::sync::Mutex<work::WorkState>>,
) {
    if name != "run_command" {
        return;
    }
    let mut work = work_state
        .lock()
        .unwrap_or_else(|poison| poison.into_inner());
    if plan_workflow_runtime::implementation_active(&work).is_none() {
        return;
    }
    if let crate::agent::registry::ToolExecutionResult::Command {
        model_text,
        success,
        ..
    } = result
    {
        let command = arguments
            .get("command")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("run_command");
        let kind = if command.contains("test") {
            work::WorkEventKind::Test
        } else {
            work::WorkEventKind::Command
        };
        let event_id = work.record_event(kind, command, *success);
        model_text.push_str(&format!("\nrecorded_event_id: {event_id}"));
    }
}

fn append_mutation_diagnostics(
    result: &mut crate::agent::registry::ToolExecutionResult,
    diagnostics: &str,
) {
    if let crate::agent::registry::ToolExecutionResult::SuccessMutation { marker, .. } = result {
        marker.push_str("\n\n");
        marker.push_str(diagnostics);
    }
}

fn activate_next_manual_resolution(
    state: &mut AppState,
    config: &CaConfig,
    stream_tx: &mpsc::UnboundedSender<StreamMsg>,
    cancel_handle: &mut Option<tokio::task::JoinHandle<()>>,
) {
    loop {
        state.approval_queue.clear();
        state.interaction = None;
        state.pending_privilege_secret = None;
        match state.manual_resolutions.current().cloned() {
            Some(crate::interaction::PendingManualResolution::Approval(approval)) => {
                let focused = state
                    .pane_deck
                    .as_ref()
                    .is_none_or(|deck| deck.focused() == state.pane_id);
                if focused {
                    if let Some(execution) = reclassify_pending_approval(state, config, &approval) {
                        state.manual_resolutions.replace_current(
                            crate::interaction::PendingManualResolution::Execution(execution),
                        );
                        continue;
                    }
                }
                state
                    .turn_lifecycle
                    .set_phase(activity::ActivityPhase::Interaction);
                state.approval_queue.begin_batch(vec![approval]);
                let (resolved, total) = state.manual_resolutions.progress();
                state.status_message = Some(format!(
                    "Tool needs approval [{}/{}] (y/n/a/g/s/x/p)",
                    resolved + 1,
                    total
                ));
                return;
            }
            Some(crate::interaction::PendingManualResolution::Privilege(privilege)) => {
                let privilege = *privilege;
                state
                    .turn_lifecycle
                    .set_phase(activity::ActivityPhase::Interaction);
                state.approval_queue.begin_batch(vec![PendingApproval {
                    tool_name: crate::privilege::TOOL_NAME.into(),
                    tool_args: privilege.tool_args,
                    tool_id: privilege.tool_id,
                    network_requested: false,
                    email_preview: None,
                    email_draft_ref: None,
                }]);
                let (resolved, total) = state.manual_resolutions.progress();
                state.status_message = Some(format!(
                    "Administrator approval required [{}/{}] (y/n)",
                    resolved + 1,
                    total
                ));
                return;
            }
            Some(crate::interaction::PendingManualResolution::Interaction(interaction)) => {
                state
                    .turn_lifecycle
                    .set_phase(activity::ActivityPhase::Interaction);
                let (resolved, total) = state.manual_resolutions.progress();
                state.interaction = Some(crate::interaction::InteractionState::from_pending(
                    interaction,
                ));
                state.status_message = Some(format!("Input required [{}/{}]", resolved + 1, total));
                return;
            }
            Some(crate::interaction::PendingManualResolution::Execution(execution)) => {
                let focused = state
                    .pane_deck
                    .as_ref()
                    .is_none_or(|deck| deck.focused() == state.pane_id);
                if !focused
                    && execution.pre_resolved.is_none()
                    && pane_execution_requires_focus(&execution)
                {
                    state.manual_resolutions.replace_current(
                        crate::interaction::PendingManualResolution::Approval(PendingApproval {
                            tool_name: execution.tool_name,
                            tool_args: execution.tool_args,
                            tool_id: execution.tool_id,
                            network_requested: execution.network_allowed,
                            email_preview: None,
                            email_draft_ref: None,
                        }),
                    );
                    continue;
                }
                state
                    .turn_lifecycle
                    .set_phase(activity::ActivityPhase::Tool);
                if let Some(result) = execution.pre_resolved {
                    observe_execution_for_loop_guard_with_call(
                        state,
                        &execution.tool_name,
                        &execution.tool_args,
                        &result,
                    );
                    apply_execution_result(
                        state,
                        &execution.tool_id,
                        &result,
                        if result.is_success() {
                            ToolStatus::Done
                        } else {
                            ToolStatus::Error
                        },
                    );
                    state.manual_resolutions.resolve_tool(&execution.tool_id);
                    continue;
                }
                let (resolved, total) = state.manual_resolutions.progress();
                state.status_message = Some(format!(
                    "Executing {} [{}/{}]…",
                    execution.tool_name,
                    resolved + 1,
                    total
                ));
                let _ = stream_tx.send(StreamMsg::ExecuteOrderedTool(
                    execution,
                    state.stream_generation,
                ));
                return;
            }
            None => {
                continue_after_tool_resolutions(state, config, stream_tx, cancel_handle);
                return;
            }
        }
    }
}

fn pane_execution_requires_focus(execution: &crate::interaction::PendingExecution) -> bool {
    execution.network_allowed
        || crate::agent::registry::ToolRegistry::builtins()
            .get(&execution.tool_name)
            .is_none_or(|spec| {
                spec.mutation == crate::agent::registry::ToolMutation::Mutating
                    || spec
                        .capabilities
                        .contains(&crate::agent::registry::ToolCapability::Network)
            })
}

fn reclassify_pending_approval(
    state: &AppState,
    config: &CaConfig,
    approval: &PendingApproval,
) -> Option<crate::interaction::PendingExecution> {
    if approval.email_draft_ref.is_some() {
        return None;
    }
    let arguments = match serde_json::from_str::<serde_json::Value>(&approval.tool_args) {
        Ok(arguments) => arguments,
        Err(_) => {
            return Some(crate::interaction::PendingExecution {
                tool_name: approval.tool_name.clone(),
                tool_args: approval.tool_args.clone(),
                tool_id: approval.tool_id.clone(),
                network_allowed: false,
                pre_resolved: Some(crate::agent::registry::ToolExecutionResult::Failure(
                    "Prepared tool arguments became invalid".into(),
                )),
            })
        }
    };
    let grants = state
        .session_grants
        .lock()
        .unwrap_or_else(|poison| poison.into_inner());
    let broker = crate::approval::ApprovalBroker::with_policy(
        &state.workspace,
        &config.approval_rules,
        &config.permission_rules,
        grants.grants(),
        crate::approval::ApprovalOrigin::Main,
    )
    .with_caller(crate::approval::DecisionCaller::Interactive);
    let (_, decision) = broker.prepare_dynamic(
        &approval.tool_name,
        &arguments,
        agent::registry::ToolOrigin::BuiltIn,
        false,
    );
    let pre_resolved = match decision {
        crate::approval::BrokerDecision::DeniedByRule => {
            Some(crate::agent::registry::ToolExecutionResult::Denied(
                "Denied by current permission rule".into(),
            ))
        }
        crate::approval::BrokerDecision::AllowedByRule => None,
        crate::approval::BrokerDecision::Prompt
            if !tool_needs_approval(&approval.tool_name, &arguments, &state.approval) =>
        {
            None
        }
        crate::approval::BrokerDecision::Prompt
        | crate::approval::BrokerDecision::ExplicitPrompt
        | crate::approval::BrokerDecision::NetworkPrompt => return None,
    };
    Some(crate::interaction::PendingExecution {
        tool_name: approval.tool_name.clone(),
        tool_args: approval.tool_args.clone(),
        tool_id: approval.tool_id.clone(),
        network_allowed: approval.network_requested,
        pre_resolved,
    })
}

fn continue_after_tool_resolutions(
    state: &mut AppState,
    config: &CaConfig,
    stream_tx: &mpsc::UnboundedSender<StreamMsg>,
    cancel_handle: &mut Option<tokio::task::JoinHandle<()>>,
) {
    if let Some(batch) = state.discovery_batch.take() {
        batch.commit();
        if let Some(prompt) = state.active_turn_prompt.as_mut() {
            // Resolve the next request's schemas; recovery retries keep their own frozen copy.
            prompt.canonical_tools = None;
        }
    }
    state.manual_resolutions.clear();
    let switch_output = state.messages.last().and_then(|last| {
        last.tool_calls.as_ref().and_then(|calls| {
            calls.iter().find_map(|call| {
                call.output
                    .as_ref()
                    .filter(|output| output.starts_with("[SWITCH_MODE:"))
                    .cloned()
            })
        })
    });
    if let Some(output) = switch_output {
        let mode = output
            .trim_start_matches("[SWITCH_MODE:")
            .trim_end_matches(']');
        state.mode = match mode {
            "plan" => AgentMode::Plan,
            "ask" => AgentMode::Ask,
            "debug" => AgentMode::Debug,
            "agent" => AgentMode::Agent,
            name => AgentMode::Custom(name.to_string()),
        };
        if let Some(calls) = state
            .messages
            .last_mut()
            .and_then(|message| message.tool_calls.as_mut())
        {
            for call in calls {
                if call.output.as_deref() == Some(output.as_str()) {
                    call.output = Some(format!("Switched to {mode} mode"));
                }
            }
        }
    }
    if pause_for_loop_guard_incident(state) {
        return;
    }
    if let Some(reason) = mechanistic_delegation::transparent_routing_degraded_reason() {
        state.active_turn_route = None;
        state.soft_pause.clear();
        state.turn_lifecycle.fail();
        state.outcome_tracker.record_failure();
        state.retry_boundary = provider_failure_retry_boundary(state);
        state.status_message = Some(format!(
            "Paused: a safe local result was preserved, but codex-team routing must recover before the model continues ({reason})"
        ));
        finish_active_prompt_epoch(state);
        return;
    }
    let verification_candidate =
        !state.mechanistic_changed_paths.is_empty() || state.mechanistic_unscoped_mutation;
    if verification_candidate
        && config.mcp.mechanistic.automatic_verification
        && mechanistic_delegation_guidance_enabled(state, config)
    {
        let event_digest = mechanistic_delegation::mechanistic_event_digest(&(
            &state.mechanistic_changed_paths,
            state.mechanistic_unscoped_mutation,
            &state.mechanistic_repository_revision_before,
        ));
        let _ = mechanistic_delegation::record_process_event(
            mechanistic_delegation::MechanisticProcessEvent {
                kind: mechanistic_delegation::MechanisticEventKind::ResolvedEditBatch,
                origin: "main-tool-batch",
                revision: state.mechanistic_repository_revision_before.as_deref(),
                action_digest: event_digest.as_deref(),
            },
        );
        if state.mechanistic_verification_suppressed {
            state.mechanistic_changed_paths.clear();
            state.mechanistic_unscoped_mutation = false;
            state.mechanistic_repository_revision_before = None;
            state.mechanistic_verification_context =
                Some(mechanistic_delegation::skipped_verification_context(
                    "the user explicitly suppressed tests or codex-team automation",
                ));
            state.status_message =
                Some("Automatic verification skipped by explicit instruction".into());
        } else if let Some(manager) = state.mcp.clone() {
            let unscoped = state.mechanistic_unscoped_mutation;
            let exact_paths = std::mem::take(&mut state.mechanistic_changed_paths)
                .into_iter()
                .collect::<Vec<_>>();
            let paths = if unscoped { Vec::new() } else { exact_paths };
            let revision_before = state.mechanistic_repository_revision_before.take();
            let mut evidence = mechanistic_delegation::EvidenceLedgerEntry::simple(
                "verification",
                "running",
                if unscoped {
                    "unscoped_revision_change"
                } else {
                    "exact_mutation_paths"
                },
            );
            evidence.selected_paths = paths.clone();
            evidence.repository_revision = revision_before.clone();
            record_mechanistic_evidence(state, evidence);
            state.mechanistic_unscoped_mutation = false;
            state.mechanistic_verification_in_flight = true;
            state.status_message = Some("Codex-team is verifying the completed edits…".into());
            let timeout = std::time::Duration::from_secs(config.mcp.mechanistic.max_wait_seconds);
            let allow_unisolated_evidence = config.mcp.mechanistic.allow_unisolated_evidence;
            let allow_unscoped_full = state.mechanistic_release_requested
                || config.mcp.mechanistic.full_suite
                    == config::MechanisticFullSuitePolicy::ReleaseOrUnscoped;
            let generation = state.stream_generation;
            let tx = stream_tx.clone();
            let handle = tokio::spawn(async move {
                let started_tx = tx.clone();
                let started_observer: mechanistic_delegation::JobStartedObserver =
                    std::sync::Arc::new(move |started| {
                        let _ = started_tx
                            .send(StreamMsg::AutomaticVerificationStarted(started, generation));
                    });
                let outcome = mechanistic_delegation::automatic_verification_observed(
                    manager,
                    paths,
                    revision_before,
                    timeout,
                    allow_unisolated_evidence,
                    allow_unscoped_full,
                    Some(started_observer),
                )
                .await;
                let _ = tx.send(StreamMsg::AutomaticVerificationFinished(
                    outcome, generation,
                ));
            });
            *cancel_handle = Some(handle);
            return;
        }
    }
    if state.mechanistic_verification_failed && !verification_candidate {
        block_unresolved_mechanistic_verification(state);
        return;
    }
    if !reach_soft_pause(state, activity::SoftPauseBoundary::Provider) {
        start_llm_turn(state, config, stream_tx, cancel_handle);
    }
}

fn resolved_tool_name<'a>(messages: &'a [Message], tool_id: &str) -> Option<&'a str> {
    messages.iter().rev().find_map(|message| {
        message.tool_calls.as_ref().and_then(|calls| {
            calls
                .iter()
                .find(|call| call.id == tool_id)
                .map(|call| call.name.as_str())
        })
    })
}

fn is_mechanical_exploration_tool(name: &str) -> bool {
    matches!(
        name,
        "delegate_mechanistic"
            | "read_file"
            | "search_files"
            | "search_text"
            | "list_dir"
            | "list_files"
            | "git_status"
            | "git_diff"
            | "git_log"
    )
}

fn block_unresolved_mechanistic_verification(state: &mut AppState) {
    if let Some(checkpoint) = state.mechanistic_checkpoint.as_mut() {
        checkpoint.phase = session::MechanisticCheckpointPhaseV1::Blocked;
        checkpoint.remaining_repair_passes = 0;
    }
    state.active_turn_route = None;
    state.soft_pause.clear();
    state.turn_lifecycle.fail();
    state.outcome_tracker.record_failure();
    state.retry_boundary = provider_failure_retry_boundary(state);
    state.active_turn_start_message_count = None;
    state.status_message = Some(format!(
        "Blocked: codex-team verification did not pass after {} repair continuation{}",
        state.mechanistic_repair_passes,
        if state.mechanistic_repair_passes == 1 {
            ""
        } else {
            "s"
        }
    ));
    if let Some(context) = state.mechanistic_verification_context.as_ref() {
        state.pager_content = context.clone();
        state.pager_scroll = 0;
    }
    finish_active_prompt_epoch(state);
}

fn continue_after_failed_mechanistic_verification(
    state: &mut AppState,
    config: &CaConfig,
    stream_tx: &mpsc::UnboundedSender<StreamMsg>,
    cancel_handle: &mut Option<tokio::task::JoinHandle<()>>,
) {
    state.mechanistic_verification_failed = true;
    if !state.mechanistic_provider_continuation_authorized {
        state.status_message = Some(
            "Duplicate verification failure ignored without another provider continuation".into(),
        );
        return;
    }
    if state.mechanistic_repair_passes < config.mcp.mechanistic.max_repair_passes {
        state.mechanistic_provider_continuation_authorized = false;
        state.mechanistic_preflight_pending_assessment = false;
        state.mechanistic_repair_passes += 1;
        if let Some(checkpoint) = state.mechanistic_checkpoint.as_mut() {
            checkpoint.phase = session::MechanisticCheckpointPhaseV1::RepairPending;
            checkpoint.remaining_repair_passes = config
                .mcp
                .mechanistic
                .max_repair_passes
                .saturating_sub(state.mechanistic_repair_passes);
        }
        let mut evidence = mechanistic_delegation::EvidenceLedgerEntry::simple(
            "repair",
            "provider_continuation",
            "diagnosed_failure_requires_judgment",
        );
        evidence.repair_count = state.mechanistic_repair_passes;
        record_mechanistic_evidence(state, evidence);
        state.status_message = Some(format!(
            "Verification diagnosed · repair pass {}/{}",
            state.mechanistic_repair_passes, config.mcp.mechanistic.max_repair_passes
        ));
        start_llm_turn(state, config, stream_tx, cancel_handle);
    } else {
        block_unresolved_mechanistic_verification(state);
    }
}

fn pause_for_loop_guard_incident(state: &mut AppState) -> bool {
    let Some(incident) = state.pending_loop_incident.take() else {
        return false;
    };
    state
        .soft_pause
        .pause_at(activity::SoftPauseBoundary::Provider);
    state
        .turn_lifecycle
        .set_phase(activity::ActivityPhase::Paused);
    state.loop_guard_interaction = Some(loop_guard::LoopGuardInteraction::new(incident));
    state.outcome_tracker.record_loop_guard_trip();
    state.status_message =
        Some("Low-yield loop paused · choose Replan, Continue, or Cancel".into());
    true
}

fn reset_loop_guard_state(state: &mut AppState) {
    state.loop_guard.reset_for_turn();
    state.pending_loop_incident = None;
    state.loop_guard_interaction = None;
    state.loop_guard_replan_prompt = None;
}

fn cancel_loop_guard_turn(
    state: &mut AppState,
    session_store: &session::SessionStore,
    cancel_handle: &mut Option<tokio::task::JoinHandle<()>>,
    approval_task_handle: &mut Option<tokio::task::JoinHandle<()>>,
    tool_task_handle: &mut Option<tokio::task::JoinHandle<()>>,
    goal_task_handle: &mut Option<tokio::task::JoinHandle<()>>,
) {
    stop_active_turn(
        state,
        session_store,
        TurnTaskHandles {
            stream: cancel_handle,
            tools: tool_task_handle,
            approval: approval_task_handle,
            goal: goal_task_handle,
        },
    );
}

fn reach_soft_pause(state: &mut AppState, boundary: activity::SoftPauseBoundary) -> bool {
    if !state.soft_pause.reach(boundary) {
        return false;
    }
    state
        .turn_lifecycle
        .set_phase(activity::ActivityPhase::Paused);
    state.status_message = Some(match boundary {
        activity::SoftPauseBoundary::Tools => {
            "Paused before tools · /unpause · Ctrl+C cancel".into()
        }
        activity::SoftPauseBoundary::Provider => {
            "Paused before provider · /unpause · Ctrl+C cancel".into()
        }
        activity::SoftPauseBoundary::Finalization => {
            "Paused after provider · /unpause · Ctrl+C cancel".into()
        }
    });
    true
}

fn tool_needs_approval(name: &str, arguments: &serde_json::Value, approval: &ApprovalMode) -> bool {
    if name == crate::skills::ACTIVATE_SKILL_TOOL_NAME {
        return false;
    }
    match approval {
        ApprovalMode::RunEverything => false,
        ApprovalMode::AutoReview => {
            !crate::permission::auto_review_safe_invocation(name, arguments)
        }
        ApprovalMode::Allowlist => true,
    }
}

fn apply_tool_result(state: &mut AppState, tool_id: &str, output: &str, status: ToolStatus) {
    observe_workflow_tool_result(state, tool_id, status == ToolStatus::Done);
    let mut tool_name = None;
    if let Some(last) = state.messages.last_mut() {
        if let Some(ref mut tcs) = last.tool_calls {
            for tc in tcs.iter_mut() {
                if tc.id == tool_id {
                    tool_name = Some(tc.name.clone());
                    tc.output = Some(output.to_string());
                    tc.status = status.clone();
                    break;
                }
            }
        }
    }
    if let Some(tool_name) = tool_name {
        let succeeded = status == ToolStatus::Done;
        state.session_sitting.record_tool(
            state.turn_lifecycle.generation,
            tool_id,
            &tool_name,
            status,
        );
        let first = state.outcome_tracker.record_tool(
            state.turn_lifecycle.generation,
            tool_id,
            &tool_name,
            succeeded,
            false,
        );
        if first {
            state.outcome_tracker.event(
                "tool_evidence",
                Some(&tool_name),
                Some(tool_id),
                Some(succeeded),
                output,
            );
            state.outcome_tracker.persist();
        }
    }
}

fn apply_execution_result(
    state: &mut AppState,
    tool_id: &str,
    result: &crate::agent::registry::ToolExecutionResult,
    status: ToolStatus,
) {
    let skill_manage_call = state.messages.iter().rev().any(|message| {
        message.tool_calls.as_ref().is_some_and(|calls| {
            calls
                .iter()
                .any(|call| call.id == tool_id && call.name == "skill_manage")
        })
    });
    let refresh_skill_palette = result.is_success() && skill_manage_call;
    if matches!(
        result,
        crate::agent::registry::ToolExecutionResult::Denied(_)
    ) {
        let name = state
            .messages
            .iter()
            .rev()
            .filter_map(|m| m.tool_calls.as_ref())
            .flatten()
            .find(|c| c.id == tool_id)
            .map(|c| c.name.clone());
        if let Some(name) = name {
            state.outcome_tracker.record_tool(
                state.turn_lifecycle.generation,
                tool_id,
                &name,
                false,
                true,
            );
        }
    }
    let output = command_output::model_text_for_policy(result, state.command_output_policy);
    apply_tool_result(state, tool_id, &output, status);
    if !result.is_success() {
        record_active_skill_outcome(state, learning_journey::SkillOutcome::Failed);
        state
            .skills
            .lock()
            .unwrap_or_else(|poison| poison.into_inner())
            .note_refinement_failure_or_recovery();
    }
    if skill_manage_call && result.is_success() {
        if let Some(ledger) = state.learning_ledger.clone() {
            let receipt = match result {
                crate::agent::registry::ToolExecutionResult::Success(text) => {
                    serde_json::from_str::<skills::SkillManageReceipt>(text).ok()
                }
                _ => None,
            };
            if let Some(receipt) = receipt {
                if let (Some(instance_id), Some(digest)) = (
                    receipt.instance_id.as_deref(),
                    receipt.full_tree_digest.as_deref(),
                ) {
                    let _ = ledger.record_skill_mutation(
                        "committed",
                        &receipt.name,
                        instance_id,
                        digest,
                        receipt.journal_id,
                    );
                }
            }
        }
    }
    if refresh_skill_palette {
        refresh_skill_registry_after_publication(state);
        refresh_prompt_commands(state);
    }
}

fn observe_resolved_for_loop_guard(state: &mut AppState, result: &app::ResolvedToolResult) {
    let call = state.messages.iter().rev().find_map(|message| {
        message
            .tool_calls
            .as_ref()
            .and_then(|calls| calls.iter().find(|call| call.id == result.tool_id))
            .cloned()
    });
    let Some(call) = call else {
        return;
    };
    if let Some(incident) = state
        .loop_guard
        .observe_batch([loop_guard::LoopObservation::from_resolved(&call, result)])
    {
        state.pending_loop_incident.get_or_insert(incident);
    }
}

fn observe_execution_for_loop_guard(
    state: &mut AppState,
    tool_id: &str,
    result: &crate::agent::registry::ToolExecutionResult,
) {
    let call = state.messages.iter().rev().find_map(|message| {
        message
            .tool_calls
            .as_ref()
            .and_then(|calls| calls.iter().find(|call| call.id == tool_id))
            .cloned()
    });
    let Some(call) = call else {
        return;
    };
    observe_execution_for_loop_guard_with_call(state, &call.name, &call.arguments, result);
}

fn observe_execution_for_loop_guard_with_call(
    state: &mut AppState,
    tool_name: &str,
    tool_arguments: &str,
    result: &crate::agent::registry::ToolExecutionResult,
) {
    let observation =
        loop_guard::LoopObservation::from_execution(tool_name, tool_arguments, result);
    if let loop_guard::LoopObservation::Command { command, .. } = &observation {
        state.outcome_tracker.observe_execution_hint(command);
    }
    if let Some(incident) = state.loop_guard.observe_batch([observation]) {
        state.pending_loop_incident.get_or_insert(incident);
    }
}

fn observe_other_for_loop_guard(state: &mut AppState) {
    let _ = state
        .loop_guard
        .observe_batch([loop_guard::LoopObservation::Other]);
}

fn retain_tool_image(
    state: &mut AppState,
    tool_id: &str,
    result: &crate::agent::registry::ToolExecutionResult,
) {
    if let Some(image) = result.image() {
        state
            .transient_tool_images
            .insert(tool_id.to_string(), image.clone());
    }
}

fn retain_memory_proposal(
    state: &mut AppState,
    result: &crate::agent::registry::ToolExecutionResult,
) {
    let Some(proposal) = result.memory_proposal() else {
        return;
    };
    if !state
        .memory_proposals
        .iter()
        .any(|existing| existing.id == proposal.id)
    {
        state.memory_proposals.push(proposal.clone());
        state.status_message = Some("Memory proposal queued; review it in /memory".into());
    }
}

fn retain_file_mutation(
    state: &mut AppState,
    tool_id: &str,
    result: &crate::agent::registry::ToolExecutionResult,
) {
    if let Some(mutation) = result.mutation_batch() {
        retain_file_mutation_receipt(state, tool_id, mutation);
    }
}

fn retain_file_mutation_receipt(
    state: &mut AppState,
    tool_id: &str,
    mutation: &crate::undo::FileMutationBatchReceipt,
) {
    if let Some(turn) = state.active_agent_turn_id {
        state.automatic_review.record(turn, mutation);
    }
    state.outcome_tracker.invalidate_verification();
    state.artifact_ledger.record_mutation_batch(
        &state.workspace,
        mutation,
        state.messages.len(),
        chrono::Utc::now(),
    );
    let mut relative_paths = Vec::new();
    for receipt in mutation.receipts() {
        if matches!(receipt.before, crate::undo::FileState::Missing) {
            state.mechanistic_unscoped_mutation = true;
        }
        if let Some(primary) = state.workspace.primary() {
            if let Ok(relative) = receipt.path.strip_prefix(&primary.path) {
                let relative = relative.to_string_lossy().replace('\\', "/");
                if !relative.is_empty()
                    && !relative
                        .split('/')
                        .any(|component| component.is_empty() || matches!(component, "." | ".."))
                {
                    state.mechanistic_changed_paths.insert(relative.clone());
                    relative_paths.push(relative);
                }
            }
        }
    }
    state.file_activity_presentations.insert(
        tool_id.to_string(),
        crate::app::FileActivityPresentation::from_receipt(mutation.primary()),
    );
    state.undo_stack.record_batch(mutation.clone());
    let mut evidence = mechanistic_delegation::EvidenceLedgerEntry::simple(
        "mutation",
        "completed",
        "typed_mutation_batch",
    );
    evidence.selected_paths = relative_paths;
    evidence.action_digest = Some(mutation.digest.clone());
    record_mechanistic_evidence(state, evidence);
}

fn retain_successful_file_read(
    state: &mut AppState,
    tool_id: &str,
    successful: bool,
    track_reads: bool,
) {
    if !successful || !track_reads {
        return;
    }
    let raw_path = state.messages.iter().rev().find_map(|message| {
        message.tool_calls.as_ref().and_then(|calls| {
            calls.iter().find_map(|call| {
                if call.id != tool_id || call.name != "read_file" {
                    return None;
                }
                serde_json::from_str::<serde_json::Value>(&call.arguments)
                    .ok()?
                    .get("path")?
                    .as_str()
                    .map(ToOwned::to_owned)
            })
        })
    });
    if let Some(raw_path) = raw_path {
        let _ = state.artifact_ledger.record_read(
            &state.workspace,
            &raw_path,
            state.messages.len(),
            chrono::Utc::now(),
        );
    }
}

fn record_mechanistic_evidence(
    state: &mut AppState,
    entry: mechanistic_delegation::EvidenceLedgerEntry,
) {
    state.mechanistic_evidence.record(entry.clone());
    let profile = state.active_profile.clone();
    if let Ok(runtime) = tokio::runtime::Handle::try_current() {
        runtime.spawn_blocking(move || {
            let _ = mechanistic_delegation::record_quality_history(&profile, &entry);
        });
    }
}

fn retain_command_presentation(
    state: &mut AppState,
    tool_id: &str,
    observation: Option<&command_output::CommandObservation>,
) {
    if state.command_output_policy != config::CommandOutputPolicy::Semantic {
        return;
    }
    let Some(presentation) = observation.and_then(command_output::summarize) else {
        return;
    };
    state.latest_semantic_command = Some(presentation.rerun.clone());
    state
        .command_presentations
        .insert(tool_id.to_string(), presentation);
}

fn apply_undo_task_result(state: &mut AppState, result: UndoTaskResult) -> bool {
    if result.generation != state.undo_generation {
        return false;
    }
    state.undo_busy = false;
    let diagnostics = result.diagnostics;
    let durable = result.durable;
    let warning = durable.as_ref().and_then(|(_, _, warning)| warning.clone());
    let restored = result.result.is_ok()
        && (durable.is_some() || state.undo_stack.complete(&result.operation));
    if let Some((history, writer, _)) = durable {
        state.undo_stack = history;
        state.session_writer = Some(writer);
    }
    match result.result {
        Ok(()) if restored => {
            state.artifact_ledger.record_undo_operation(
                &state.workspace,
                &result.operation,
                state.messages.len(),
                chrono::Utc::now(),
            );
            state.outcome_tracker.record_undo();
            state.outcome_tracker.invalidate_verification();
            state.mechanistic_verification_context = None;
            state
                .work_state
                .lock()
                .unwrap_or_else(|poison| poison.into_inner())
                .invalidate_verification_after_recovery();
            let summary = format!(
                "{} {}: {}",
                result.operation.direction.past_tense(),
                result.operation.batch.action,
                result.operation.batch.safe_path()
            );
            state.status_message = Some(warning.as_ref().map_or_else(
                || summary.clone(),
                |warning| format!("{summary}. {warning}"),
            ));
            if let Some(diagnostics) = diagnostics {
                state.pager_content = format!("{summary}\n\n{diagnostics}");
                state.pager_scroll = 0;
                state.pager_open = true;
            }
        }
        Ok(()) => {
            state.status_message = Some(
                "File changed, but the history state was replaced; no history entry was consumed"
                    .into(),
            );
        }
        Err(error) => {
            state.status_message = Some(format!(
                "Could not {} {}: {error}",
                match result.operation.direction {
                    crate::undo::UndoDirection::Undo => "undo",
                    crate::undo::UndoDirection::Redo => "redo",
                },
                result.operation.batch.safe_path()
            ));
        }
    }
    true
}

fn apply_interaction_resolution(
    state: &mut AppState,
    resolution: crate::interaction::InteractionResolution,
) -> bool {
    if let Some(crate::interaction::PendingManualResolution::Interaction(pending)) =
        state.manual_resolutions.current()
    {
        if pending.write_access.is_some()
            && (pending.id != resolution.id
                || resolution.tool_call_id.as_deref() != Some(pending.tool_call_id.as_str()))
        {
            return false;
        }
    }
    let write_access = match state.manual_resolutions.current() {
        Some(crate::interaction::PendingManualResolution::Interaction(pending))
            if pending.id == resolution.id
                && resolution.tool_call_id.as_deref() == Some(&pending.tool_call_id) =>
        {
            pending.write_access.clone()
        }
        _ => None,
    };
    if !state.manual_resolutions.resolve_interaction(resolution.id) {
        return false;
    }
    observe_other_for_loop_guard(state);
    if let Some(tool_call_id) = resolution.tool_call_id.as_deref() {
        if let Some(request) = write_access {
            let accepted = matches!(&resolution.outcome,
                crate::interaction::InteractionOutcome::Answer(answer)
                    if answer.selected.iter().any(|value| value == "yes"));
            let result = if accepted {
                state.workspace.grant_session_write(request.root.clone())
                    .map(|()| format!("Write access granted for this live session: {}. Use ordinary tools or run_command without sudo.", request.root.path.display()))
                    .map_err(|error| error.to_string())
            } else {
                Err("Folder write access was not granted".into())
            };
            let (output, status) = match result {
                Ok(output) => (output, ToolStatus::Done),
                Err(error) => (error, ToolStatus::Error),
            };
            apply_tool_result(state, tool_call_id, &output, status);
            return true;
        }
        let (output, status) = match resolution.outcome.model_result() {
            Ok(output) => {
                let status = if matches!(
                    resolution.outcome,
                    crate::interaction::InteractionOutcome::Cancelled
                ) {
                    ToolStatus::Error
                } else {
                    ToolStatus::Done
                };
                (output, status)
            }
            Err(error) => (error.to_string(), ToolStatus::Error),
        };
        apply_tool_result(state, tool_call_id, &output, status);
    }
    true
}

fn handle_resolution(
    state: &mut AppState,
    config: &CaConfig,
    stream_tx: &mpsc::UnboundedSender<StreamMsg>,
    cancel_handle: &mut Option<tokio::task::JoinHandle<()>>,
) {
    let tool_call_id = state
        .approval_queue
        .current()
        .map(|approval| approval.tool_id.clone());
    let action = state.approval_queue.resolve();
    apply_resolution_action(
        state,
        &action,
        tool_call_id.as_deref(),
        config,
        stream_tx,
        cancel_handle,
    );
}

/// Apply a resolution action to UI/provider continuation.
/// Shared by normal deny, async completion, and cancellation paths
/// to ensure exactly-once continuation.
fn apply_resolution_action(
    state: &mut AppState,
    action: &ResolutionAction,
    tool_call_id: Option<&str>,
    config: &CaConfig,
    stream_tx: &mpsc::UnboundedSender<StreamMsg>,
    cancel_handle: &mut Option<tokio::task::JoinHandle<()>>,
) {
    match action {
        ResolutionAction::Advance { .. } => {
            let (r, t) = state.approval_queue.progress();
            state.status_message = Some(format!(
                "Tool needs approval [{}/{}] (y/n/a/g/s/x/p)",
                r + 1,
                t
            ));
        }
        ResolutionAction::Continue => {
            state.approval_queue.clear();
            if let Some(tool_call_id) = tool_call_id {
                if state.manual_resolutions.resolve_tool(tool_call_id) {
                    activate_next_manual_resolution(state, config, stream_tx, cancel_handle);
                } else if !state.manual_resolutions.is_active() {
                    continue_after_tool_resolutions(state, config, stream_tx, cancel_handle);
                }
            }
        }
        ResolutionAction::Idle => {
            // No current item; no-op
        }
    }
}

