struct PaneStreamMessage {
    pane: panes::PaneId,
    message: StreamMsg,
}

fn pane_stream_channel(
    pane: panes::PaneId,
    router: mpsc::UnboundedSender<PaneStreamMessage>,
) -> (
    mpsc::UnboundedSender<StreamMsg>,
    tokio::task::JoinHandle<()>,
) {
    let (sender, mut receiver) = mpsc::unbounded_channel();
    let forwarder = tokio::spawn(async move {
        while let Some(message) = receiver.recv().await {
            if router.send(PaneStreamMessage { pane, message }).is_err() {
                break;
            }
        }
    });
    (sender, forwarder)
}

#[derive(Default)]
struct PaneCoreTasks {
    stream: Option<tokio::task::JoinHandle<()>>,
    approval: Option<tokio::task::JoinHandle<()>>,
    tools: Option<tokio::task::JoinHandle<()>>,
    goal: Option<tokio::task::JoinHandle<()>>,
}

fn take_pane_core_tasks(
    stream: &mut Option<tokio::task::JoinHandle<()>>,
    approval: &mut Option<tokio::task::JoinHandle<()>>,
    tools: &mut Option<tokio::task::JoinHandle<()>>,
    goal: &mut Option<tokio::task::JoinHandle<()>>,
) -> PaneCoreTasks {
    PaneCoreTasks {
        stream: stream.take(),
        approval: approval.take(),
        tools: tools.take(),
        goal: goal.take(),
    }
}

fn install_pane_core_tasks(
    tasks: PaneCoreTasks,
    stream: &mut Option<tokio::task::JoinHandle<()>>,
    approval: &mut Option<tokio::task::JoinHandle<()>>,
    tools: &mut Option<tokio::task::JoinHandle<()>>,
    goal: &mut Option<tokio::task::JoinHandle<()>>,
) {
    *stream = tasks.stream;
    *approval = tasks.approval;
    *tools = tasks.tools;
    *goal = tasks.goal;
}

#[allow(clippy::too_many_arguments)]
fn materialize_pane_runtime(
    state: &mut AppState,
    target: panes::PaneId,
    stream: &mut Option<tokio::task::JoinHandle<()>>,
    approval: &mut Option<tokio::task::JoinHandle<()>>,
    tools: &mut Option<tokio::task::JoinHandle<()>>,
    goal: &mut Option<tokio::task::JoinHandle<()>>,
    inactive_tasks: &mut std::collections::BTreeMap<panes::PaneId, PaneCoreTasks>,
    focus: bool,
) -> Result<(), String> {
    if state.pane_id == target {
        if focus {
            return panes::focus(state, target);
        }
        return Ok(());
    }
    let previous = state.pane_id;
    let previous_tasks = take_pane_core_tasks(stream, approval, tools, goal);
    let result = if focus {
        panes::focus(state, target)
    } else {
        panes::materialize(state, target)
    };
    match result {
        Ok(()) => {
            inactive_tasks.insert(previous, previous_tasks);
            install_pane_core_tasks(
                inactive_tasks.remove(&target).unwrap_or_default(),
                stream,
                approval,
                tools,
                goal,
            );
            Ok(())
        }
        Err(error) => {
            install_pane_core_tasks(previous_tasks, stream, approval, tools, goal);
            Err(error)
        }
    }
}

