    #[test]
    fn compact_command_queues_validated_focus_and_rejects_controls() {
        let temp = tempfile::tempdir().unwrap();
        let config_path = temp.path().join("config.toml");
        std::fs::write(&config_path, "# compact command test\n").unwrap();
        let config_store = ConfigStore::new(&config_path);
        let config = config_store.load().unwrap();
        let sessions = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = AppState::new(context::ShellHistory::in_memory());

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::Compact,
                args: "  focus on café auth  ".into(),
            },
            &sessions,
            &config,
            &config_store,
        );
        assert_eq!(
            state
                .checkpoint_request
                .take()
                .and_then(context::ContextCheckpointRequest::into_focus)
                .as_deref(),
            Some("focus on café auth")
        );

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::Compact,
                args: "bad\nfocus".into(),
            },
            &sessions,
            &config,
            &config_store,
        );
        assert!(state.checkpoint_request.is_none());
        assert_eq!(
            state.status_message.as_deref(),
            Some("Compact focus must be a single line without control characters")
        );

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::Compact,
                args: "here".into(),
            },
            &sessions,
            &config,
            &config_store,
        );
        assert_eq!(
            state
                .checkpoint_request
                .take()
                .and_then(|request| request.retained_completed_exchanges()),
            Some(2)
        );

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::Compact,
                args: "here 0".into(),
            },
            &sessions,
            &config,
            &config_store,
        );
        assert!(state.checkpoint_request.is_none());
        assert_eq!(
            state.status_message.as_deref(),
            Some("Compact retained exchange count must be between 1 and 32")
        );
    }

    #[test]
    fn commit_results_discard_stale_generations_and_preserve_failure_context() {
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.change_review =
            changes::ChangeReviewState::open_for(changes::ChangeReviewPurpose::Commit);
        let generation = state.change_review.generation;
        let snapshot = git_commit_test_snapshot();
        assert!(!apply_commit_prepared_result(
            &mut state,
            Ok(snapshot.clone()),
            "stale".into(),
            generation.wrapping_sub(1),
        ));
        assert_eq!(state.change_review.mode, changes::ChangeViewMode::List);
        assert!(apply_commit_prepared_result(
            &mut state,
            Ok(snapshot),
            "Focused subject".into(),
            generation,
        ));
        assert_eq!(state.change_review.mode, changes::ChangeViewMode::Confirm);
        assert!(!state.change_review.commit_selected);

        assert!(apply_commit_finished_result(
            &mut state,
            Err(changes::GitCommitFailure {
                message: "hook rejected the commit".into(),
                uncertain: false,
            }),
            "Focused subject".into(),
            generation,
        ));
        assert_eq!(state.change_review.mode, changes::ChangeViewMode::Subject);
        assert_eq!(state.change_review.subject, "Focused subject");
        assert_eq!(
            state.change_review.error.as_deref(),
            Some("hook rejected the commit")
        );
        assert!(state.changes_load_requested);

        let loaded = changes::ChangeReviewLoad {
            repository: Some(changes::GitRepositoryState {
                root: "/tmp/repo".into(),
                branch: "master".into(),
                head: Some("1".repeat(40)),
            }),
            changes: changes::ChangeSet::default(),
        };
        assert!(apply_changes_loaded_result(
            &mut state,
            Ok(loaded),
            generation,
        ));
        assert_eq!(
            state.change_review.error.as_deref(),
            Some("hook rejected the commit")
        );
        assert_eq!(state.change_review.subject, "Focused subject");
    }

    #[test]
    fn commit_success_uncertainty_and_cancelled_head_drift_are_explicit() {
        let mut success = AppState::new(context::ShellHistory::in_memory());
        success.change_review =
            changes::ChangeReviewState::open_for(changes::ChangeReviewPurpose::Commit);
        let generation = success.change_review.generation;
        assert!(apply_commit_finished_result(
            &mut success,
            Ok(changes::GitCommitResult {
                sha: "a".repeat(40),
                short_sha: "a".repeat(12),
                subject: "Focused subject".into(),
            }),
            "Focused subject".into(),
            generation,
        ));
        assert!(!success.change_review.open);
        assert_eq!(
            success.status_message.as_deref(),
            Some("Committed aaaaaaaaaaaa Focused subject")
        );

        let mut uncertain = AppState::new(context::ShellHistory::in_memory());
        uncertain.change_review =
            changes::ChangeReviewState::open_for(changes::ChangeReviewPurpose::Commit);
        let generation = uncertain.change_review.generation;
        assert!(apply_commit_finished_result(
            &mut uncertain,
            Err(changes::GitCommitFailure {
                message: "HEAD moved; inspect the repository".into(),
                uncertain: true,
            }),
            "Focused subject".into(),
            generation,
        ));
        assert!(!uncertain.change_review.open);
        assert_eq!(
            uncertain.status_message.as_deref(),
            Some("HEAD moved; inspect the repository")
        );

        let mut cancelled = AppState::new(context::ShellHistory::in_memory());
        cancelled.change_review =
            changes::ChangeReviewState::open_for(changes::ChangeReviewPurpose::Commit);
        cancelled.change_review.cancelled_operation = true;
        cancelled.change_review.cancelled_commit_head = Some(Some("1".repeat(40)));
        let generation = cancelled.change_review.generation;
        let loaded = changes::ChangeReviewLoad {
            repository: Some(changes::GitRepositoryState {
                root: "/tmp/repo".into(),
                branch: "master".into(),
                head: Some("3".repeat(40)),
            }),
            changes: changes::ChangeSet::default(),
        };
        assert!(apply_changes_loaded_result(
            &mut cancelled,
            Ok(loaded),
            generation,
        ));
        assert!(cancelled
            .change_review
            .error
            .as_deref()
            .is_some_and(|error| error.contains("uncertain outcome") && error.contains("HEAD")));
    }

    #[derive(Default)]
    struct FakeProviderSecrets {
        values: Mutex<HashMap<String, Vec<u8>>>,
    }

    impl crate::provider_secrets::ProviderSecretStore for FakeProviderSecrets {
        fn load(&self, provider: &str) -> anyhow::Result<Option<Vec<u8>>> {
            Ok(self.values.lock().unwrap().get(provider).cloned())
        }

        fn store(&self, provider: &str, secret: &[u8]) -> anyhow::Result<()> {
            self.values
                .lock()
                .unwrap()
                .insert(provider.to_string(), secret.to_vec());
            Ok(())
        }

        fn delete(&self, provider: &str) -> anyhow::Result<()> {
            self.values.lock().unwrap().remove(provider);
            Ok(())
        }
    }

