    #[test]
    fn support_bundle_and_config_explain_commands_are_bounded_and_read_only() {
        use std::os::unix::fs::PermissionsExt;

        let temp = tempfile::tempdir().unwrap();
        let config_path = temp.path().join("config.toml");
        std::fs::write(
            &config_path,
            "[defaults]\nprovider = 'safe'\nmodel = 'local'\n",
        )
        .unwrap();
        std::fs::set_permissions(&config_path, std::fs::Permissions::from_mode(0o600)).unwrap();
        let config_store = ConfigStore::new(&config_path);
        let config = config_store.load().unwrap();
        let sessions = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = AppState::new(context::ShellHistory::in_memory());

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::SupportBundle,
                args: "unexpected".into(),
            },
            &sessions,
            &config,
            &config_store,
        );
        assert!(!state.support_bundle_requested);
        assert!(state
            .status_message
            .as_deref()
            .unwrap()
            .contains("duration"));

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::SupportBundle,
                args: "since=2h".into(),
            },
            &sessions,
            &config,
            &config_store,
        );
        assert!(state.support_bundle_requested);
        assert!(state.support_bundle_since.is_some());

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::Config,
                args: "explain defaults".into(),
            },
            &sessions,
            &config,
            &config_store,
        );
        assert!(state.pager_open);
        assert!(state.pager_content.contains("defaults.provider"));
        assert!(!state.pager_content.contains("safe"));
    }

