    #[test]
    fn trace_command_manages_status_files_and_cancel_first_deletion() {
        let temp = tempfile::tempdir().unwrap();
        let hub = provider_trace::ProviderTraceHub::new(temp.path().join("traces"), true);
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.provider_trace = Some(hub.clone());

        execute_trace_command(&mut state, "");
        assert!(state.pager_open);
        assert!(state.pager_content.contains("Status: off"));

        execute_trace_command(&mut state, "on");
        let id = hub.status().trace_id.unwrap();
        assert!(hub.status().enabled);
        execute_trace_command(&mut state, "off");
        assert!(!hub.status().enabled);

        execute_trace_command(&mut state, "list");
        assert!(state.pager_content.contains(&id.to_string()));
        execute_trace_command(&mut state, &format!("delete {id}"));
        let confirmation = state.trace_delete_confirmation.as_ref().unwrap();
        assert_eq!(confirmation.trace_id, id);
        assert!(!confirmation.delete_selected);

        apply_trace_delete(&mut state, id);
        assert!(state.trace_delete_confirmation.is_none());
        assert!(hub.list().unwrap().is_empty());

        execute_trace_command(&mut state, "open not-an-id");
        assert_eq!(
            state.status_message.as_deref(),
            Some("Usage: /trace open <id>")
        );
    }

