    #[test]
    fn service_cli_reserves_only_the_leading_serve_command() {
        let service = parse_launch_args(["ca", "serve", "--stdio", "--profile", "work"])
            .expect("service command should parse");
        let LaunchArgs::Serve(service) = service else {
            panic!("leading serve must select service mode");
        };
        assert!(matches!(
            service.transport,
            crate::service::ServiceTransport::Stdio
        ));
        assert_eq!(
            service.active_profile,
            runtime::ActiveProfile::Named("work".into())
        );

        let LaunchArgs::Standard(prompt) =
            parse_launch_args(["ca", "-p", "serve"]).expect("explicit prompt remains valid")
        else {
            panic!("-p serve must remain a prompt");
        };
        assert_eq!(prompt.one_shot_prompt.as_deref(), Some("serve"));

        let LaunchArgs::Standard(dashboard) =
            parse_launch_args(["ca", "dashboard"]).expect("dashboard command")
        else {
            panic!("ca dashboard must launch the TUI dashboard");
        };
        assert!(dashboard.open_dashboard);
        let LaunchArgs::Standard(flag) =
            parse_launch_args(["ca", "--dashboard"]).expect("dashboard flag")
        else {
            panic!("--dashboard must launch the TUI dashboard");
        };
        assert!(flag.open_dashboard);
        assert!(parse_launch_args(["ca", "serve", "unexpected"]).is_err());

        let listener = parse_launch_args([
            "ca",
            "serve",
            "--listen",
            "127.0.0.1:0",
            "--auth-env",
            "CA_TEST_ATTACH_TOKEN",
        ])
        .expect("loopback listener should parse");
        assert!(matches!(
            listener,
            LaunchArgs::Serve(crate::service::ServiceCliArgs {
                transport: crate::service::ServiceTransport::WebSocket { .. },
                ..
            })
        ));

        let attach = parse_launch_args([
            "ca",
            "attach",
            "ws://127.0.0.1:9777/",
            "--auth-env",
            "CA_TEST_ATTACH_TOKEN",
        ])
        .expect("loopback attach should parse");
        assert!(matches!(attach, LaunchArgs::Attach(_)));
        assert!(parse_launch_args([
            "ca",
            "attach",
            "ws://example.com:9777/",
            "--auth-env",
            "CA_TEST_ATTACH_TOKEN",
        ])
        .is_err());
    }

