    #[test]
    fn local_cli_and_process_only_run_flags_are_explicit_and_conflict_safe() {
        assert!(matches!(
            parse_launch_args(["ca", "local", "list"]).expect("local list should parse"),
            LaunchArgs::Local(_)
        ));
        let LaunchArgs::Standard(prompt) =
            parse_launch_args(["ca", "-p", "local"]).expect("local remains a prompt after -p")
        else {
            panic!("-p local must remain a prompt");
        };
        assert_eq!(prompt.one_shot_prompt.as_deref(), Some("local"));

        let cli = parse_cli_args([
            "ca",
            "--local-model",
            "demo",
            "--local-runtime",
            "llama",
            "--local-context-size",
            "8192",
            "--local-startup-timeout",
            "20",
            "-p",
            "hello",
        ])
        .unwrap();
        let options = cli.local_run.unwrap();
        assert_eq!(options.model_id, "demo");
        assert_eq!(options.runtime_id, "llama");
        assert_eq!(options.context_size, 8192);
        assert_eq!(options.startup_timeout, std::time::Duration::from_secs(20));

        for args in [
            vec!["ca", "--local-model", "demo", "-p", "hello"],
            vec![
                "ca",
                "--local-model",
                "demo",
                "--local-runtime",
                "llama",
                "--doctor",
            ],
            vec![
                "ca",
                "--local-model",
                "demo",
                "--local-runtime",
                "llama",
                "--session",
                "saved",
            ],
        ] {
            assert!(parse_cli_args(args).is_err());
        }

        let temporary = tempfile::tempdir().unwrap();
        let path = temporary.path().join("config.toml");
        let store = ConfigStore::for_process_only_load(&path, runtime::ActiveProfile::Default);
        assert!(!store.creates_on_load());
        assert!(!store.load().unwrap().providers.is_empty());
        assert!(!path.exists());
    }

