    #[test]
    fn headless_contract_flags_preserve_positional_inputs_and_require_explicit_check() {
        for args in [
            vec!["ca", "--check", "review", "this", "@Cargo.toml"],
            vec!["ca", "review", "this", "@Cargo.toml", "--check"],
            vec![
                "ca",
                "--output-schema",
                "schema.json",
                "review",
                "this",
                "@Cargo.toml",
            ],
            vec![
                "ca",
                "review",
                "this",
                "@Cargo.toml",
                "--output-schema",
                "schema.json",
            ],
        ] {
            let cli = parse_cli_args(args).expect("new headless contract flags should parse");
            assert_eq!(cli.one_shot_prompt.as_deref(), Some("review this"));
            assert_eq!(cli.file_mentions, ["Cargo.toml"]);
        }

        assert!(parse_cli_args(["ca", "--check-repair", "-p", "fix it"]).is_err());
        assert!(parse_cli_args(["ca", "--check", "--check-repair", "-p", "fix it"]).is_ok());
        assert!(parse_cli_args(["ca", "--check-converge", "-p", "inspect it"]).is_err());
        let converge =
            parse_cli_args(["ca", "--check", "--check-converge", "-p", "inspect it"]).unwrap();
        assert!(converge.check_converge);
        assert!(!converge.check_converge_unpriced);
        assert!(parse_cli_args([
            "ca",
            "--check",
            "--check-converge-unpriced",
            "-p",
            "inspect it",
        ])
        .is_err());
        assert!(
            parse_cli_args([
                "ca",
                "--check",
                "--check-converge",
                "--check-converge-unpriced",
                "-p",
                "inspect it",
            ])
            .unwrap()
            .check_converge_unpriced
        );
    }

