    #[test]
    fn caller_session_id_collision_checks_active_and_archive_namespaces() {
        let temp = tempfile::tempdir().unwrap();
        let store = session::SessionStore::with_archive(
            temp.path().join("active"),
            temp.path().join("archive"),
        );
        let mut saved =
            session::SessionV2::new("saved", "/workspace", "provider", "model", Vec::new());
        let id = saved.id;
        store.save(&mut saved).unwrap();
        assert!(session_id_exists(&store, id).unwrap());
        assert!(!session_id_exists(&store, uuid::Uuid::new_v4()).unwrap());
        let summary = store.list().unwrap().pop().unwrap();
        store.archive(&summary.storage_key, id).unwrap();
        assert!(session_id_exists(&store, id).unwrap());
    }

    #[test]
    fn ephemeral_history_is_validated_without_persisting_an_import() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("history.json");
        let session = session::SessionV2::new(
            "portable",
            "/source",
            "provider",
            "model",
            vec![Message {
                role: Role::User,
                content: "prior request".into(),
                tool_calls: None,
                thinking: None,
                response_items: Vec::new(),
                timestamp: chrono::Utc::now(),
            }],
        );
        let bytes =
            session_portability::encode_session(&session, session_portability::ExportFormat::Json)
                .unwrap();
        std::fs::write(&path, bytes).unwrap();
        let messages = read_ephemeral_history(&path, temp.path()).unwrap();
        assert_eq!(messages.len(), 1);
        assert_eq!(messages[0].content, "prior request");
        assert!(!temp.path().join("sessions").exists());

        std::fs::write(&path, br#"{"schema":"wrong"}"#).unwrap();
        assert!(read_ephemeral_history(&path, temp.path()).is_err());
    }

