    #[tokio::test]
    async fn launch_worktree_preserves_supplemental_roots_and_setup_is_digest_bound() {
        fn git(cwd: &std::path::Path, args: &[&str]) {
            let output = std::process::Command::new("git")
                .args(args)
                .current_dir(cwd)
                .env("GIT_AUTHOR_NAME", "CA Test")
                .env("GIT_AUTHOR_EMAIL", "ca@example.invalid")
                .env("GIT_COMMITTER_NAME", "CA Test")
                .env("GIT_COMMITTER_EMAIL", "ca@example.invalid")
                .output()
                .unwrap();
            assert!(
                output.status.success(),
                "{}",
                String::from_utf8_lossy(&output.stderr)
            );
        }

        let temp = tempfile::tempdir().unwrap();
        let repository = temp.path().join("repository");
        let supplemental = temp.path().join("supplemental");
        std::fs::create_dir_all(&repository).unwrap();
        std::fs::create_dir_all(&supplemental).unwrap();
        git(&repository, &["init", "-q"]);
        std::fs::write(repository.join("tracked.txt"), "base\n").unwrap();
        git(&repository, &["add", "tracked.txt"]);
        git(&repository, &["commit", "-q", "-m", "base"]);
        std::fs::create_dir_all(repository.join(".ca")).unwrap();
        std::fs::write(
            repository.join(".ca/worktrees.toml"),
            "version = 1\n[[steps]]\nname = \"marker\"\nprogram = \"/usr/bin/touch\"\nargs = [\"setup-ok\"]\nsandbox = \"policy-only\"\n",
        )
        .unwrap();
        let repository = std::fs::canonicalize(repository).unwrap();
        let supplemental = std::fs::canonicalize(supplemental).unwrap();
        let mut workspace = workspace::WorkspaceContext::discover(&repository).unwrap();
        workspace.add_root(&supplemental, true).unwrap();
        let paths = runtime::RuntimePaths::from_home(temp.path().join("home"));
        let mut cli = CliArgs {
            worktree: Some("launch".into()),
            worktree_base: Some("HEAD".into()),
            active_profile: runtime::ActiveProfile::Default,
            ..CliArgs::default()
        };
        let launch = create_launch_worktree(&cli, &paths, workspace)
            .await
            .unwrap();
        let record = launch.record.as_ref().unwrap();
        assert_eq!(launch.workspace.primary().unwrap().path, record.path);
        assert_eq!(launch.workspace.roots().len(), 2);
        assert_eq!(launch.workspace.roots()[1].path, supplemental);
        assert!(launch.workspace.roots()[1].read_only);

        let warnings = apply_headless_worktree_setup(&cli, &launch).await.unwrap();
        assert_eq!(warnings.len(), 1);
        assert!(warnings[0].contains("did not match"));
        assert!(!record.path.join("setup-ok").exists());

        cli.worktree_setup_digest = launch.setup.as_ref().map(|preview| preview.digest.clone());
        let warnings = apply_headless_worktree_setup(&cli, &launch).await.unwrap();
        assert_eq!(warnings.len(), 1);
        assert!(warnings[0].contains("did not include --trust"));
        assert!(!record.path.join("setup-ok").exists());

        cli.trust = true;
        assert!(apply_headless_worktree_setup(&cli, &launch)
            .await
            .unwrap()
            .is_empty());
        assert!(record.path.join("setup-ok").is_file());

        let no_setup = LaunchWorktree {
            workspace: launch.workspace.clone(),
            record: launch.record.clone(),
            setup: None,
        };
        let warnings = apply_headless_worktree_setup(&cli, &no_setup)
            .await
            .unwrap();
        assert_eq!(warnings.len(), 1);
        assert!(warnings[0].contains("no setup configuration"));
    }

