    #[test]
    fn launch_workspace_resolves_catalog_precedence_and_deduplicates_cli_roots() {
        let temp = tempfile::tempdir().unwrap();
        let launch = temp.path().join("launch");
        let ambiguous = launch.join("team");
        let saved = temp.path().join("saved");
        let extra = temp.path().join("extra");
        std::fs::create_dir_all(&ambiguous).unwrap();
        std::fs::create_dir_all(&saved).unwrap();
        std::fs::create_dir_all(&extra).unwrap();
        let launch = std::fs::canonicalize(launch).unwrap();
        let saved = std::fs::canonicalize(saved).unwrap();
        let extra = std::fs::canonicalize(extra).unwrap();
        let paths = runtime::RuntimePaths::from_home(temp.path().join("home"));
        let profile = runtime::ActiveProfile::Named("work".into());
        let catalog =
            workspace_catalog::WorkspaceCatalogStore::new(paths.workspace_catalog_file(&profile));
        let saved_workspace =
            workspace::WorkspaceContext::from_primary(saved.clone(), saved.clone());
        catalog.save("team", &saved_workspace).unwrap();

        let cli = CliArgs {
            active_profile: profile,
            workspace: Some("team".into()),
            add_dirs: vec![extra.clone(), extra.clone()],
            ..CliArgs::default()
        };
        let resolved = resolve_launch_workspace(&cli, &paths, &launch).unwrap();
        assert_eq!(resolved.primary().unwrap().path, saved);
        assert_eq!(resolved.roots().len(), 2);
        assert_eq!(resolved.roots()[1].path, extra);

        let explicit = CliArgs {
            workspace: Some("./team".into()),
            ..cli
        };
        assert_eq!(
            resolve_launch_workspace(&explicit, &paths, &launch)
                .unwrap()
                .primary()
                .unwrap()
                .path,
            std::fs::canonicalize(ambiguous).unwrap()
        );
    }

    #[test]
    fn cli_parser_preserves_tool_filters_and_positional_inputs_in_either_order() {
        for args in [
            vec![
                "ca",
                "--tools",
                "WRITE_FILE,read_file",
                "--include-tools",
                "search_files",
                "--exclude-tools",
                "write_file",
                "review",
                "this",
                "@Cargo.toml",
            ],
            vec![
                "ca",
                "review",
                "this",
                "@Cargo.toml",
                "--tools",
                "WRITE_FILE,read_file",
                "--include-tools",
                "search_files",
                "--exclude-tools",
                "write_file",
            ],
        ] {
            let cli = parse_cli_args(args).unwrap();
            let resolved = tool_selection::resolve_tools(
                agent::registry::ToolRegistry::builtins(),
                agent::registry::ToolProfile::Main,
                &cli.tool_policy,
                &tool_selection::ToolSelectionConstraints::default(),
            )
            .unwrap();
            let names = resolved
                .definitions()
                .iter()
                .map(|definition| definition.function.name.as_str())
                .collect::<Vec<_>>();
            assert_eq!(names, ["read_file", "search_files"]);
            assert_eq!(cli.one_shot_prompt.as_deref(), Some("review this"));
            assert_eq!(cli.file_mentions, ["Cargo.toml"]);
        }
    }

