    #[test]
    fn cli_parser_rejects_new_session_id_with_resume_paths() {
        let fresh = uuid::Uuid::new_v4().to_string();
        for args in [
            vec![
                "ca",
                "--new-session-id",
                fresh.as_str(),
                "--continue",
                "-p",
                "hi",
            ],
            vec![
                "ca",
                "--new-session-id",
                fresh.as_str(),
                "--session",
                "ses_old",
                "-p",
                "hi",
            ],
            vec![
                "ca",
                "--new-session-id",
                fresh.as_str(),
                "--no-session",
                "-p",
                "hi",
            ],
        ] {
            let error = parse_cli_args(args).unwrap_err();
            let message = error.to_string();
            assert!(
                message.contains("--new-session-id"),
                "unexpected message: {message}"
            );
        }
        // Fresh persistent id alone is accepted at parse time.
        let parsed =
            parse_cli_args(["ca", "--new-session-id", fresh.as_str(), "-p", "hi"]).unwrap();
        assert_eq!(
            parsed.new_session_id,
            Some(uuid::Uuid::parse_str(&fresh).unwrap())
        );
        assert!(!parsed.no_session);
    }

