    #[test]
    fn enabled_memory_is_a_tagged_stale_instruction_component() {
        let temp = tempfile::tempdir().unwrap();
        let cwd = temp.path().to_string_lossy();
        let record = memory::MemoryRecord::new(
            memory::MemoryScope::User,
            memory::MemoryKind::UserPreference,
            "Prefer focused validation before broad gates.",
            memory::MemoryProvenance::Manual,
        )
        .unwrap();
        let recall = memory::MemoryRecall::from_records(true, false, &[record], &[])
            .render_for_query("focused validation");
        let parts = build_system_prompt_parts_with_memory(&cwd, false, None, &recall);
        let rendered = parts.render();
        assert!(rendered.contains("## Recalled Memory"));
        assert!(rendered.contains("may be stale; reverify paths, versions, and facts"));
        assert!(rendered.contains("Prefer focused validation before broad gates."));
        assert!(!parts
            .render_session_epoch()
            .contains("Prefer focused validation before broad gates."));
        assert!(parts
            .render_logical_turn()
            .contains("Prefer focused validation before broad gates."));
        assert!(parts.instruction_tokens(context::TokenEstimator::generic()) > 0);
    }

    #[test]
    fn memory_mutation_worker_persists_then_rebuilds_process_recall() {
        let temp = tempfile::tempdir().unwrap();
        let paths = runtime::RuntimePaths::from_home(temp.path());
        let config_path = paths.config_file.clone();
        let store = ConfigStore::new(&config_path);
        let mut config = store.load().unwrap();
        config.memory.user.recall = true;

        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.memory_manager_generation = 7;
        state.user_memory_store = Some(
            memory::MemoryStore::user(&paths, &runtime::ActiveProfile::Default, true).unwrap(),
        );
        state.memory_manager = Some(crate::app::MemoryManagerState {
            filter: String::new(),
            selected_idx: 0,
            view: crate::app::MemoryManagerView::User,
            editor: None,
            confirmation: None,
            busy: true,
            writes_enabled: true,
            user_recall: true,
            user_generation: false,
            workspace_recall: false,
            workspace_generation: false,
            generation: 7,
            error: None,
            notice: None,
        });
        let request = memory_mutation_request(
            &state,
            &store,
            tui::commands::InputAction::SaveMemoryRecord {
                id: None,
                scope: memory::MemoryScope::User,
                kind: memory::MemoryKind::UserPreference,
                text: "Prefer focused validation.".into(),
            },
        );
        let result = perform_memory_mutation(request);
        apply_memory_mutation_result(&mut state, &mut config, result);

        assert_eq!(state.user_memory_records.len(), 1);
        assert!(state
            .memory_recall
            .render()
            .contains("Prefer focused validation."));
        assert_eq!(
            state.memory_manager.as_ref().unwrap().notice.as_deref(),
            Some("Memory entry saved")
        );
        assert_eq!(
            state
                .user_memory_store
                .as_ref()
                .unwrap()
                .load()
                .unwrap()
                .len(),
            1
        );
    }

