    #[test]
    fn context_overview_reports_latest_foreground_speed_and_honest_status_sections() {
        let root = tempfile::tempdir().unwrap();
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.cwd = root.path().to_string_lossy().into_owned();
        state.workspace = workspace::WorkspaceContext::discover(root.path()).unwrap();
        state.current_model = Some(ModelInfo {
            id: "coder".into(),
            provider: "local".into(),
            display_name: "Coder".into(),
        });
        let handle =
            state
                .usage_ledger
                .lock()
                .unwrap()
                .begin(usage::UsageKind::MainTurn, "local", "coder");
        assert!(state
            .usage_ledger
            .lock()
            .unwrap()
            .finish_with_generation_duration(
                handle,
                Some(agent::stream::UsageInfo {
                    prompt_tokens: 80,
                    completion_tokens: 20,
                    total_tokens: 100,
                    cached_prompt_tokens: None,
                    cache_write_tokens: None,
                    reasoning_tokens: None,
                    response_metadata: None,
                    cache_usage_override: None,
                }),
                usage::UsageOutcome::Completed,
                Some(std::time::Duration::from_secs(2)),
            ));
        state
            .work_state
            .lock()
            .unwrap()
            .apply_model_mutation(work::WorkMutation::Propose {
                body: None,
                expected_revision: 0,
                title: "TUI work".into(),
                tasks: vec!["Render overview".into()],
            })
            .unwrap();
        let rendered = context_dashboard(&state, &CaConfig::default());

        assert!(rendered.contains("This sitting"));
        assert!(rendered.contains("Output speed: 10.0 tokens/s"));
        assert!(rendered.contains("Cost: unknown"));
        assert!(rendered.contains("Working directory:"));
        assert!(rendered.contains("No enabled servers"));
        assert!(rendered.contains("Pending 1"));
        assert!(rendered.contains("/tasks to inspect or manage"));
    }

    #[test]
    fn review_target_parser_is_explicit_and_rejects_ambiguous_input() {
        assert_eq!(
            parse_review_target("").unwrap(),
            changes::ReviewTarget::Working
        );
        assert_eq!(
            parse_review_target("base main").unwrap(),
            changes::ReviewTarget::Base("main".into())
        );
        assert_eq!(
            parse_review_target("commit abcdef0").unwrap(),
            changes::ReviewTarget::Commit("abcdef0".into())
        );
        assert_eq!(
            parse_review_target("custom focus on races").unwrap(),
            changes::ReviewTarget::Custom("focus on races".into())
        );
        assert!(parse_review_target("main").is_err());
        assert!(parse_review_target("base ").is_err());
        assert_eq!(
            parse_review_request("converge").unwrap(),
            ParsedReviewRequest::Converge {
                target: changes::ReviewTarget::Working,
                acknowledge_unpriced: false,
            }
        );
        assert_eq!(
            parse_review_request("converge --ack-unpriced base main").unwrap(),
            ParsedReviewRequest::Converge {
                target: changes::ReviewTarget::Base("main".into()),
                acknowledge_unpriced: true,
            }
        );
        assert!(parse_review_request("converge base").is_err());
    }

