    #[test]
    fn provider_editor_action_saves_refreshes_and_selects_without_user_state() {
        let temp = tempfile::tempdir().unwrap();
        let config_path = temp.path().join("config.toml");
        std::fs::write(
            &config_path,
            r#"[providers.test]
base_url = "https://example.invalid/v1"
api_key = "${EDITOR_TEST_KEY}"
models = ["old"]

[defaults]
provider = "test"
model = "old"
"#,
        )
        .unwrap();
        let config_store = ConfigStore::new(&config_path);
        let mut config = config_store.load().unwrap();
        let session_store = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.model_list = tui::input::build_model_list(&config.providers);
        let existing_model = state.model_list[0].clone();

        execute_input_action(
            &mut state,
            tui::commands::InputAction::OpenProviderEditor(
                crate::app::ProviderEditorRequest::EditModel(existing_model),
            ),
            &session_store,
            &mut config,
            &config_store,
        );
        let editor = state.provider_editor.as_ref().unwrap();
        assert_eq!(editor.draft.base_url, "https://example.invalid/v1");
        assert_eq!(editor.mode, crate::app::ProviderEditorMode::EditModel);
        assert_eq!(editor.draft.api_key_env, "EDITOR_TEST_KEY");
        assert_eq!(editor.field, crate::app::ProviderEditorField::Model);
        assert_eq!(editor.cursor, "old".len());

        execute_input_action(
            &mut state,
            tui::commands::InputAction::SaveProviderModel(crate::app::ProviderModelDraft {
                google: None,
                original_model: Some("old".into()),
                provider: "bad provider".into(),
                base_url: "https://new.example.invalid/v1".into(),
                api_key_env: String::new(),
                model: "new".into(),
            }),
            &session_store,
            &mut config,
            &config_store,
        );
        assert!(state
            .provider_editor
            .as_ref()
            .unwrap()
            .error
            .as_deref()
            .is_some_and(|error| error.contains("provider must use")));

        execute_input_action(
            &mut state,
            tui::commands::InputAction::SaveProviderModel(crate::app::ProviderModelDraft {
                google: None,
                original_model: Some("old".into()),
                provider: "test".into(),
                base_url: "https://new.example.invalid/v1".into(),
                api_key_env: String::new(),
                model: "new".into(),
            }),
            &session_store,
            &mut config,
            &config_store,
        );

        assert!(state.provider_editor.is_none());
        assert_eq!(state.current_model.as_ref().unwrap().id, "new");
        assert_eq!(state.model_list[0].id, "new");
        assert_eq!(config.defaults.model, "new");
        assert_eq!(state.status_message.as_deref(), Some("Updated test/new"));
        let raw = std::fs::read_to_string(config_path).unwrap();
        assert!(raw.contains("${EDITOR_TEST_KEY}"));
    }

    #[test]
    fn provider_command_opens_safe_filtered_manager_with_current_provider_first() {
        let temp = tempfile::tempdir().unwrap();
        let config_path = temp.path().join("config.toml");
        std::fs::write(
            &config_path,
            r#"[providers.alpha]
base_url = "https://alpha.invalid/v1"
api_key = "literal-secret-that-must-stay-hidden"
models = []

[providers.zeta]
base_url = "https://zeta.invalid/v1"
api_key = "${ZETA_KEY}"
models = ["current"]

[defaults]
provider = "zeta"
model = "current"
"#,
        )
        .unwrap();
        let config_store = ConfigStore::new(&config_path);
        let mut config = config_store.load().unwrap();
        let session_store = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.current_model = Some(ModelInfo {
            id: "current".into(),
            provider: "zeta".into(),
            display_name: "current".into(),
        });

        execute_input_action(
            &mut state,
            tui::commands::InputAction::Command(tui::commands::CommandAction {
                id: tui::commands::CommandId::Provider,
                args: "zet".into(),
            }),
            &session_store,
            &mut config,
            &config_store,
        );

        let manager = state.provider_manager.as_ref().unwrap();
        assert_eq!(manager.provider_filter, "zet");
        assert_eq!(manager.providers[0].id, "zeta");
        let alpha = manager
            .providers
            .iter()
            .find(|provider| provider.id == "alpha")
            .unwrap();
        assert!(alpha.configured_models.is_empty());
        assert_eq!(alpha.api_key_source, config::ProviderApiKeySource::Hidden);
        assert!(["mimo", "openai-codex", "deepseek", "openai"]
            .iter()
            .all(|id| manager.providers.iter().any(|provider| provider.id == *id)));
        assert!(!format!("{manager:?}").contains("literal-secret"));
    }

    #[test]
    fn provider_discover_is_exact_and_prefills_existing_add_provider_flow() {
        let temp = tempfile::tempdir().unwrap();
        let config_path = temp.path().join("config.toml");
        std::fs::write(
            &config_path,
            r#"[providers.existing]
base_url = "https://existing.invalid/v1"
api_key = ""
models = ["existing-model"]

[defaults]
provider = "existing"
model = "existing-model"
"#,
        )
        .unwrap();
        let config_store = ConfigStore::new(&config_path);
        let mut config = config_store.load().unwrap();
        let raw_before_discovery = std::fs::read_to_string(&config_path).unwrap();
        let session_store = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());

        execute_input_action(
            &mut state,
            tui::commands::InputAction::Command(tui::commands::CommandAction {
                id: tui::commands::CommandId::Provider,
                args: "discover".into(),
            }),
            &session_store,
            &mut config,
            &config_store,
        );
        assert!(state.provider_discovery.is_some());
        assert!(state.provider_discovery_requested);
        assert!(state.provider_manager.is_none());

        let candidate = provider_discovery::LocalProviderCandidate {
            provider_id: "local-11434".into(),
            port: 11434,
            base_url: "http://127.0.0.1:11434/v1".into(),
            models: vec!["coder".into(), "general".into()],
        };
        let generation = state.provider_discovery_generation;
        assert!(apply_local_provider_discovery_result(
            &mut state,
            Ok(vec![candidate.clone()]),
            generation,
        ));
        execute_input_action(
            &mut state,
            tui::commands::InputAction::OpenProviderEditor(
                crate::app::ProviderEditorRequest::AddDiscoveredProvider(candidate),
            ),
            &session_store,
            &mut config,
            &config_store,
        );
        let editor = state.provider_editor.as_ref().unwrap();
        assert_eq!(
            editor.origin,
            crate::app::ProviderEditorOrigin::ProviderDiscovery
        );
        assert_eq!(editor.draft.provider, "local-11434");
        assert_eq!(editor.draft.base_url, "http://127.0.0.1:11434/v1");
        assert_eq!(editor.draft.model, "coder");
        assert_eq!(
            std::fs::read_to_string(&config_path).unwrap(),
            raw_before_discovery
        );

        let draft = editor.draft.clone();
        execute_input_action(
            &mut state,
            tui::commands::InputAction::SaveProviderModel(draft),
            &session_store,
            &mut config,
            &config_store,
        );
        assert!(state.provider_editor.is_none());
        assert!(state.provider_discovery.is_none());
        assert_eq!(config.defaults.provider, "local-11434");
        assert_eq!(config.defaults.model, "coder");
        assert!(state.model_catalog_refresh_requested);
        assert_eq!(
            state.model_catalog_refresh_provider.as_deref(),
            Some("local-11434")
        );
    }

