    #[test]
    fn stale_or_closed_local_discovery_results_are_discarded() {
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        tui::input::open_provider_discovery(&mut state);
        state.provider_discovery_generation = 7;
        let candidate = provider_discovery::LocalProviderCandidate {
            provider_id: "local-8000".into(),
            port: 8000,
            base_url: "http://127.0.0.1:8000/v1".into(),
            models: vec!["model".into()],
        };

        assert!(!apply_local_provider_discovery_result(
            &mut state,
            Ok(vec![candidate.clone()]),
            6,
        ));
        let discovery = state.provider_discovery.as_ref().unwrap();
        assert!(discovery.scanning);
        assert!(discovery.candidates.is_empty());

        state.provider_discovery = None;
        assert!(!apply_local_provider_discovery_result(
            &mut state,
            Ok(vec![candidate]),
            7,
        ));
        assert!(state.provider_discovery.is_none());
    }

