    #[test]
    fn openai_template_prefills_and_saves_responses_without_switching_setup_default() {
        let temp = tempfile::tempdir().unwrap();
        let config_path = temp.path().join("config.toml");
        std::fs::write(
            &config_path,
            r#"# keep existing setup comment
[providers.current]
base_url = "https://current.invalid/v1"
api_key = "${CURRENT_KEY}"
models = ["current-model"]

[defaults]
provider = "current"
model = "current-model"
"#,
        )
        .unwrap();
        let config_store = ConfigStore::new(&config_path);
        let mut config = config_store.load().unwrap();
        let session_store = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.current_model = Some(ModelInfo {
            id: "current-model".into(),
            provider: "current".into(),
            display_name: "current-model".into(),
        });
        tui::input::open_provider_setup(
            &mut state,
            config_store.provider_management_entries().unwrap(),
            String::new(),
        );
        let before_open = std::fs::read_to_string(&config_path).unwrap();

        execute_input_action(
            &mut state,
            tui::commands::InputAction::OpenProviderEditor(
                crate::app::ProviderEditorRequest::AddOpenAiProvider,
            ),
            &session_store,
            &mut config,
            &config_store,
        );

        let editor = state.provider_editor.as_ref().unwrap();
        assert_eq!(editor.mode, crate::app::ProviderEditorMode::AddProvider);
        assert_eq!(
            editor.origin,
            crate::app::ProviderEditorOrigin::ProviderSetup
        );
        assert_eq!(editor.draft.provider, config::OPENAI_PROVIDER_TEMPLATE_ID);
        assert_eq!(
            editor.draft.base_url,
            config::OPENAI_PROVIDER_TEMPLATE_BASE_URL
        );
        assert_eq!(
            editor.draft.api_key_env,
            config::OPENAI_PROVIDER_TEMPLATE_API_KEY_ENV
        );
        assert_eq!(editor.draft.model, config::OPENAI_PROVIDER_TEMPLATE_MODEL);
        assert!(editor.api_key.is_empty());
        assert_eq!(
            editor.protocol_override,
            Some(crate::agent::ProviderProtocol::OpenAiResponses)
        );
        assert_eq!(editor.field, crate::app::ProviderEditorField::ApiKey);
        assert_eq!(std::fs::read_to_string(&config_path).unwrap(), before_open);

        let draft = editor.draft.clone();
        execute_input_action(
            &mut state,
            tui::commands::InputAction::SaveProviderModel(draft),
            &session_store,
            &mut config,
            &config_store,
        );

        assert!(state.provider_editor.is_none());
        assert_eq!(config.defaults.provider, "current");
        assert_eq!(config.defaults.model, "current-model");
        assert_eq!(state.current_model.as_ref().unwrap().provider, "current");
        assert_eq!(
            config.providers[config::OPENAI_PROVIDER_TEMPLATE_ID].protocol,
            crate::agent::ProviderProtocol::OpenAiResponses
        );
        assert_eq!(
            state.provider_manager.as_ref().unwrap().view,
            crate::app::ProviderManagerView::SetupProvider {
                provider: config::OPENAI_PROVIDER_TEMPLATE_ID.into()
            }
        );
        let saved = std::fs::read_to_string(&config_path).unwrap();
        assert!(saved.contains("# keep existing setup comment"));
        assert!(saved.contains("api_key = \"${OPENAI_API_KEY}\""));
        assert!(saved.contains("protocol = \"openai_responses\""));

        execute_input_action(
            &mut state,
            tui::commands::InputAction::OpenProviderEditor(
                crate::app::ProviderEditorRequest::AddOpenAiProvider,
            ),
            &session_store,
            &mut config,
            &config_store,
        );
        assert!(state.provider_editor.is_none());
        assert!(state
            .provider_manager
            .as_ref()
            .unwrap()
            .error
            .as_deref()
            .is_some_and(|error| error.contains("no changes")));
        assert_eq!(std::fs::read_to_string(config_path).unwrap(), saved);
    }

    #[test]
    fn provider_catalog_templates_save_each_supported_protocol_without_switching_setup_default() {
        for (template_id, provider_id, expected_protocol) in [
            (
                "openrouter",
                "openrouter",
                crate::agent::ProviderProtocol::ChatCompletions,
            ),
            (
                "anthropic",
                "anthropic",
                crate::agent::ProviderProtocol::AnthropicMessages,
            ),
            (
                "openai-api",
                "openai",
                crate::agent::ProviderProtocol::OpenAiResponses,
            ),
        ] {
            let temp = tempfile::tempdir().unwrap();
            let config_path = temp.path().join("config.toml");
            std::fs::write(
                &config_path,
                r#"# keep catalog install comment
[providers.current]
base_url = "https://current.invalid/v1"
api_key = "${CURRENT_KEY}"
models = ["current-model"]

[defaults]
provider = "current"
model = "current-model"
"#,
            )
            .unwrap();
            let config_store = ConfigStore::new(&config_path);
            let mut config = config_store.load().unwrap();
            let session_store = session::SessionStore::new(temp.path().join("sessions"));
            let mut state = AppState::new(crate::context::ShellHistory::in_memory());
            state.current_model = Some(ModelInfo {
                id: "current-model".into(),
                provider: "current".into(),
                display_name: "current-model".into(),
            });
            tui::input::open_provider_setup(
                &mut state,
                config_store.provider_management_entries().unwrap(),
                String::new(),
            );
            state.provider_manager.as_mut().unwrap().view =
                crate::app::ProviderManagerView::Templates {
                    return_to: crate::app::ProviderTemplateReturn::SetupProviders,
                };
            let before = std::fs::read_to_string(&config_path).unwrap();

            execute_input_action(
                &mut state,
                tui::commands::InputAction::OpenProviderEditor(
                    crate::app::ProviderEditorRequest::AddProviderTemplate(template_id.into()),
                ),
                &session_store,
                &mut config,
                &config_store,
            );
            let editor = state.provider_editor.as_ref().unwrap();
            assert_eq!(
                editor.origin,
                crate::app::ProviderEditorOrigin::ProviderSetup
            );
            assert_eq!(editor.draft.provider, provider_id);
            assert!(!editor.draft.base_url.is_empty());
            assert!(!editor.draft.model.is_empty());
            assert_eq!(editor.protocol_override, Some(expected_protocol));
            assert_eq!(std::fs::read_to_string(&config_path).unwrap(), before);

            let draft = editor.draft.clone();
            execute_input_action(
                &mut state,
                tui::commands::InputAction::SaveProviderModel(draft),
                &session_store,
                &mut config,
                &config_store,
            );
            assert_eq!(config.defaults.provider, "current");
            assert_eq!(config.defaults.model, "current-model");
            assert_eq!(config.providers[provider_id].protocol, expected_protocol);
            let saved = std::fs::read_to_string(&config_path).unwrap();
            assert!(saved.contains("# keep catalog install comment"));
            assert!(saved.contains(&format!("protocol = \"{}\"", expected_protocol.label())));
        }
    }

    #[test]
    fn provider_catalog_manager_save_selects_model_and_cancel_preserves_catalog() {
        let temp = tempfile::tempdir().unwrap();
        let config_path = temp.path().join("config.toml");
        std::fs::write(
            &config_path,
            r#"# keep manager catalog comment
[providers.current]
base_url = "https://current.invalid/v1"
api_key = "${CURRENT_KEY}"
models = ["current-model"]

[defaults]
provider = "current"
model = "current-model"
"#,
        )
        .unwrap();
        let config_store = ConfigStore::new(&config_path);
        let mut config = config_store.load().unwrap();
        let session_store = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.current_model = Some(ModelInfo {
            id: "current-model".into(),
            provider: "current".into(),
            display_name: "current-model".into(),
        });

        for (setup, return_to) in [
            (false, crate::app::ProviderTemplateReturn::Providers),
            (true, crate::app::ProviderTemplateReturn::SetupProviders),
        ] {
            let entries = config_store.provider_management_entries().unwrap();
            if setup {
                tui::input::open_provider_setup(&mut state, entries, String::new());
            } else {
                tui::input::open_provider_manager(&mut state, entries, String::new());
            }
            state.provider_manager.as_mut().unwrap().view =
                crate::app::ProviderManagerView::Templates { return_to };
            let before = std::fs::read_to_string(&config_path).unwrap();

            execute_input_action(
                &mut state,
                tui::commands::InputAction::OpenProviderEditor(
                    crate::app::ProviderEditorRequest::AddProviderTemplate("anthropic".into()),
                ),
                &session_store,
                &mut config,
                &config_store,
            );
            let expected_origin = if setup {
                crate::app::ProviderEditorOrigin::ProviderSetup
            } else {
                crate::app::ProviderEditorOrigin::ProviderManager
            };
            assert_eq!(
                state.provider_editor.as_ref().unwrap().origin,
                expected_origin
            );

            tui::input::handle_event(
                &mut state,
                &tui::event::Event::Key(
                    crossterm::event::KeyCode::Esc,
                    crossterm::event::KeyModifiers::NONE,
                ),
                ".",
            );
            assert!(state.provider_editor.is_none());
            assert_eq!(
                state.provider_manager.as_ref().unwrap().view,
                crate::app::ProviderManagerView::Templates { return_to }
            );
            assert_eq!(std::fs::read_to_string(&config_path).unwrap(), before);
            assert_eq!(config.defaults.provider, "current");
            assert_eq!(state.current_model.as_ref().unwrap().provider, "current");
        }

        tui::input::open_provider_manager(
            &mut state,
            config_store.provider_management_entries().unwrap(),
            String::new(),
        );
        state.provider_manager.as_mut().unwrap().view =
            crate::app::ProviderManagerView::Templates {
                return_to: crate::app::ProviderTemplateReturn::Providers,
            };
        execute_input_action(
            &mut state,
            tui::commands::InputAction::OpenProviderEditor(
                crate::app::ProviderEditorRequest::AddProviderTemplate("openrouter".into()),
            ),
            &session_store,
            &mut config,
            &config_store,
        );
        let draft = state.provider_editor.as_ref().unwrap().draft.clone();
        execute_input_action(
            &mut state,
            tui::commands::InputAction::SaveProviderModel(draft),
            &session_store,
            &mut config,
            &config_store,
        );

        assert_eq!(config.defaults.provider, "openrouter");
        assert_eq!(config.defaults.model, "anthropic/claude-fable-5");
        assert_eq!(state.current_model.as_ref().unwrap().provider, "openrouter");
        assert_eq!(
            state.provider_manager.as_ref().unwrap().view,
            crate::app::ProviderManagerView::Models {
                provider: "openrouter".into()
            }
        );
        let saved = std::fs::read_to_string(config_path).unwrap();
        assert!(saved.contains("# keep manager catalog comment"));
        assert!(saved.contains("protocol = \"chat_completions\""));
    }

    #[test]
    fn every_ready_provider_catalog_row_opens_an_inert_typed_editor() {
        let mut config = CaConfig::default_config();
        config.providers.clear();
        for template in crate::provider_templates::ALL
            .iter()
            .filter(|template| template.is_installable())
        {
            let mut state = AppState::new(crate::context::ShellHistory::in_memory());
            let editor = provider_template_editor(
                &mut state,
                &config,
                crate::app::ProviderEditorOrigin::ProviderManager,
                template,
            )
            .unwrap_or_else(|| panic!("ready template {} did not open", template.id));
            assert_eq!(editor.mode, crate::app::ProviderEditorMode::AddProvider);
            assert_eq!(editor.draft.provider, template.provider_id);
            assert_eq!(editor.draft.base_url, template.base_url.unwrap_or_default());
            assert_eq!(
                editor.draft.api_key_env,
                template.api_key_env.unwrap_or_default()
            );
            assert_eq!(
                editor.draft.model,
                template.starter_model.unwrap_or_default()
            );
            assert_eq!(editor.protocol_override, template.protocol);
            assert!(editor.api_key.is_empty());
            assert!(state.status_message.is_none());
        }
    }

