    #[test]
    fn provider_delete_switches_to_sorted_discovered_replacement_and_persists_it() {
        let temp = tempfile::tempdir().unwrap();
        let config_path = temp.path().join("config.toml");
        std::fs::write(
            &config_path,
            r#"[providers.old]
base_url = "https://old.invalid/v1"
api_key = "${OLD_KEY}"
models = ["current"]

[providers.backup]
base_url = "https://backup.invalid/v1"
api_key = "${BACKUP_KEY}"
models = []

[defaults]
provider = "old"
model = "current"
"#,
        )
        .unwrap();
        let config_store = ConfigStore::new(&config_path);
        let mut config = config_store.load().unwrap();
        let session_store = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.current_model = Some(ModelInfo {
            id: "current".into(),
            provider: "old".into(),
            display_name: "current".into(),
        });
        state.model_list = vec![
            state.current_model.clone().unwrap(),
            ModelInfo {
                id: "live-only".into(),
                provider: "backup".into(),
                display_name: "live-only".into(),
            },
        ];
        tui::input::open_provider_manager(
            &mut state,
            config_store.provider_management_entries().unwrap(),
            String::new(),
        );

        execute_input_action(
            &mut state,
            tui::commands::InputAction::RequestDeleteProvider("old".into()),
            &session_store,
            &mut config,
            &config_store,
        );
        let confirmation = state
            .provider_manager
            .as_ref()
            .unwrap()
            .delete_confirmation
            .as_ref()
            .unwrap();
        assert!(!confirmation.confirm_selected);
        assert_eq!(
            confirmation.replacement.as_ref().unwrap().provider,
            "backup"
        );
        assert_eq!(confirmation.replacement.as_ref().unwrap().id, "live-only");
        let replacement = confirmation.replacement.clone();

        execute_input_action(
            &mut state,
            tui::commands::InputAction::DeleteProvider {
                provider: "old".into(),
                replacement,
            },
            &session_store,
            &mut config,
            &config_store,
        );

        assert!(!config.providers.contains_key("old"));
        assert_eq!(state.current_model.as_ref().unwrap().provider, "backup");
        assert_eq!(state.current_model.as_ref().unwrap().id, "live-only");
        assert_eq!(config.defaults.provider, "backup");
        assert_eq!(config.defaults.model, "live-only");
        assert_eq!(config.providers["backup"].models, ["live-only"]);
        assert_eq!(
            state.status_message.as_deref(),
            Some("Deleted provider old · switched to backup/live-only")
        );
    }

