    #[test]
    fn provider_editor_action_stores_a_direct_key_outside_config_and_selects_model() {
        let temp = tempfile::tempdir().unwrap();
        let config_path = temp.path().join("config.toml");
        std::fs::write(&config_path, "# keep direct-key comment\n").unwrap();
        let secrets = Arc::new(FakeProviderSecrets::default());
        let config_store = ConfigStore::with_secret_store(&config_path, secrets.clone());
        let mut config = config_store.load().unwrap();
        let session_store = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());

        execute_input_action(
            &mut state,
            tui::commands::InputAction::OpenProviderEditor(
                crate::app::ProviderEditorRequest::AddProvider,
            ),
            &session_store,
            &mut config,
            &config_store,
        );
        let editor = state.provider_editor.as_mut().unwrap();
        editor.draft.provider = "mimo".into();
        editor.draft.base_url = "https://example.invalid/v1".into();
        editor.draft.model = "mimo-v2.5-pro".into();
        editor.api_key = crate::provider_secrets::SecretValue::from_text("not-a-real-secret");
        let draft = editor.draft.clone();

        execute_input_action(
            &mut state,
            tui::commands::InputAction::SaveProviderModel(draft),
            &session_store,
            &mut config,
            &config_store,
        );

        assert!(state.provider_editor.is_none());
        assert_eq!(state.current_model.as_ref().unwrap().id, "mimo-v2.5-pro");
        assert_eq!(config.providers["mimo"].api_key, "not-a-real-secret");
        assert_eq!(secrets.values.lock().unwrap()["mimo"], b"not-a-real-secret");
        let raw = std::fs::read_to_string(config_path).unwrap();
        assert!(raw.contains("# keep direct-key comment"));
        assert!(raw.contains("credential://ca/provider/mimo"));
        assert!(!raw.contains("not-a-real-secret"));
    }

