    fn native_codex_test_config() -> CaConfig {
        let mut config = CaConfig::default();
        let mut provider =
            provider_connect::FirstClassProvider::OpenAiCodex.candidate(String::new(), None);
        provider.models = vec!["configured-only".into()];
        config.providers = std::collections::HashMap::from([("openai-codex".into(), provider)]);
        config.defaults.provider = "openai-codex".into();
        config.defaults.model = "configured-only".into();
        config
    }

    fn native_codex_test_refresh(models: Option<Vec<String>>) -> model_catalog::CatalogRefresh {
        model_catalog::CatalogRefresh {
            catalogs: models
                .map(|models| std::collections::HashMap::from([("openai-codex".into(), models)]))
                .unwrap_or_default(),
            documented: std::collections::HashMap::from([(
                "openai-codex".into(),
                vec!["gpt-5.6-sol".into(), "not-live-fallback".into()],
            )]),
            failures: vec![],
        }
    }

    #[test]
    fn native_codex_refresh_is_authoritative_and_retains_last_success_in_both_views() {
        for scoped in [false, true] {
            let config = native_codex_test_config();
            let mut state = AppState::new(crate::context::ShellHistory::in_memory());
            let current = ModelInfo {
                id: "session-only".into(),
                display_name: "session-only".into(),
                provider: "openai-codex".into(),
            };
            state.current_model = Some(current.clone());
            let live = model_catalog::codex_fixture_models();
            let apply = |state: &mut AppState, refresh| {
                if scoped {
                    apply_provider_catalog_refresh(state, &config, refresh, "openai-codex");
                } else {
                    apply_model_catalog_refresh(state, &config, refresh);
                }
            };
            apply(&mut state, native_codex_test_refresh(Some(live.clone())));
            assert_eq!(state.discovered_models["openai-codex"], live);
            assert_eq!(state.model_list.len(), live.len() + 2);
            assert_eq!(
                state.model_catalog_provider_status["openai-codex"],
                "live · 7 models"
            );
            assert!(state.model_is_configured_only(&current));
            assert!(state
                .model_list
                .iter()
                .find(|model| model.id == "configured-only")
                .is_some_and(|model| state.model_is_configured_only(model)));
            assert!(!state
                .model_list
                .iter()
                .any(|model| model.id == "not-live-fallback"));
            assert_eq!(
                tui::input::selected_picker_model(&state),
                Some(current.clone())
            );

            let spark = state
                .model_list
                .iter()
                .find(|model| model.id == "gpt-5.3-codex-spark")
                .unwrap()
                .clone();
            state
                .model_preferences
                .record_selection(&current, chrono::Utc::now())
                .unwrap();
            state.model_picker_open = true;
            state.selected_model_idx = tui::input::visible_model_rows(&state)
                .iter()
                .position(|row| row.model == spark)
                .unwrap();
            for _ in 0..2 {
                let mut failed = native_codex_test_refresh(None);
                failed.failures = vec![("openai-codex".into(), "HTTP 503\u{1b}[31m".into())];
                apply(&mut state, failed);
                assert_eq!(state.discovered_models["openai-codex"], live);
                assert_eq!(state.codex_catalogs["openai-codex"], live);
                assert_eq!(
                    state.model_catalog_provider_status["openai-codex"],
                    "cached · HTTP 503"
                );
                assert_eq!(
                    tui::input::selected_picker_model(&state),
                    Some(spark.clone())
                );
                assert_eq!(state.current_model, Some(current.clone()));
                assert!(!state.model_is_configured_only(&spark));
            }
            apply(
                &mut state,
                native_codex_test_refresh(Some(vec!["gpt-5.4".into()])),
            );
            assert_eq!(state.discovered_models["openai-codex"], ["gpt-5.4"]);
            assert_eq!(
                state.model_catalog_provider_status["openai-codex"],
                "live · 1 model"
            );
            assert_eq!(state.model_list.len(), 3);
        }
    }

    #[test]
    fn native_codex_empty_success_stays_empty_after_failure_in_both_views() {
        for scoped in [false, true] {
            let config = native_codex_test_config();
            let mut state = AppState::new(crate::context::ShellHistory::in_memory());
            for models in [Some(Vec::new()), None] {
                let mut refresh = native_codex_test_refresh(models);
                if refresh.catalogs.is_empty() {
                    refresh
                        .failures
                        .push(("openai-codex".into(), "request timed out".into()));
                }
                if scoped {
                    apply_provider_catalog_refresh(&mut state, &config, refresh, "openai-codex");
                } else {
                    apply_model_catalog_refresh(&mut state, &config, refresh);
                }
                assert!(state.codex_catalogs["openai-codex"].is_empty());
                assert!(state.discovered_models["openai-codex"].is_empty());
                assert_eq!(state.model_list.len(), 1);
                assert!(state.model_is_configured_only(&state.model_list[0]));
            }
            assert_eq!(
                state.model_catalog_provider_status["openai-codex"],
                "cached · request timed out"
            );
        }
    }

    #[test]
    fn native_codex_catalog_model_beyond_gpt56_can_be_selected_without_profile_changes() {
        let temp = tempfile::tempdir().unwrap();
        let config_store = ConfigStore::new(temp.path().join("config.toml"));
        let session_store = session::SessionStore::new(temp.path().join("sessions"));
        let mut config = native_codex_test_config();
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.active_profile = runtime::ActiveProfile::Bare;
        state.run_capabilities = runtime::RunCapabilities::for_profile(&state.active_profile);
        state.model_preferences_store = model_preferences::ModelPreferencesStore::unavailable();
        apply_model_catalog_refresh(
            &mut state,
            &config,
            native_codex_test_refresh(Some(model_catalog::codex_fixture_models())),
        );
        let model = state
            .model_list
            .iter()
            .find(|model| model.id == "gpt-5.3-codex-spark")
            .unwrap()
            .clone();
        execute_input_action(
            &mut state,
            tui::commands::InputAction::SelectModel(model.clone()),
            &session_store,
            &mut config,
            &config_store,
        );
        assert_eq!(state.current_model, Some(model));
        assert_eq!(
            config.providers["openai-codex"].models,
            ["configured-only", "gpt-5.3-codex-spark"]
        );
        assert!(config
            .effective_model_profile("openai-codex", "gpt-5.3-codex-spark")
            .is_none());
        assert!(!temp.path().join("config.toml").exists());
    }

