    #[test]
    fn session_identity_is_allocated_and_named_before_the_first_turn() {
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.current_model = Some(ModelInfo {
            provider: "mimo".into(),
            id: "mimo-v2.5-pro".into(),
            display_name: "MiMo".into(),
        });
        state.messages.push(Message {
            role: Role::User,
            content: "Check rsync on BSD via SSH".into(),
            tool_calls: None,
            thinking: None,
            timestamp: chrono::Utc::now(),
            response_items: Vec::new(),
        });

        ensure_session_identity(&mut state);
        let session = state.current_session.as_ref().unwrap();
        assert_eq!(state.session_name, "Check rsync on BSD via SSH");
        assert_eq!(session.title, state.session_name);
        assert_eq!(state.job_owner.session_id, Some(session.id));
        assert!(state.session_title_pending);
        assert_eq!(state.session_title_generation, 1);

        let id = session.id;
        state.session_name = "Manual title".into();
        ensure_session_identity(&mut state);
        assert_eq!(state.current_session.as_ref().unwrap().id, id);
        assert_eq!(
            state.current_session.as_ref().unwrap().title,
            "Manual title"
        );
    }

    #[test]
    fn generated_session_title_applies_only_to_the_matching_pending_session() {
        let temp = tempfile::tempdir().unwrap();
        let store = session::SessionStore::new(temp.path());
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.messages.push(Message {
            role: Role::User,
            content: "Investigate a FreeBSD MOTD freeze".into(),
            tool_calls: None,
            thinking: None,
            timestamp: chrono::Utc::now(),
            response_items: Vec::new(),
        });
        ensure_session_identity(&mut state);
        let session_id = state.current_session.as_ref().unwrap().id;

        apply_session_title_result(
            &mut state,
            &store,
            SessionTitleTaskResult {
                target: SessionTitleTarget::Current { session_id },
                generation: 1,
                outcome: Ok(SessionTitleSuccess::Current(
                    "Fix FreeBSD MOTD freeze".into(),
                )),
            },
        );
        assert_eq!(state.session_name, "Fix FreeBSD MOTD freeze");
        assert!(!state.session_title_pending);

        state.session_title_generation = 2;
        apply_session_title_result(
            &mut state,
            &store,
            SessionTitleTaskResult {
                target: SessionTitleTarget::Current { session_id },
                generation: 1,
                outcome: Ok(SessionTitleSuccess::Current("Stale overwrite".into())),
            },
        );
        assert_eq!(state.session_name, "Fix FreeBSD MOTD freeze");
    }

