    #[test]
    fn cli_parser_accepts_doctor_without_reinterpreting_positional_prompts() {
        let doctor = parse_cli_args(["ca", "--doctor", "--connect", "--output-format", "json"])
            .expect("valid doctor arguments");
        assert!(doctor.doctor);
        assert!(doctor.connect);
        assert_eq!(doctor.output_format, headless::OutputFormat::Json);

        let prompt = parse_cli_args(["ca", "doctor"]).expect("positional prompt remains valid");
        assert!(!prompt.doctor);
        assert_eq!(prompt.one_shot_prompt.as_deref(), Some("doctor"));

        let conflict = parse_cli_args(["ca", "--doctor", "diagnose"])
            .expect_err("doctor cannot consume a prompt");
        assert_eq!(conflict.kind(), clap::error::ErrorKind::ArgumentConflict);
        let jsonl = parse_cli_args(["ca", "--doctor", "--output-format", "jsonl"])
            .expect_err("doctor is an aggregate report");
        assert_eq!(jsonl.kind(), clap::error::ErrorKind::InvalidValue);

        let contracts = parse_cli_args([
            "ca",
            "--doctor",
            "--connect",
            "--provider-contract",
            "openai",
            "--provider-contract",
            "mimo",
        ])
        .expect("provider contracts are explicit and repeatable");
        assert_eq!(
            contracts.provider_contracts,
            [
                provider_contract_verifier::ProviderContractTarget::Openai,
                provider_contract_verifier::ProviderContractTarget::Mimo
            ]
        );
        assert!(parse_cli_args(["ca", "--doctor", "--provider-contract", "deepseek"]).is_err());
    }

