    #[test]
    fn goal_commands_persist_start_pause_resume_and_clear_transitions() {
        let temp = tempfile::tempdir().unwrap();
        let config_path = temp.path().join("config.toml");
        std::fs::write(&config_path, "# goal test\n").unwrap();
        let config_store = ConfigStore::new(&config_path);
        let config = config_store.load().unwrap();
        let sessions = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.cwd = temp.path().display().to_string();

        let run = |state: &mut AppState, args: &str| {
            execute_command_action(
                state,
                tui::commands::CommandAction {
                    id: tui::commands::CommandId::Goal,
                    args: args.into(),
                },
                &sessions,
                &config,
                &config_store,
            );
        };

        run(&mut state, "prove the bounded change --iterations 2");
        assert_eq!(
            state.goal_state.as_ref().map(|goal| goal.status),
            Some(goal::GoalStatus::Active)
        );
        assert!(state.goal_resume_requested);
        assert!(state.goal_continuation_prompt.is_some());

        run(&mut state, "pause");
        assert_eq!(
            state.goal_state.as_ref().map(|goal| goal.status),
            Some(goal::GoalStatus::Paused)
        );
        assert!(!state.goal_resume_requested);

        run(&mut state, "resume");
        assert_eq!(
            state.goal_state.as_ref().map(|goal| goal.status),
            Some(goal::GoalStatus::Active)
        );
        assert!(state.goal_resume_requested);

        run(&mut state, "clear");
        assert_eq!(
            state.goal_state.as_ref().map(|goal| goal.status),
            Some(goal::GoalStatus::Cleared)
        );
        let storage_key = state.current_session.as_ref().unwrap().id.to_string();
        let saved = sessions.load(&storage_key).unwrap();
        assert_eq!(
            saved.goal_state.map(|goal| goal.status),
            Some(goal::GoalStatus::Cleared)
        );
    }

