    #[test]
    fn worktree_command_parses_actions_and_enforces_bare_and_busy_guards() {
        let mut state = AppState::new(context::ShellHistory::in_memory());
        manage_worktree_command(&mut state, "status deadbeef");
        assert!(matches!(
            state.worktree_request.as_ref().map(|request| &request.action),
            Some(worktree::WorktreeAction::Status { id }) if id == "deadbeef"
        ));

        state.worktree_request = None;
        state.worktree_busy = false;
        state.active_profile = runtime::ActiveProfile::Bare;
        state.run_capabilities = runtime::RunCapabilities::for_profile(&state.active_profile);
        manage_worktree_command(&mut state, "create review HEAD");
        assert!(state.worktree_request.is_none());
        assert!(state.status_message.as_deref().unwrap().contains("bare"));

        state.active_profile = runtime::ActiveProfile::Default;
        state.run_capabilities = runtime::RunCapabilities::for_profile(&state.active_profile);
        state.turn_lifecycle.begin();
        manage_worktree_command(&mut state, "attach deadbeef");
        assert!(state.worktree_request.is_none());
        assert!(state.status_message.as_deref().unwrap().contains("idle"));

        state.turn_lifecycle.reset();
        manage_worktree_command(&mut state, "create invalid extra arguments");
        assert!(state.worktree_request.is_none());
        assert!(state.status_message.as_deref().unwrap().contains("Usage"));
    }

    #[test]
    fn worktree_attachment_updates_workspace_and_session_but_exports_portably() {
        let home = tempfile::tempdir().unwrap();
        let launch = tempfile::tempdir().unwrap();
        let attached = tempfile::tempdir().unwrap();
        let paths = runtime::RuntimePaths::from_home(home.path());
        let config = CaConfig::default_config();
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.workspace = workspace::WorkspaceContext::discover(launch.path()).unwrap();
        state.cwd = state.workspace.cwd().to_string_lossy().into_owned();
        state.current_session = Some(session::SessionV2::new(
            "worktree session",
            state.cwd.clone(),
            "local",
            "model",
            Vec::new(),
        ));
        let id = uuid::Uuid::new_v4();
        let record = worktree::WorktreeRecord {
            id,
            label: "review".into(),
            repository_root: launch.path().canonicalize().unwrap(),
            path: attached.path().canonicalize().unwrap(),
            branch: format!("ca/review-{}", &id.simple().to_string()[..8]),
            base_commit: "0".repeat(40),
            git_common_dir: launch.path().canonicalize().unwrap(),
            created_at: chrono::Utc::now(),
        };
        let context =
            workspace::WorkspaceContext::from_primary(record.path.clone(), record.path.clone());

        apply_worktree_attachment(&mut state, &config, &paths, record.clone(), context).unwrap();

        assert_eq!(state.workspace.primary().unwrap().path, record.path);
        assert_eq!(state.cwd, record.path.to_string_lossy());
        assert_eq!(
            state.attached_worktree.as_ref().map(|value| value.id),
            Some(id)
        );
        assert_eq!(
            state
                .current_session
                .as_ref()
                .and_then(|session| session.attached_worktree.as_ref())
                .map(|value| value.id),
            Some(id)
        );
        assert!(portable_session_snapshot(&state)
            .attached_worktree
            .is_none());

        let sessions = session::SessionStore::new(home.path().join("sessions"));
        let saved_id = save_current_session(&mut state, &sessions).unwrap();
        assert_eq!(
            sessions
                .load(&saved_id.to_string())
                .unwrap()
                .attached_worktree
                .map(|value| value.id),
            Some(id)
        );
    }

