    #[tokio::test]
    async fn workflow_step_request_is_transient_exact_route_and_tool_restricted() {
        let mut config = CaConfig::default_config();
        config.providers = std::collections::HashMap::from([(
            "workflow-provider".into(),
            config::ProviderConfig {
                google: None,
                tool_schema_policy: Default::default(),
                base_url: "http://127.0.0.1:1/v1".into(),
                api_key: "${CA_WFL070_INTENTIONALLY_MISSING}".into(),
                protocol: agent::ProviderProtocol::default(),
                prompt_cache_mode: crate::config::PromptCacheMode::Implicit,
                models: vec!["workflow-model".into()],
                timeout: config::ProviderTimeoutConfig::default(),
            },
        )]);
        config.defaults.provider = "workflow-provider".into();
        config.defaults.model = "workflow-model".into();
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.current_model = Some(ModelInfo {
            provider: "workflow-provider".into(),
            id: "workflow-model".into(),
            display_name: "workflow-model".into(),
        });
        state.messages.push(Message {
            role: Role::User,
            content: "canonical history marker".into(),
            tool_calls: None,
            thinking: None,
            timestamp: chrono::Utc::now(),
            response_items: Vec::new(),
        });
        state.workflow_execution = Some(crate::workflow::WorkflowExecutionContext {
            step_id: "verify".into(),
            provider: "workflow-provider".into(),
            model: "workflow-model".into(),
            tools: Some(["read_file".to_string()].into_iter().collect()),
            grants: Vec::new(),
        });
        state.workflow_control_prompt = Some(crate::workflow::WorkflowControlPrompt::new(
            "workflow-only prompt marker".into(),
        ));
        let canonical_before = serde_json::to_string(&state.messages).unwrap();
        let (tx, _rx) = tokio::sync::mpsc::unbounded_channel();
        let mut handle = None;

        start_llm_turn(&mut state, &config, &tx, &mut handle);
        handle.take().unwrap().await.unwrap();

        let snapshot = state.request_store.snapshot().unwrap();
        assert_eq!(snapshot.kind, crate::request::RequestKind::WorkflowStep);
        assert_eq!(snapshot.provider, "workflow-provider");
        assert_eq!(snapshot.model, "workflow-model");
        assert_eq!(
            snapshot
                .schemas
                .iter()
                .map(|schema| schema.name.as_str())
                .collect::<Vec<_>>(),
            vec!["read_file"]
        );
        assert!(snapshot
            .messages
            .iter()
            .any(|message| message.content.contains("workflow-only prompt marker")));
        assert_eq!(
            serde_json::to_string(&state.messages).unwrap(),
            canonical_before
        );
        assert_eq!(
            state.usage_ledger.lock().unwrap().snapshot().records[0].kind,
            usage::UsageKind::WorkflowStep
        );
    }

    #[tokio::test]
    async fn workflow_scheduler_runs_dependency_chain_and_persists_bounded_outputs() {
        let (base_url, captured) = test_provider_sequence(vec![
            ("200 OK", btw_complete_stream("FIRST RESULT")),
            ("200 OK", btw_complete_stream("SECOND RESULT")),
        ])
        .await;
        let mut config = CaConfig::default_config();
        config.providers = std::collections::HashMap::from([(
            "local".into(),
            config::ProviderConfig {
                google: None,
                tool_schema_policy: Default::default(),
                base_url,
                api_key: String::new(),
                protocol: agent::ProviderProtocol::default(),
                prompt_cache_mode: crate::config::PromptCacheMode::Implicit,
                models: vec!["workflow-model".into()],
                timeout: config::ProviderTimeoutConfig::default(),
            },
        )]);
        config.defaults.provider = "local".into();
        config.defaults.model = "workflow-model".into();
        let loaded = crate::workflow::LoadedWorkflow {
            definition: crate::workflow::WorkflowDefinition {
                version: 1,
                id: "chain".into(),
                title: "Chain".into(),
                steps: vec![
                    crate::workflow::WorkflowStep {
                        id: "first".into(),
                        depends_on: Vec::new(),
                        prompt: "Produce the first result".into(),
                        model: Some("local/workflow-model".into()),
                        tools: Some(Vec::new()),
                        grants: Vec::new(),
                        retry: crate::workflow::WorkflowRetryPolicy::default(),
                        output: Some("first_result".into()),
                        evidence: vec![crate::workflow::WorkflowEvidenceGate::AssistantOutput],
                    },
                    crate::workflow::WorkflowStep {
                        id: "second".into(),
                        depends_on: vec!["first".into()],
                        prompt: "Use the dependency result".into(),
                        model: None,
                        tools: Some(Vec::new()),
                        grants: Vec::new(),
                        retry: crate::workflow::WorkflowRetryPolicy::default(),
                        output: Some("second_result".into()),
                        evidence: vec![crate::workflow::WorkflowEvidenceGate::AssistantOutput],
                    },
                ],
            }
            .validate()
            .unwrap(),
            relative_path: "workflow.toml".into(),
            digest: "0123456789abcdef".into(),
        };
        let temp = tempfile::tempdir().unwrap();
        let sessions = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.cwd = temp.path().display().to_string();
        state.workspace = crate::workspace::WorkspaceContext::from_primary(
            temp.path().to_path_buf(),
            temp.path().to_path_buf(),
        );
        state.current_model = Some(ModelInfo {
            provider: "local".into(),
            id: "workflow-model".into(),
            display_name: "workflow-model".into(),
        });
        state.workflow_loaded = Some(loaded.clone());
        state.workflow_run = Some(crate::workflow::WorkflowRun::start(
            &loaded,
            "local".into(),
            "workflow-model".into(),
            chrono::Utc::now(),
        ));
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        let mut handle = None;

        for (index, expected) in ["FIRST RESULT", "SECOND RESULT"].into_iter().enumerate() {
            if index == 0 {
                start_next_workflow_step(&mut state, &config, &sessions, &tx, &mut handle).unwrap();
            }
            handle.take().unwrap().await.unwrap();
            loop {
                match tokio::time::timeout(std::time::Duration::from_secs(2), rx.recv())
                    .await
                    .unwrap()
                    .unwrap()
                {
                    StreamMsg::PromptToolsPrepared { tools, .. } => {
                        if let Some(prompt) = state.active_turn_prompt.as_mut() {
                            prompt.canonical_tools = Some(tools);
                        }
                    }
                    StreamMsg::ContextPrepared(breakdown, tool_names, _) => {
                        state.context_breakdown = Some(breakdown);
                        state.active_tool_names = tool_names.into_iter().collect();
                    }
                    StreamMsg::Delta(delta, _) => handle_stream_delta(&mut state, delta),
                    StreamMsg::Finish(_) => break,
                    StreamMsg::HarnessPrepared(snapshot, _) => {
                        state.outcome_tracker.set_runtime_harness(snapshot)
                    }
                    StreamMsg::RecoveryPrepared(frozen, generation) => {
                        assert!(frozen.prepared.tools.is_empty());
                        capture_recovery_request(&mut state, *frozen, generation);
                    }
                    StreamMsg::RecoveryTurnRetired {
                        session_id,
                        turn_id,
                        warning,
                    } => {
                        state.recovery_retiring.remove(&turn_id);
                        apply_recovery_retirement(&mut state, session_id, turn_id, warning);
                    }
                    StreamMsg::AwaitingProvider(_) => {}
                    _ => panic!("unexpected workflow stream event"),
                }
            }
            finish_active_usage(&state, usage::UsageOutcome::Completed);
            let streaming = state.streaming.take().unwrap();
            assert_eq!(streaming.content, expected);
            state.messages.push(Message {
                role: Role::Assistant,
                content: streaming.content.clone(),
                tool_calls: None,
                thinking: streaming.thinking,
                timestamp: chrono::Utc::now(),
                response_items: Vec::new(),
            });
            assert!(advance_workflow_after_response(
                &mut state,
                &config,
                &sessions,
                &tx,
                &mut handle,
                &streaming.content,
            ));
        }

        let run = state.workflow_run.as_ref().unwrap();
        assert_eq!(run.status, crate::workflow::WorkflowRunStatus::Complete);
        assert_eq!(run.steps[0].output.as_deref(), Some("FIRST RESULT"));
        assert_eq!(run.steps[1].output.as_deref(), Some("SECOND RESULT"));
        assert!(state
            .messages
            .iter()
            .all(|message| !message.content.contains("Execute declarative workflow")));
        let requests = captured.await.unwrap();
        assert_eq!(requests.len(), 2);
        let first = String::from_utf8_lossy(&requests[0]);
        let second = String::from_utf8_lossy(&requests[1]);
        assert!(first.contains("Produce the first result"));
        assert!(!first.contains("BEGIN UNTRUSTED OUTPUT"));
        assert!(second.contains("Use the dependency result"));
        assert!(second.contains("BEGIN UNTRUSTED OUTPUT first_result"));
        assert!(second.contains("FIRST RESULT"));
        assert!(!first.contains("\"tools\""));
        assert!(!second.contains("\"tools\""));
        let storage_key = state.current_session.as_ref().unwrap().id.to_string();
        assert_eq!(
            sessions
                .load(&storage_key)
                .unwrap()
                .workflow_run
                .unwrap()
                .status,
            crate::workflow::WorkflowRunStatus::Complete
        );
    }

    #[test]
    fn hook_manager_reload_and_toggle_return_only_safe_state() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("config.toml");
        let secret_marker = "SECRET-HOOK-COMMAND-MARKER";
        std::fs::write(
            &path,
            format!(
                "# preserved\n[[hooks]]\nevent = \"pre_tool_use\"\ncommand = \"printf {secret_marker}\"\nenabled = true # enabled comment\n"
            ),
        )
        .unwrap();
        let store = ConfigStore::new(&path);
        let runner = hooks::HookRunner::new(Vec::new(), sandbox::SandboxMode::PolicyOnly);
        let loaded = perform_hook_manager_reload(&store, &runner).unwrap();
        assert_eq!(loaded.snapshot.entries.len(), 1);
        assert!(!format!("{:?}", loaded.snapshot).contains(secret_marker));

        let toggled =
            perform_hook_manager_toggle(&store, &runner, 0, hooks::HookEvent::PreToolUse, false)
                .unwrap();
        assert!(!toggled.snapshot.entries[0].enabled);
        let raw = std::fs::read_to_string(&path).unwrap();
        assert!(raw.contains("# preserved"));
        assert!(raw.contains("enabled = false # enabled comment"));

        std::fs::write(
            &path,
            format!("[[hooks]]\nevent = \"unknown\"\ncommand = \"printf {secret_marker}\"\n"),
        )
        .unwrap();
        let error = match perform_hook_manager_reload(&store, &runner) {
            Ok(_) => panic!("invalid hook config unexpectedly reloaded"),
            Err(error) => error,
        };
        assert_eq!(
            error,
            "Could not reload hooks; fix config.toml and press Shift+R"
        );
        assert!(!error.contains(secret_marker));
    }

