    #[test]
    fn prompt_stash_commands_swap_text_and_force_attachment_revalidation() {
        let temp = tempfile::tempdir().unwrap();
        let root = temp.path().canonicalize().unwrap();
        let config_path = root.join("config.toml");
        std::fs::write(&config_path, "# preserved\n").unwrap();
        let store = ConfigStore::new(&config_path);
        let mut config = store.load().unwrap();
        let sessions = session::SessionStore::new(root.join("sessions"));
        let attachment = root.join("note.txt");
        std::fs::write(&attachment, "first\nsecond\n").unwrap();
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.workspace = workspace::WorkspaceContext::from_primary(root.clone(), root.clone());
        state.cwd = root.display().to_string();
        state.prompt_stash_store =
            prompt_stash::PromptStashStore::for_profile(&root, &root.join("profile"), true)
                .unwrap();
        state.input = "Review @note.txt#1".into();
        state.input_cursor = state.input.len();
        let root_id = state.workspace.primary().unwrap().id.to_string();
        state
            .composer_attachments
            .push(attachments::ComposerAttachment {
                reference: "note.txt".into(),
                kind: attachments::ComposerAttachmentKind::File {
                    root_id,
                    relative: "note.txt".into(),
                },
            });

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::Stash,
                args: "save".into(),
            },
            &sessions,
            &config,
            &store,
        );
        assert!(state.input.is_empty());
        assert!(state.composer_attachments.is_empty());
        let saved = state.prompt_stash_store.load().unwrap();
        assert_eq!(saved.len(), 1);

        state.input = "current replacement @note.txt".into();
        state.input_cursor = state.input.len();
        state
            .composer_attachments
            .push(attachments::ComposerAttachment {
                reference: "note.txt".into(),
                kind: attachments::ComposerAttachmentKind::File {
                    root_id: state.workspace.primary().unwrap().id.to_string(),
                    relative: "note.txt".into(),
                },
            });
        execute_input_action(
            &mut state,
            tui::commands::InputAction::RestorePromptDraft(saved[0].id),
            &sessions,
            &mut config,
            &store,
        );
        assert_eq!(state.input, "Review @note.txt#1");
        assert!(state.composer_attachments.is_empty());
        assert!(state
            .prompt_stash_store
            .load()
            .unwrap()
            .iter()
            .any(|entry| entry.text == "current replacement @note.txt"));

        std::fs::remove_file(attachment).unwrap();
        let expanded = expand_file_mentions(&state.input, &state.workspace, &[]).unwrap();
        assert!(expanded.contains("(file not found: note.txt#1)"));

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::Stash,
                args: String::new(),
            },
            &sessions,
            &config,
            &store,
        );
        assert_eq!(state.prompt_stash.as_ref().unwrap().entries.len(), 1);
    }

    #[test]
    fn prompt_stash_expands_registered_large_pastes_before_persistence() {
        let temp = tempfile::tempdir().unwrap();
        let root = temp.path().canonicalize().unwrap();
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.prompt_stash_store =
            prompt_stash::PromptStashStore::for_profile(&root, &root.join("profile"), true)
                .unwrap();
        let payload = "stored payload ".repeat(100);
        let marker = tui::composer::large_paste_placeholder(payload.chars().count());
        state.input = format!("before {marker} after");
        state.input_cursor = state.input.len();
        let start = "before ".len();
        state
            .composer_ui
            .register_large_paste(start..start + marker.len(), payload.clone());

        save_prompt_draft(&mut state);

        let saved = state.prompt_stash_store.load().unwrap();
        assert_eq!(saved.len(), 1);
        assert_eq!(saved[0].text, format!("before {payload} after"));
        assert!(state.input.is_empty());
        assert!(state.composer_ui.atomic_elements.is_empty());
    }

