    #[test]
    fn context_limit_command_targets_current_or_exact_configured_model() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("config.toml");
        std::fs::write(
            &path,
            r#"[providers.mimo]
base_url = "https://safe.invalid/v1"
api_key = ""
models = ["base", "pro"]

[defaults]
provider = "mimo"
model = "base"

[model_context."mimo/base"]
context_window_tokens = 32000
"#,
        )
        .unwrap();
        let store = ConfigStore::new(&path);
        let config = store.load().unwrap();
        let sessions = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.current_model = Some(ModelInfo {
            provider: "mimo".into(),
            id: "base".into(),
            display_name: "base".into(),
        });

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::ContextLimit,
                args: String::new(),
            },
            &sessions,
            &config,
            &store,
        );
        let current = state.context_limit_editor.take().unwrap();
        assert_eq!(
            (current.provider.as_str(), current.model.as_str()),
            ("mimo", "base")
        );
        assert_eq!(current.window_input, "32000");

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::ContextLimit,
                args: "mimo/pro".into(),
            },
            &sessions,
            &config,
            &store,
        );
        assert_eq!(state.context_limit_editor.as_ref().unwrap().model, "pro");

        state.context_limit_editor = None;
        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::ContextLimit,
                args: "mimo/missing".into(),
            },
            &sessions,
            &config,
            &store,
        );
        assert!(state.context_limit_editor.is_none());
        assert_eq!(
            state.status_message.as_deref(),
            Some("Unknown configured model: mimo/missing")
        );
    }

