    #[test]
    fn context_limit_save_failure_keeps_editor_and_draft() {
        let store = ConfigStore::for_profile(
            std::path::PathBuf::from("/unused/config.toml"),
            runtime::ActiveProfile::Bare,
        );
        let mut config = CaConfig::default_config();
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.current_model = Some(ModelInfo {
            provider: config.defaults.provider.clone(),
            id: config.defaults.model.clone(),
            display_name: config.defaults.model.clone(),
        });
        open_context_limit_editor(&mut state, &config, "");
        let editor = state.context_limit_editor.as_mut().unwrap();
        editor.window_input = "12345".into();
        editor.saving = true;
        let update = config::ContextLimitUpdate {
            provider: editor.provider.clone(),
            model: editor.model.clone(),
            context_window_tokens: Some(12_345),
            compact_at_tokens: None,
        };

        let result = perform_context_limit_save(&store, update);
        apply_context_limit_save_result(&mut state, &mut config, result);

        let editor = state.context_limit_editor.unwrap();
        assert_eq!(editor.window_input, "12345");
        assert!(!editor.saving);
        assert!(editor.error.unwrap().contains("Could not save"));
    }

