    #[test]
    fn project_instruction_discovery_stops_at_git_workspace_root() {
        let parent = tempfile::tempdir().unwrap();
        let root = parent.path().join("workspace");
        let nested = root.join("src/nested");
        std::fs::create_dir_all(&nested).unwrap();
        let status = std::process::Command::new("git")
            .args(["init", "-q"])
            .arg(&root)
            .status()
            .unwrap();
        assert!(status.success());
        std::fs::write(
            parent.path().join("AGENTS.md"),
            "OUTSIDE-WORKSPACE-SENTINEL",
        )
        .unwrap();
        std::fs::write(root.join("AGENTS.md"), "INSIDE-WORKSPACE-SENTINEL").unwrap();

        let instructions = load_project_instructions(nested.to_str().unwrap());

        assert!(instructions.contains("INSIDE-WORKSPACE-SENTINEL"));
        assert!(!instructions.contains("OUTSIDE-WORKSPACE-SENTINEL"));
    }

    #[test]
    fn ca_rules_directory_is_discovered_from_workspace_root() {
        let parent = tempfile::tempdir().unwrap();
        let root = parent.path().join("workspace");
        let nested = root.join("src/nested");
        std::fs::create_dir_all(&nested).unwrap();
        let status = std::process::Command::new("git")
            .args(["init", "-q"])
            .arg(&root)
            .status()
            .unwrap();
        assert!(status.success());
        let rules_dir = root.join(".ca").join("rules");
        std::fs::create_dir_all(&rules_dir).unwrap();
        std::fs::write(rules_dir.join("style.md"), "Always use snake_case.").unwrap();
        std::fs::write(rules_dir.join("testing.md"), "Write tests first.").unwrap();
        // Non-.md files are ignored
        std::fs::write(rules_dir.join("notes.txt"), "Ignored.").unwrap();

        let instructions = load_project_instructions(nested.to_str().unwrap());

        assert!(instructions.contains("Rule: style"));
        assert!(instructions.contains("Always use snake_case."));
        assert!(instructions.contains("Rule: testing"));
        assert!(instructions.contains("Write tests first."));
        assert!(!instructions.contains("Ignored."));
    }

    #[test]
    fn project_instructions_rules_and_skills_cover_every_workspace_root() {
        let temp = tempfile::tempdir().unwrap();
        let primary = temp.path().join("primary");
        let additional = temp.path().join("additional");
        std::fs::create_dir_all(primary.join(".ca/rules")).unwrap();
        std::fs::create_dir_all(additional.join(".ca/rules")).unwrap();
        std::fs::create_dir_all(primary.join(".ca/skills/primary-skill")).unwrap();
        std::fs::create_dir_all(additional.join(".ca/skills/extra-skill")).unwrap();
        std::fs::write(primary.join("AGENTS.md"), "primary instructions").unwrap();
        std::fs::write(additional.join("AGENTS.md"), "additional instructions").unwrap();
        std::fs::write(primary.join(".ca/rules/primary.md"), "primary rule").unwrap();
        std::fs::write(additional.join(".ca/rules/extra.md"), "additional rule").unwrap();
        std::fs::write(
            primary.join(".ca/skills/primary-skill/SKILL.md"),
            "---\nname: primary-skill\ndescription: Primary\n---\nPrimary body",
        )
        .unwrap();
        std::fs::write(
            additional.join(".ca/skills/extra-skill/SKILL.md"),
            "---\nname: extra-skill\ndescription: Extra\n---\nExtra body",
        )
        .unwrap();
        let primary = std::fs::canonicalize(primary).unwrap();
        let additional = std::fs::canonicalize(additional).unwrap();
        let workspace =
            workspace::WorkspaceContext::from_roots(&primary, std::slice::from_ref(&additional))
                .unwrap();
        let instructions = load_project_instructions_for_workspace(&workspace);
        for expected in [
            "primary instructions",
            "additional instructions",
            "primary rule",
            "additional rule",
        ] {
            assert!(instructions.contains(expected), "missing {expected}");
        }
        let paths = runtime::RuntimePaths::from_home(temp.path().join("home"));
        let registry = discover_skill_registry(&paths, &workspace, &CaConfig::default());
        assert!(registry
            .instances()
            .any(|instance| instance.metadata.name == "primary-skill"));
        assert!(registry
            .instances()
            .any(|instance| instance.metadata.name == "extra-skill"));
    }

