    #[test]
    fn unavailable_tool_failure_guidance_names_the_mode_and_existing_ui() {
        let ask = unavailable_tool_failure_message(&AgentMode::Ask, "run_command");
        for guidance in [
            "Ask has no tools",
            "Empty input",
            "Tab twice",
            "Agent",
            "resend",
        ] {
            assert!(ask[..80].contains(guidance), "{ask}");
        }
        assert!(ask.contains("Unavailable tool: run_command"));
        assert!(!ask.contains("/retry"));
        assert!(!ask.contains("/agent"));

        let plan = unavailable_tool_failure_message(&AgentMode::Plan, "run_command");
        for guidance in [
            "Plan",
            "Empty input",
            "Tab until Agent",
            "resend",
            "Execute reviewed plan",
        ] {
            assert!(plan[..80].contains(guidance), "{plan}");
        }
        assert!(!plan.contains("/retry"));
        assert!(!plan.contains("/agent"));

        for mode in [
            AgentMode::Agent,
            AgentMode::Debug,
            AgentMode::Custom("limited".into()),
        ] {
            let message = unavailable_tool_failure_message(&mode, "run_command");
            assert_eq!(
                message,
                "Unavailable tool run_command in this request. /retry keeps its tool restrictions."
            );
            assert!(!message.contains("configuration"));
        }
        let safe = unavailable_tool_failure_message(
            &AgentMode::Agent,
            &format!("{}\n\x1b[31m", "x".repeat(1_000)),
        );
        assert!(!safe.chars().any(char::is_control));
        assert!(safe.len() < 220);
    }

