    #[test]
    fn failed_and_cancelled_turns_do_not_drain_queue() {
        for outcome in [
            activity::TurnOutcome::Failed,
            activity::TurnOutcome::Cancelled,
        ] {
            let mut state = AppState::new(crate::context::ShellHistory::in_memory());
            state.input_queue.enqueue("keep queued");
            state.turn_lifecycle.begin();
            match outcome {
                activity::TurnOutcome::Failed => state.turn_lifecycle.fail(),
                activity::TurnOutcome::Cancelled => state.turn_lifecycle.cancel(),
                _ => unreachable!(),
            }
            let (tx, _rx) = mpsc::unbounded_channel();
            let mut cancel_handle = None;
            let temporary = tempfile::TempDir::new().unwrap();
            let session_store = session::SessionStore::new(temporary.path());

            assert!(!drain_next_queued_input(
                &mut state,
                &CaConfig::default(),
                &session_store,
                &tx,
                &mut cancel_handle,
            ));
            assert_eq!(state.input_queue.len(), 1);
            assert!(cancel_handle.is_none());
        }
    }

