    #[test]
    fn provider_failure_retry_preserves_resolved_tools_and_drops_failed_partial_text() {
        let temp = tempfile::tempdir().unwrap();
        let store = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.session_name = "resolved tool retry".into();
        state.cwd = temp.path().display().to_string();
        state.current_model = Some(ModelInfo {
            id: "retry-model".into(),
            provider: "retry-provider".into(),
            display_name: "Retry Model".into(),
        });
        state.messages = vec![
            Message {
                role: Role::User,
                content: "inspect and update".into(),
                tool_calls: None,
                thinking: None,
                timestamp: chrono::Utc::now(),
                response_items: Vec::new(),
            },
            Message {
                role: Role::Assistant,
                content: String::new(),
                tool_calls: Some(vec![
                    ToolCall {
                        id: "delegated".into(),
                        name: "delegate_mechanistic".into(),
                        arguments: r#"{"actions":[{"kind":"git_status_summary"}]}"#.into(),
                        status: ToolStatus::Done,
                        output: Some(r#"{"status":"completed","receipt":{"digest":"abc"}}"#.into()),
                    },
                    ToolCall {
                        id: "mutated".into(),
                        name: "write_file".into(),
                        arguments: r#"{"path":"tracked.txt","content":"updated"}"#.into(),
                        status: ToolStatus::Done,
                        output: Some("Updated tracked.txt".into()),
                    },
                    ToolCall {
                        id: "denied".into(),
                        name: "run_command".into(),
                        arguments: r#"{"command":"false"}"#.into(),
                        status: ToolStatus::Error,
                        output: Some("Denied by policy".into()),
                    },
                ]),
                thinking: None,
                timestamp: chrono::Utc::now(),
                response_items: Vec::new(),
            },
        ];
        state.active_turn_start_message_count = Some(0);
        state.turn_lifecycle.begin();
        state.streaming = Some(StreamingState {
            provider_text: Default::default(),
            usage_handle: crate::usage::UsageHandle::test_handle(),
            content: "This partial conclusion must not be retried".into(),
            tool_calls: Vec::new(),
            thinking: None,
            last_usage: None,
            response_items: Vec::new(),
            reasoning_started_at: None,
            reasoning_duration: None,
            generation_started_at: None,
        });

        apply_stream_failure(
            &mut state,
            "test",
            &agent::stream::ProviderError::PrematureEof,
        );
        assert_eq!(
            state.retry_boundary,
            Some(RetryBoundary::continuation(0, 2))
        );
        assert_eq!(state.messages.len(), 3);

        prepare_retry_branch(&mut state, &store).unwrap();

        assert_eq!(state.messages.len(), 2);
        assert_eq!(state.messages[0].content, "inspect and update");
        assert_eq!(state.messages[1].tool_calls.as_ref().unwrap().len(), 3);
        assert!(state
            .messages
            .iter()
            .all(|message| !message.content.contains("partial conclusion")));
        assert!(state.turn_lifecycle.is_active());
        assert_eq!(state.active_turn_start_message_count, Some(0));
        assert!(state.retry_boundary.is_none());
        assert_eq!(
            state
                .current_model
                .as_ref()
                .map(|model| (model.provider.as_str(), model.id.as_str())),
            Some(("retry-provider", "retry-model"))
        );
        assert!(state
            .status_message
            .as_deref()
            .unwrap()
            .contains("provider continuation"));

        let parent = state
            .current_session
            .as_ref()
            .unwrap()
            .parent
            .as_ref()
            .unwrap();
        let source = store.load(&parent.session_id.to_string()).unwrap();
        assert_eq!(source.messages.len(), 3);
        assert!(source.messages[2].content.contains("partial conclusion"));
    }

