    #[test]
    fn transcript_completion_metadata_updates_only_the_final_annotation() {
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        let turn_id = uuid::Uuid::parse_str("51515151-5151-4151-8151-515151515151").unwrap();
        state.active_agent_turn_id = Some(turn_id);
        state.current_model = Some(ModelInfo {
            id: "mimo-v2.5-pro".into(),
            provider: "mimo".into(),
            display_name: "MiMo".into(),
        });
        let first = chrono::DateTime::from_timestamp(1, 0).unwrap();
        let final_message = chrono::DateTime::from_timestamp(2, 0).unwrap();
        record_transcript_annotation(&mut state, first, None);
        record_transcript_annotation(
            &mut state,
            final_message,
            Some(std::time::Duration::from_millis(651)),
        );
        assert!(record_turn_completion_annotation(
            &mut state,
            activity::TurnCompletion {
                outcome: activity::TurnOutcome::Cancelled,
                duration: std::time::Duration::from_millis(1_400),
                was_paused: false,
            },
        ));

        assert_eq!(state.transcript_annotations[0].total_turn_duration_ms, None);
        assert_eq!(state.transcript_annotations[0].terminal_outcome, None);
        let final_annotation = &state.transcript_annotations[1];
        assert_eq!(final_annotation.provider.as_deref(), Some("mimo"));
        assert_eq!(final_annotation.model.as_deref(), Some("mimo-v2.5-pro"));
        assert_eq!(final_annotation.reasoning_duration_ms, Some(651));
        assert_eq!(final_annotation.total_turn_duration_ms, Some(1_400));
        assert_eq!(
            final_annotation.terminal_outcome,
            Some(crate::app::TranscriptTurnOutcome::Cancelled)
        );
    }

