    #[tokio::test]
    async fn http_fallback_allows_429_but_not_auth_route_or_protocol_failures() {
        enum Expected {
            Fallback,
            PrimaryError,
        }
        let cases = [
            ("429 Too Many Requests", Vec::new(), 2, Expected::Fallback),
            ("401 Unauthorized", Vec::new(), 1, Expected::PrimaryError),
            ("403 Forbidden", Vec::new(), 1, Expected::PrimaryError),
            ("404 Not Found", Vec::new(), 1, Expected::PrimaryError),
            (
                "200 OK",
                b"data: {not-json}\n\n".to_vec(),
                1,
                Expected::PrimaryError,
            ),
        ];
        for (status, body, attempts, expected) in cases {
            let (primary_url, primary_server) = test_provider_sequence(
                (0..attempts)
                    .map(|_| (status, body.clone()))
                    .collect::<Vec<_>>(),
            )
            .await;
            let fallback_listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
            let fallback_url = format!("http://{}/v1", fallback_listener.local_addr().unwrap());
            let mut config = CaConfig::default();
            config.providers = std::collections::HashMap::from([
                (
                    "primary".into(),
                    config::ProviderConfig {
                        google: None,
                        tool_schema_policy: Default::default(),
                        base_url: primary_url,
                        api_key: String::new(),
                        protocol: agent::ProviderProtocol::default(),
                        prompt_cache_mode: crate::config::PromptCacheMode::Implicit,
                        models: vec!["one".into()],
                        timeout: config::ProviderTimeoutConfig::default(),
                    },
                ),
                (
                    "backup".into(),
                    config::ProviderConfig {
                        google: None,
                        tool_schema_policy: Default::default(),
                        base_url: fallback_url,
                        api_key: String::new(),
                        protocol: agent::ProviderProtocol::default(),
                        prompt_cache_mode: crate::config::PromptCacheMode::Implicit,
                        models: vec!["two".into()],
                        timeout: config::ProviderTimeoutConfig::default(),
                    },
                ),
            ]);
            config.defaults.provider = "primary".into();
            config.defaults.model = "one".into();
            config.fallbacks = vec![fallback::ProviderFallbackRule {
                provider: "primary".into(),
                model: "one".into(),
                fallback_provider: "backup".into(),
                fallback_model: "two".into(),
                causes: fallback::default_fallback_causes(),
            }];
            let mut state = AppState::new(context::ShellHistory::in_memory());
            state.cwd = ".".into();
            state.current_model = Some(ModelInfo {
                provider: "primary".into(),
                id: "one".into(),
                display_name: "one".into(),
            });
            state.messages.push(Message {
                role: Role::User,
                content: "status".into(),
                tool_calls: None,
                thinking: None,
                timestamp: chrono::Utc::now(),
                response_items: Vec::new(),
            });
            let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
            let mut handle = None;

            if matches!(expected, Expected::Fallback) {
                let server = tokio::spawn(async move {
                    let (mut stream, _) = fallback_listener.accept().await.unwrap();
                    let request = read_test_http_request(&mut stream).await;
                    let response = btw_complete_stream("OK");
                    let headers = format!(
                        "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                        response.len()
                    );
                    stream.write_all(headers.as_bytes()).await.unwrap();
                    stream.write_all(&response).await.unwrap();
                    request
                });
                start_llm_turn(&mut state, &config, &tx, &mut handle);
                handle.take().unwrap().await.unwrap();
                let events = std::iter::from_fn(|| rx.try_recv().ok()).collect::<Vec<_>>();
                assert!(events.iter().any(|event| matches!(
                    event,
                    StreamMsg::FallbackActivated {
                        cause: fallback::ProviderFallbackCause::RateLimited,
                        ..
                    }
                )));
                assert!(
                    String::from_utf8_lossy(&server.await.unwrap()).contains("\"model\":\"two\"")
                );
            } else {
                start_llm_turn(&mut state, &config, &tx, &mut handle);
                handle.take().unwrap().await.unwrap();
                let events = std::iter::from_fn(|| rx.try_recv().ok()).collect::<Vec<_>>();
                assert!(!events
                    .iter()
                    .any(|event| matches!(event, StreamMsg::FallbackActivated { .. })));
                assert!(events.iter().any(
                    |event| matches!(event, StreamMsg::Error { provider, .. } if provider == "primary")
                ));
                assert!(tokio::time::timeout(
                    std::time::Duration::from_millis(75),
                    fallback_listener.accept()
                )
                .await
                .is_err());
            }
            assert_eq!(primary_server.await.unwrap().len(), attempts);
        }
    }

