    #[test]
    fn checkpoint_ready_during_tool_turn_waits_for_prompt_epoch_finish() {
        let checkpoint = |summary: &str| context::ContextCheckpoint {
            format_version: 1,
            through_message_count: 1,
            summary: summary.into(),
            created_at: chrono::Utc::now(),
            source_tokens: 10,
            source_sha256: None,
            anchors: Vec::new(),
            user_quotes: Vec::new(),
            recall_pointer: None,
        };
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.context_checkpoint = Some(checkpoint("active checkpoint"));
        state.active_turn_prompt = Some(crate::app::ActiveTurnPromptState {
            stable_system: "frozen stable prompt".into(),
            ..Default::default()
        });
        state.turn_lifecycle.begin();
        state
            .turn_lifecycle
            .set_phase(activity::ActivityPhase::Tool);

        assert_eq!(
            accept_ready_context_checkpoint(&mut state, checkpoint("pending checkpoint")),
            CheckpointReadyDisposition::Pending
        );
        assert_eq!(
            state
                .context_checkpoint
                .as_ref()
                .map(|value| value.summary.as_str()),
            Some("active checkpoint")
        );
        assert_eq!(
            state
                .pending_context_checkpoint
                .as_ref()
                .map(|value| value.summary.as_str()),
            Some("pending checkpoint")
        );
        assert!(!activate_pending_checkpoint_between_turns(&mut state));
        assert_eq!(
            state
                .context_checkpoint
                .as_ref()
                .map(|value| value.summary.as_str()),
            Some("active checkpoint")
        );
        assert!(state.active_turn_prompt.is_some());

        state.turn_lifecycle.complete();
        state.outcome_tracker.record_assistant_turn();
        assert!(finish_active_prompt_epoch(&mut state));
        assert_eq!(
            state
                .context_checkpoint
                .as_ref()
                .map(|value| value.summary.as_str()),
            Some("pending checkpoint")
        );
        assert!(state.pending_context_checkpoint.is_none());
        assert!(state.active_turn_prompt.is_none());
    }

    fn failed_user_only_state(workspace: &std::path::Path) -> AppState {
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.cwd = workspace.display().to_string();
        state.session_name = "failed source".into();
        state.messages.push(Message {
            role: Role::User,
            content: "failed request".into(),
            tool_calls: None,
            thinking: None,
            timestamp: chrono::Utc::now(),
            response_items: Vec::new(),
        });
        state.retry_boundary = Some(RetryBoundary::replay(0));
        state.turn_lifecycle.begin();
        state.turn_lifecycle.fail();
        state.outcome_tracker.record_failure();
        state
    }

    fn finish_new_session_for_test(state: &mut AppState, store: &session::SessionStore) -> bool {
        let request = prepare_new_session(state).expect("idle session can start over");
        let generation = state.session_load_generation;
        let result = save_new_session_source(store, request);
        apply_new_session_result(state, result, generation)
    }

    #[test]
    fn new_session_preserves_source_and_starts_an_independent_empty_root() {
        let temp = tempfile::tempdir().unwrap();
        let sessions = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = failed_user_only_state(temp.path());
        state.workspace = workspace::WorkspaceContext::discover(temp.path()).unwrap();
        state.current_model = Some(ModelInfo {
            id: "fixture".into(),
            provider: "local".into(),
            display_name: "Fixture".into(),
        });
        state.reasoning_effort = Some(config::ReasoningEffort::High);
        state.input_queue.enqueue("old queued draft");
        state.input = "composer draft".into();
        state
            .session_sitting
            .record_tool(1, "old", "read_file", ToolStatus::Done);
        state.token_count = (123, 456);
        state.context_checkpoint = Some(context::ContextCheckpoint {
            format_version: 1,
            through_message_count: 1,
            summary: "old summary".into(),
            created_at: chrono::Utc::now(),
            source_tokens: 1,
            source_sha256: None,
            anchors: Vec::new(),
            user_quotes: Vec::new(),
            recall_pointer: None,
        });
        ensure_session_identity(&mut state);
        let old_id = state.current_session.as_ref().unwrap().id;
        let model = state.current_model.clone();
        let root = state.workspace.primary().unwrap().path.clone();

        assert!(finish_new_session_for_test(&mut state, &sessions));

        let fresh = state.current_session.as_ref().unwrap();
        assert_ne!(fresh.id, old_id);
        assert!(fresh.parent.is_none());
        assert!(fresh.messages.is_empty());
        assert!(state.messages.is_empty());
        assert!(state.session_name.is_empty());
        assert!(state.input.is_empty());
        assert!(state.input_queue.is_empty());
        assert!(state.retry_boundary.is_none());
        assert!(state.context_checkpoint.is_none());
        assert_eq!(state.token_count, (0, 0));
        assert_eq!(state.session_sitting.tool_total(), 0);
        assert_eq!(state.current_model, model);
        assert_eq!(state.reasoning_effort, Some(config::ReasoningEffort::High));
        assert_eq!(state.workspace.primary().unwrap().path, root);
        assert_eq!(state.job_owner.session_id, Some(fresh.id));
        assert!(state.request_store.snapshot().is_none());
        let old = sessions.load(&old_id.to_string()).unwrap();
        assert_eq!(old.messages[0].content, "failed request");
        assert_eq!(old.queued_inputs[0].text, "old queued draft");
        assert_eq!(old.title, "failed source");
        assert_eq!(sessions.list().unwrap().len(), 1);

        state.messages.push(Message {
            content: "first new prompt".into(),
            ..old.messages[0].clone()
        });
        save_current_session(&mut state, &sessions).unwrap();
        assert!(state.session_title_pending);
        assert_eq!(sessions.list().unwrap().len(), 2);
        assert_eq!(
            sessions.load(&old_id.to_string()).unwrap().messages[0].content,
            "failed request"
        );
    }

