    #[test]
    fn new_session_preserves_all_paged_history_and_rejects_changed_generation() {
        for changed in [false, true] {
            let temp = tempfile::tempdir().unwrap();
            let sessions = session::SessionStore::new(temp.path().join("sessions"));
            let mut state = failed_user_only_state(temp.path());
            let message = state.messages[0].clone();
            state.messages = (0..(session::SESSION_HISTORY_PAGE_SIZE * 2 + 3))
                .map(|index| Message {
                    content: format!("message {index}"),
                    ..message.clone()
                })
                .collect();
            let id = save_current_session(&mut state, &sessions).unwrap();
            let complete = sessions.load(&id.to_string()).unwrap();
            apply_recent_session(
                &mut state,
                sessions.load_recent(&id.to_string(), 2).unwrap(),
            );
            assert!(state
                .session_history
                .as_ref()
                .is_some_and(|history| !history.is_complete()));
            state.input_queue.enqueue("preserve after resume");
            if changed {
                let mut replacement = complete.clone();
                replacement.messages[0].content = "changed externally".into();
                sessions.save(&mut replacement).unwrap();
            }
            assert_eq!(finish_new_session_for_test(&mut state, &sessions), !changed);
            let saved = sessions.load(&id.to_string()).unwrap();
            assert_eq!(saved.messages.len(), complete.messages.len());
            assert_eq!(
                saved.messages[0].content,
                if changed {
                    "changed externally"
                } else {
                    "message 0"
                }
            );
            if changed {
                assert_eq!(state.current_session.as_ref().unwrap().id, id);
                assert_eq!(state.messages.len(), 2);
            } else {
                assert_ne!(state.current_session.as_ref().unwrap().id, id);
                assert_eq!(saved.queued_inputs[0].text, "preserve after resume");
            }
        }
    }

    #[test]
    fn new_session_refuses_active_work_and_ignores_stale_completion() {
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.turn_lifecycle.begin();
        assert!(prepare_new_session(&mut state).is_none());
        state.turn_lifecycle.fail();
        state.outcome_tracker.record_failure();
        let _request = prepare_new_session(&mut state).unwrap();
        let generation = state.session_load_generation;
        assert!(!apply_new_session_result(
            &mut state,
            Ok(()),
            generation.wrapping_sub(1)
        ));
        assert!(state.new_session_starting);
        assert!(apply_new_session_result(&mut state, Ok(()), generation));
        let id = state.current_session.as_ref().unwrap().id;
        assert!(!apply_new_session_result(&mut state, Ok(()), generation));
        assert_eq!(state.current_session.as_ref().unwrap().id, id);
    }

    #[tokio::test]
    async fn pane_close_save_failure_keeps_owner_and_stale_completion_cannot_close_it() {
        let temp = tempfile::tempdir().unwrap();
        let blocked = temp.path().join("blocked-sessions");
        std::fs::write(&blocked, "not a directory").unwrap();
        let failed_store = session::SessionStore::new(&blocked);
        let mut state = failed_user_only_state(temp.path());
        state.current_session = Some(current_session_snapshot(&state));
        let source_id = state.current_session.as_ref().unwrap().id;
        let messages = state.messages.clone();
        let mut deck = state.pane_deck.take().unwrap();
        let second = state.new_pane_from();
        deck.split(
            &state,
            panes::SplitAxis::Vertical,
            second,
            ratatui::layout::Rect::new(0, 0, 280, 45),
        )
        .unwrap();
        state.pane_deck = Some(deck);
        let (tx, mut rx) = mpsc::unbounded_channel();
        start_pane_close_save(&mut state, &failed_store, &tx);
        assert!(state.pane_close_busy);
        let old_generation = state.pane_close_generation;
        let StreamMsg::PaneCloseSaved(result) = rx.recv().await.unwrap() else {
            panic!("expected pane save")
        };
        assert!(result.result.is_err());
        apply_pane_close_save(&mut state, *result);
        assert_eq!(state.pane_deck.as_ref().unwrap().len(), 2);
        assert_eq!(state.current_session.as_ref().unwrap().id, source_id);
        assert_eq!(state.messages, messages);
        assert!(state.pane_request.is_none());
        assert!(!state.pane_close_committed);
        assert!(state
            .status_message
            .as_deref()
            .unwrap()
            .contains("pane kept open"));

        let store = session::SessionStore::new(temp.path().join("sessions"));
        start_pane_close_save(&mut state, &store, &tx);
        let pane_id = state.pane_id;
        apply_pane_close_save(
            &mut state,
            PaneCloseSaveResult {
                pane_id,
                session_id: Some(source_id),
                generation: old_generation,
                result: Err("stale failure".into()),
            },
        );
        assert!(state.pane_close_busy);
        let StreamMsg::PaneCloseSaved(result) = rx.recv().await.unwrap() else {
            panic!("expected pane save")
        };
        apply_pane_close_save(&mut state, *result);
        assert!(state.pane_close_committed);
        assert!(matches!(
            state.pane_request,
            Some(panes::PaneRequest::Close)
        ));
        assert_eq!(
            store.load(&source_id.to_string()).unwrap().messages,
            messages
        );
        panes::close_focused(&mut state).unwrap();
        assert_eq!(state.pane_deck.as_ref().unwrap().len(), 1);
    }

