    #[test]
    fn repeated_failed_user_replacements_never_accumulate_user_messages() {
        let temp = tempfile::tempdir().unwrap();
        let store = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = failed_user_only_state(temp.path());
        let mut earlier_user = state.messages[0].clone();
        earlier_user.content = "earlier request".into();
        let mut earlier_answer = earlier_user.clone();
        earlier_answer.role = Role::Assistant;
        earlier_answer.content = "completed answer".into();
        state.messages.splice(0..0, [earlier_user, earlier_answer]);
        state.retry_boundary = Some(RetryBoundary::replay(2));
        for replacement in ["replacement one", "replacement two", "replacement three"] {
            assert!(apply_before_submit_hook_result(
                &mut state,
                &store,
                hooks::HookBatchResult::default(),
                replacement.into(),
                replacement.into(),
            ));
            assert_eq!(state.messages.len(), 3);
            assert_eq!(state.messages[0].content, "earlier request");
            assert_eq!(state.messages[1].content, "completed answer");
            assert_eq!(state.messages[2].content, replacement);
            assert!(state.current_session.as_ref().unwrap().parent.is_some());
            state.retry_boundary = Some(RetryBoundary::replay(2));
            state.turn_lifecycle.begin();
            state.turn_lifecycle.fail();
            state.outcome_tracker.record_failure();
        }
    }

