    #[test]
    fn rule_manager_previews_confirms_persists_and_rejects_editor_drift() {
        let temp = tempfile::tempdir().unwrap();
        let home = temp.path().join("home");
        let project = temp.path().join("project");
        std::fs::create_dir_all(&home).unwrap();
        std::fs::create_dir_all(&project).unwrap();
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.run_capabilities =
            runtime::RunCapabilities::for_profile(&runtime::ActiveProfile::Default);
        state.rules_home = Some(std::fs::canonicalize(&home).unwrap());
        state.workspace = workspace::WorkspaceContext::discover(&project).unwrap();
        state.cwd = state.workspace.cwd().to_string_lossy().into_owned();
        refresh_rules(&mut state);
        let sessions = session::SessionStore::new(temp.path().join("sessions"));

        manage_rule_command(
            &mut state,
            "create project rust manual Rust conventions :: Use rustfmt.",
            &sessions,
        );
        let create_digest = state
            .asset_mutation_preview
            .as_ref()
            .unwrap()
            .confirmation_digest
            .clone();
        assert!(state.pager_content.contains("rule create preview"));
        manage_rule_command(&mut state, &format!("confirm {create_digest}"), &sessions);
        let id = "workspace-0/rust";
        assert!(state.rules.find(id).is_some());

        manage_rule_command(&mut state, &format!("activate {id}"), &sessions);
        assert!(state.manual_rule_ids.contains(id));
        let saved = sessions
            .load(&state.current_session.as_ref().unwrap().id.to_string())
            .unwrap();
        assert_eq!(saved.manual_rule_ids, [id]);

        manage_rule_command(
            &mut state,
            &format!("edit {id} manual Revised conventions :: Use cargo fmt."),
            &sessions,
        );
        let edit = state.asset_mutation_preview.clone().unwrap();
        std::fs::write(&edit.target, "external drift").unwrap();
        manage_rule_command(
            &mut state,
            &format!("confirm {}", edit.confirmation_digest),
            &sessions,
        );
        assert!(state
            .status_message
            .as_deref()
            .unwrap()
            .contains("changed after preview"));
        assert_eq!(
            std::fs::read_to_string(&edit.target).unwrap(),
            "external drift"
        );

        manage_rule_command(&mut state, "reload", &sessions);
        manage_rule_command(&mut state, &format!("delete {id}"), &sessions);
        let delete_digest = state
            .asset_mutation_preview
            .as_ref()
            .unwrap()
            .confirmation_digest
            .clone();
        manage_rule_command(&mut state, &format!("confirm {delete_digest}"), &sessions);
        assert!(!edit.target.exists());
        assert!(!state.manual_rule_ids.contains(id));
    }

    #[test]
    fn command_manager_keeps_builtins_and_foreign_commands_read_only() {
        let temp = tempfile::tempdir().unwrap();
        let home = temp.path().join("home");
        let project = temp.path().join("project");
        std::fs::create_dir_all(home.join(".claude/commands")).unwrap();
        std::fs::create_dir_all(&project).unwrap();
        std::fs::write(
            home.join(".claude/commands/foreign.md"),
            "---\ndescription: Foreign command\n---\n\nRead only body\n",
        )
        .unwrap();
        let paths = runtime::RuntimePaths::from_home(home.clone());
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.run_capabilities =
            runtime::RunCapabilities::for_profile(&runtime::ActiveProfile::Default);
        state.active_profile = runtime::ActiveProfile::Default;
        state.rules_home = Some(std::fs::canonicalize(&home).unwrap());
        state.workspace = workspace::WorkspaceContext::discover(&project).unwrap();
        state.cwd = state.workspace.cwd().to_string_lossy().into_owned();
        state.prompt_commands = prompt_commands::PromptCommandRegistry::discover_for_workspace(
            &paths,
            &state.active_profile,
            &state.workspace,
        );

        manage_prompt_command(
            &mut state,
            "create project inspect-local Review changes :: Inspect the current diff.",
        );
        let create_digest = state
            .asset_mutation_preview
            .as_ref()
            .unwrap()
            .confirmation_digest
            .clone();
        manage_prompt_command(&mut state, &format!("confirm {create_digest}"));
        assert!(state.prompt_commands.find("inspect-local").is_some());

        manage_prompt_command(
            &mut state,
            "create project help Replace builtin :: This must fail.",
        );
        assert!(state
            .status_message
            .as_deref()
            .unwrap()
            .contains("built-in"));

        state.prompt_commands = prompt_commands::PromptCommandRegistry::discover_for_workspace(
            &paths,
            &state.active_profile,
            &state.workspace,
        );
        manage_prompt_command(&mut state, "delete foreign");
        assert!(state
            .status_message
            .as_deref()
            .unwrap()
            .contains("read-only"));

        manage_prompt_command(&mut state, "edit inspect-local Revised :: New body");
        let edit = state.asset_mutation_preview.clone().unwrap();
        std::fs::write(&edit.target, "external drift").unwrap();
        manage_prompt_command(&mut state, &format!("confirm {}", edit.confirmation_digest));
        assert!(state
            .status_message
            .as_deref()
            .unwrap()
            .contains("changed after preview"));
        assert_eq!(
            std::fs::read_to_string(edit.target).unwrap(),
            "external drift"
        );
    }

    #[test]
    fn conditional_rules_enter_system_prompt_only_for_host_selected_paths() {
        let temp = tempfile::tempdir().unwrap();
        let project = temp.path().join("project");
        std::fs::create_dir_all(project.join(".ca/rules")).unwrap();
        std::fs::create_dir_all(project.join("src")).unwrap();
        std::fs::write(project.join("src/lib.rs"), "pub fn example() {}\n").unwrap();
        std::fs::write(
            project.join(".ca/rules/rust.md"),
            "---\ndescription: Rust rule\nactivation: glob\nglobs: [\"src/*.rs\"]\n---\nOnly for explicit Rust files.",
        )
        .unwrap();
        let workspace = workspace::WorkspaceContext::discover(&project).unwrap();
        let registry = rules::RuleRegistry::discover_workspace_only(&workspace);
        let manual = std::collections::BTreeSet::new();
        let prose_only = registry.render_active(&manual, &[], &workspace);
        assert!(
            prose_only.is_empty(),
            "ordinary prose path names must not activate globs"
        );
        let explicit = attachments::explicit_file_paths("@src/lib.rs", &workspace, &[]).unwrap();
        let active = registry.render_active(&manual, &explicit, &workspace);
        let prompt = build_system_prompt_parts_with_memory_workspace_and_rules(
            workspace.cwd().to_str().unwrap(),
            Some(&workspace),
            false,
            None,
            "",
            Some(&active),
        )
        .render();
        assert!(prompt.contains("Only for explicit Rust files."));
    }

