    #[test]
    fn proposal_confirmation_applies_on_yes_and_leaves_the_proposal_pending_on_no() {
        let proposal_view = || codex_learning::TuiLearningView {
            kind: codex_learning::TuiLearningViewKind::Proposal,
            content: "proposal ready\n\ny applies these changes. n leaves them pending.".into(),
            evidence: None,
            proposal: Some(codex_learning::TuiProposalBinding {
                digest: "c".repeat(64),
                memory_items: 2,
                skill_items: 0,
            }),
        };
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.learning_review_view = Some(proposal_view());
        state.pager_open = true;
        state.learning_review_pager_open = true;

        open_learning_review_actions(&mut state);
        assert!(state.learning_review_request.is_none());
        assert!(!state.learning_review_busy);
        assert!(state.learning_review_interaction);
        let interaction = state.interaction.as_ref().expect("proposal confirmation");
        assert_eq!(
            interaction.request.question,
            "Apply this learning proposal?"
        );
        assert!(interaction
            .request
            .description
            .as_deref()
            .unwrap()
            .contains("y applies them. n leaves them pending."));

        let resolution = state
            .interaction
            .as_mut()
            .unwrap()
            .handle_key(
                crossterm::event::KeyCode::Char('y'),
                crossterm::event::KeyModifiers::NONE,
            )
            .expect("y answers yes");
        state.interaction = None;
        assert!(resolve_learning_review_decision(&mut state, &resolution));
        assert_eq!(
            state.learning_review_request,
            Some(codex_learning::TuiLearningRequest::ApplyProposal {
                digest: "c".repeat(64),
                scope: codex_learning::TuiLearningApplyScope::All,
            })
        );
        assert!(state.learning_review_busy);

        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.learning_review_view = Some(proposal_view());
        open_learning_proposal_confirmation(&mut state);
        let resolution = state
            .interaction
            .as_mut()
            .unwrap()
            .handle_key(
                crossterm::event::KeyCode::Char('n'),
                crossterm::event::KeyModifiers::NONE,
            )
            .expect("n answers no");
        state.interaction = None;
        assert!(resolve_learning_review_decision(&mut state, &resolution));
        assert!(state.learning_review_request.is_none());
        assert!(!state.learning_review_busy);
        assert_eq!(
            state.status_message.as_deref(),
            Some("Learning review left pending")
        );
        assert!(state.pager_open);

        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.learning_review_view = Some(proposal_view());
        open_learning_proposal_confirmation(&mut state);
        let resolution = state
            .interaction
            .as_mut()
            .unwrap()
            .handle_key(
                crossterm::event::KeyCode::Esc,
                crossterm::event::KeyModifiers::NONE,
            )
            .expect("esc cancels");
        state.interaction = None;
        assert!(resolve_learning_review_decision(&mut state, &resolution));
        assert!(state.learning_review_request.is_none());
        assert_eq!(
            state.status_message.as_deref(),
            Some("Learning review left pending")
        );
    }

    #[test]
    fn learn_and_distill_commands_route_directly_with_legacy_aliases_and_controls() {
        let temp = tempfile::tempdir().unwrap();
        let config_path = temp.path().join("config.toml");
        std::fs::write(&config_path, "# direct learning command test\n").unwrap();
        let config_store = ConfigStore::new(&config_path);
        let config = config_store.load().unwrap();
        let sessions = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.run_capabilities =
            runtime::RunCapabilities::for_profile(&runtime::ActiveProfile::Default);

        let cases = [
            (
                tui::commands::CommandId::Learn,
                "BSD transfer checks",
                codex_learning::TuiLearningRequest::Direct {
                    focus: "BSD transfer checks".into(),
                    allow_memory: true,
                    migration_notice: false,
                },
            ),
            (
                tui::commands::CommandId::Learn,
                "review",
                codex_learning::TuiLearningRequest::Direct {
                    focus: String::new(),
                    allow_memory: true,
                    migration_notice: true,
                },
            ),
            (
                tui::commands::CommandId::Learn,
                "approve",
                codex_learning::TuiLearningRequest::Direct {
                    focus: String::new(),
                    allow_memory: true,
                    migration_notice: true,
                },
            ),
            (
                tui::commands::CommandId::Distill,
                "",
                codex_learning::TuiLearningRequest::Direct {
                    focus: String::new(),
                    allow_memory: false,
                    migration_notice: false,
                },
            ),
            (
                tui::commands::CommandId::Distill,
                "run seedbox checks",
                codex_learning::TuiLearningRequest::Direct {
                    focus: "seedbox checks".into(),
                    allow_memory: false,
                    migration_notice: false,
                },
            ),
        ];
        for (id, args, expected) in cases {
            state.learning_review_busy = false;
            execute_command_action(
                &mut state,
                tui::commands::CommandAction {
                    id,
                    args: args.into(),
                },
                &sessions,
                &config,
                &config_store,
            );
            assert_eq!(state.learning_review_request.take(), Some(expected));
            assert!(!state.pager_open);
            assert!(!state.learning_review_pager_open);
        }

        state.learning_review_busy = false;
        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::Learn,
                args: "status".into(),
            },
            &sessions,
            &config,
            &config_store,
        );
        assert_eq!(
            state.learning_review_request.take(),
            Some(codex_learning::TuiLearningRequest::Status { run_id: None })
        );

        state.learning_review_busy = false;
        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::Distill,
                args: "off".into(),
            },
            &sessions,
            &config,
            &config_store,
        );
        assert_eq!(
            state.maintenance_request,
            Some(learning::MaintenanceRequest {
                kind: learning::MaintenanceKind::Distill,
                action: learning::MaintenanceCommandAction::SetEnabled(false),
            })
        );
    }

