    #[test]
    fn learning_review_completion_rejects_stale_results_and_respects_closed_pager() {
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.learning_review_generation = 7;
        state.learning_review_busy = true;
        state.pager_content = "unrelated page".into();
        state.pager_open = false;
        state.learning_review_pager_open = false;
        let result = || {
            Ok(codex_learning::TuiLearningTaskResult {
                view: codex_learning::TuiLearningView {
                    kind: codex_learning::TuiLearningViewKind::Proposal,
                    content: "proposal ready".into(),
                    evidence: None,
                    proposal: Some(codex_learning::TuiProposalBinding {
                        digest: "c".repeat(64),
                        memory_items: 1,
                        skill_items: 0,
                    }),
                },
                notice: "Proposal ready".into(),
                refreshed_after_drift: false,
            })
        };

        assert!(!apply_learning_review_task_result(&mut state, result(), 6));
        assert!(state.learning_review_busy);
        assert!(state.learning_review_view.is_none());
        assert!(apply_learning_review_task_result(&mut state, result(), 7));
        assert!(!state.learning_review_busy);
        assert!(state.pager_open);
        assert!(state.learning_review_pager_open);
        assert!(state.learning_review_interaction);
        assert!(state.learning_review_request.is_none());
        assert_eq!(
            state
                .interaction
                .as_ref()
                .map(|interaction| interaction.request.question.as_str()),
            Some("Apply this learning proposal?")
        );
        assert_eq!(state.pager_content, "proposal ready");
        assert_eq!(
            state.learning_review_view.as_ref().map(|view| view.kind),
            Some(codex_learning::TuiLearningViewKind::Proposal)
        );

        let mut evidence = AppState::new(crate::context::ShellHistory::in_memory());
        evidence.learning_review_generation = 7;
        evidence.learning_review_busy = true;
        assert!(apply_learning_review_task_result(
            &mut evidence,
            Ok(codex_learning::TuiLearningTaskResult {
                view: codex_learning::TuiLearningView {
                    kind: codex_learning::TuiLearningViewKind::Evidence,
                    content: "evidence ready".into(),
                    evidence: None,
                    proposal: None,
                },
                notice: "Evidence ready".into(),
                refreshed_after_drift: false,
            }),
            7,
        ));
        assert!(evidence.interaction.is_none());
        assert!(!evidence.learning_review_interaction);
        assert!(!evidence.learning_review_pager_open);
    }

    #[test]
    fn direct_learning_receipt_replaces_inline_progress_without_opening_a_pager() {
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.learning_review_generation = 4;
        state.learning_review_busy = true;
        assert!(apply_learning_review_progress(
            &mut state,
            codex_learning::TuiLearningProgress {
                completed_calls: 1,
                total_calls: 8,
                operation: "Searching repeated BSD checks".into(),
                model: Some("mimo/mimo-v2.5-pro".into()),
                activities: vec!["Search · “BSD rsync” · 6 matching sessions (collapsed)".into(),],
            },
            4,
        ));
        assert_eq!(state.messages.len(), 1);
        assert!(state.messages[0]
            .content
            .contains("Model: `mimo/mimo-v2.5-pro` · up to 8 turns"));
        assert!(state.messages[0].content.contains("## Investigation"));
        assert!(state.messages[0]
            .content
            .contains("Search · “BSD rsync” · 6 matching sessions (collapsed)"));
        let result = Ok(codex_learning::TuiLearningTaskResult {
            view: codex_learning::TuiLearningView {
                kind: codex_learning::TuiLearningViewKind::Receipt,
                content: "Inventory\n\nShortlist\n\nCreated or extended\n- /check-bsd\n\nSkipped\n- one-offs\n\nNeeds more evidence\n- dedup\n\nRun: abc · 2 adaptive turns".into(),
                evidence: None,
                proposal: None,
            },
            notice: "Learning completed and published".into(),
            refreshed_after_drift: false,
        });
        assert!(apply_learning_review_task_result(&mut state, result, 4));
        assert!(!state.pager_open);
        assert!(!state.learning_review_pager_open);
        assert_eq!(state.messages.len(), 1);
        assert!(state.messages[0].content.contains("Created or extended"));
        assert!(!state.messages[0].content.contains("Source revisions"));
    }

    #[test]
    fn learning_progress_is_generation_tagged_and_survives_closed_pager() {
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.learning_review_generation = 9;
        state.learning_review_busy = true;
        state.learning_review_pager_open = false;
        state.pager_open = false;
        let progress = codex_learning::TuiLearningProgress {
            completed_calls: 2,
            total_calls: 7,
            operation: "Distill 1/4".into(),
            model: Some("test/model".into()),
            activities: vec!["Inspect · 2 selected sessions (collapsed)".into()],
        };

        assert!(!apply_learning_review_progress(
            &mut state,
            progress.clone(),
            8
        ));
        assert!(state.learning_review_progress.is_none());
        assert!(apply_learning_review_progress(
            &mut state,
            progress.clone(),
            9
        ));
        assert!(!state.pager_open, "progress must not reopen a closed pager");
        assert_eq!(state.learning_review_progress, Some(progress.clone()));
        assert!(state.status_message.as_deref().unwrap().contains("2/7"));

        state.learning_review_pager_open = true;
        assert!(apply_learning_review_progress(&mut state, progress, 9));
        assert!(!state.pager_open);
        assert_eq!(state.messages.len(), 1);
        assert!(state.messages[0].content.contains("Distill 1/4"));
        state.learning_review_busy = false;
        assert!(!apply_learning_review_progress(
            &mut state,
            codex_learning::TuiLearningProgress {
                completed_calls: 3,
                total_calls: 7,
                operation: "stale".into(),
                model: None,
                activities: Vec::new(),
            },
            9,
        ));
    }

