    #[test]
    fn copy_picker_preserves_exact_visible_parts_without_exposing_opaque_provider_state() {
        let source = crate::agent::stream::ProviderStateSourceV1::for_test(
            "fixture",
            crate::agent::provider::ProviderProtocol::OpenAiResponses,
        );
        let message = Message {
            role: Role::Assistant,
            content: "answer\nwith spacing".into(),
            tool_calls: Some(vec![ToolCall {
                id: "call-1".into(),
                name: "run_command".into(),
                arguments: "{\"cmd\":\"true\"}".into(),
                status: ToolStatus::Done,
                output: Some("done\nexactly".into()),
            }]),
            thinking: Some("visible thought".into()),
            timestamp: chrono::Utc::now(),
            response_items: vec![
                crate::agent::stream::ProviderResponseItem::ResponsesOutput {
                    source,
                    output_index: 0,
                    item: serde_json::json!({
                        "type": "message",
                        "encrypted_content": "must-not-copy",
                        "content": [
                            {"type": "output_text", "text": "provider-visible"},
                            {"type": "reasoning", "text": "must-not-copy-either"}
                        ]
                    }),
                },
            ],
        };
        let picker = copy_picker_message(&message).unwrap();
        let values = picker
            .parts
            .iter()
            .map(|part| part.value.as_str())
            .collect::<Vec<_>>();
        assert!(values.contains(&"answer\nwith spacing"));
        assert!(values.contains(&"{\"cmd\":\"true\"}"));
        assert!(values.contains(&"done\nexactly"));
        assert!(values.contains(&"visible thought"));
        assert!(values.contains(&"provider-visible"));
        assert!(!values.iter().any(|value| value.contains("must-not-copy")));
    }

    #[test]
    fn copy_all_uses_privacy_safe_visible_projection_and_reports_failures() {
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.show_thinking = false;
        state.messages = vec![
            Message {
                role: Role::System,
                content: "SYSTEM PROMPT MUST STAY PRIVATE".into(),
                tool_calls: None,
                thinking: None,
                timestamp: chrono::Utc::now(),
                response_items: Vec::new(),
            },
            Message {
                role: Role::User,
                content: "Visible request 🙂".into(),
                tool_calls: None,
                thinking: None,
                timestamp: chrono::Utc::now(),
                response_items: Vec::new(),
            },
            Message {
                role: Role::Assistant,
                content: "Visible **Markdown** answer".into(),
                tool_calls: Some(vec![ToolCall {
                    id: "diff-call".into(),
                    name: "apply_patch".into(),
                    arguments: r#"{"patch":"*** Begin Patch\n+safe\n*** End Patch"}"#.into(),
                    status: ToolStatus::Done,
                    output: Some("@@ file @@\n-old\n+new".into()),
                }]),
                thinking: Some("HIDDEN REASONING MUST STAY PRIVATE".into()),
                timestamp: chrono::Utc::now(),
                response_items: Vec::new(),
            },
        ];
        state.streaming = Some(StreamingState {
            provider_text: Default::default(),
            content: "Active streaming tail 界".into(),
            tool_calls: Vec::new(),
            thinking: Some("HIDDEN STREAM REASONING".into()),
            response_items: Vec::new(),
            last_usage: None,
            usage_handle: crate::usage::UsageHandle::test_handle(),
            reasoning_started_at: None,
            reasoning_duration: None,
            generation_started_at: None,
        });
        let copied = std::cell::RefCell::new(String::new());
        assert!(copy_all_transcript_with(&mut state, |text| {
            *copied.borrow_mut() = text.to_string();
            Ok(())
        }));
        let copied = copied.borrow();
        assert!(copied.contains("Visible request 🙂"));
        assert!(copied.contains("Visible Markdown answer"));
        assert!(copied.contains("@@ file @@"));
        assert!(copied.contains("Active streaming tail 界"));
        assert!(!copied.contains("SYSTEM PROMPT"));
        assert!(!copied.contains("HIDDEN REASONING"));
        assert!(!copied.contains("HIDDEN STREAM"));
        assert!(!copied.contains('▌'));
        drop(copied);

        assert!(!copy_all_transcript_with(&mut state, |_| Err(())));
        assert_eq!(
            state.status_message.as_deref(),
            Some("Clipboard unavailable; nothing was copied")
        );
    }

