    #[test]
    fn skills_command_activates_views_searches_and_deactivates_exact_ids() {
        let temp = tempfile::tempdir().unwrap();
        let skill_dir = temp.path().join("deploy");
        std::fs::create_dir_all(&skill_dir).unwrap();
        std::fs::write(
            skill_dir.join("SKILL.md"),
            "---\nname: deploy\ndescription: Deploy carefully\naliases: [ship]\n---\nDEPLOY-BODY",
        )
        .unwrap();
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.skills = std::sync::Arc::new(std::sync::Mutex::new(skills::SkillRegistry::discover(
            skills::SkillRoots {
                project: Some(temp.path().to_path_buf()),
                project_boundary: Some(temp.path().to_path_buf()),
                user: None,
                compatibility: Vec::new(),
            },
            &[],
        )));

        manage_skills_command(&mut state, "ship");
        assert!(state.pager_content.contains("deploy"));
        manage_skills_command(&mut state, "activate deploy");
        assert!(state.skills.lock().unwrap().is_active("deploy"));
        manage_skills_command(&mut state, "view deploy");
        assert!(state.pager_content.contains("DEPLOY-BODY"));
        manage_skills_command(&mut state, "deactivate deploy");
        assert!(!state.skills.lock().unwrap().is_active("deploy"));
    }

    #[test]
    fn skills_command_ranks_explained_suggestions_without_activating_them() {
        let temp = tempfile::tempdir().unwrap();
        for (directory, name, description) in [
            (
                "release",
                "release-manager",
                "Coordinate safe production deployment and rollback",
            ),
            (
                "review",
                "rust-review",
                "Review Rust code for correctness and maintainability",
            ),
        ] {
            let skill_dir = temp.path().join(directory);
            std::fs::create_dir_all(&skill_dir).unwrap();
            std::fs::write(
                skill_dir.join("SKILL.md"),
                format!(
                    "---\nname: {name}\ndescription: {description}\naliases: [{name}-alias]\n---\nPRIVATE-{name}-BODY"
                ),
            )
            .unwrap();
        }
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.skills = std::sync::Arc::new(std::sync::Mutex::new(skills::SkillRegistry::discover(
            skills::SkillRoots {
                project: Some(temp.path().to_path_buf()),
                project_boundary: Some(temp.path().to_path_buf()),
                user: None,
                compatibility: Vec::new(),
            },
            &[],
        )));

        manage_skills_command(
            &mut state,
            "release-manager-alias rust correctness maintainability",
        );
        assert!(state.pager_content.starts_with("Skill suggestions for"));
        assert!(state
            .pager_content
            .contains("Suggestions do not activate skills · activate an exact canonical ID"));
        let release = state.pager_content.find("1. release-manager").unwrap();
        let review = state.pager_content.find("2. rust-review").unwrap();
        assert!(release < review);
        assert!(state
            .pager_content
            .contains("exact alias: release-manager-alias"));
        assert!(state.pager_content.contains("related"));
        assert!(!state.pager_content.contains("PRIVATE-"));
        assert!(state.skills.lock().unwrap().active_refs().is_empty());

        manage_skills_command(&mut state, "activate release-manager-alias");
        assert!(state
            .status_message
            .as_deref()
            .is_some_and(|message| message.contains("unknown skill ID")));
        assert!(state.skills.lock().unwrap().active_refs().is_empty());

        manage_skills_command(&mut state, "no-unrelated-metadata-token");
        assert!(state
            .pager_content
            .contains("No relevant skill suggestions"));
    }

    #[test]
    fn saving_session_persists_only_hash_bound_active_skill_references() {
        let temp = tempfile::tempdir().unwrap();
        let skill_dir = temp.path().join("skills/deploy");
        std::fs::create_dir_all(&skill_dir).unwrap();
        std::fs::write(
            skill_dir.join("SKILL.md"),
            "---\nname: deploy\ndescription: Deploy\n---\nSECRET-BODY-NOT-SERIALIZED",
        )
        .unwrap();
        let mut registry = skills::SkillRegistry::discover(
            skills::SkillRoots {
                project: Some(temp.path().join("skills")),
                project_boundary: Some(temp.path().to_path_buf()),
                user: None,
                compatibility: Vec::new(),
            },
            &[],
        );
        registry.activate_exact("deploy").unwrap();
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.workspace = workspace::WorkspaceContext::discover(temp.path()).unwrap();
        state.cwd = state.workspace.cwd().to_string_lossy().into_owned();
        state.skills = std::sync::Arc::new(std::sync::Mutex::new(registry));
        let store = session::SessionStore::new(temp.path().join("sessions"));

        let id = save_current_session(&mut state, &store).unwrap();
        let restored = store.load(&id.to_string()).unwrap();
        assert_eq!(restored.active_skills.len(), 1);
        let json = std::fs::read_to_string(temp.path().join("sessions").join(format!("{id}.json")))
            .unwrap();
        assert!(!json.contains("SECRET-BODY-NOT-SERIALIZED"));
        assert!(json.contains("sha256"));
    }

