    #[test]
    fn explicit_queue_transition_does_not_interrupt_turn() {
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.turn_lifecycle.begin();
        state.input = "follow up after this".into();
        state.input_cursor = state.input.len();

        assert!(queue_composer_draft(&mut state));
        assert!(state.input.is_empty());
        assert_eq!(state.input_queue.len(), 1);
        assert_eq!(
            state.input_queue.selected().unwrap().text,
            "follow up after this"
        );
        assert_eq!(
            state.turn_lifecycle.outcome,
            activity::TurnOutcome::InProgress
        );

        let definition = crate::workflow::WorkflowDefinition {
            version: 1,
            id: "queue-pause".into(),
            title: "Queue pause".into(),
            steps: vec![crate::workflow::WorkflowStep {
                id: "active".into(),
                depends_on: Vec::new(),
                prompt: "active".into(),
                model: None,
                tools: Some(Vec::new()),
                grants: Vec::new(),
                retry: crate::workflow::WorkflowRetryPolicy::default(),
                output: None,
                evidence: vec![crate::workflow::WorkflowEvidenceGate::AssistantOutput],
            }],
        }
        .validate()
        .unwrap();
        let loaded = crate::workflow::LoadedWorkflow {
            definition,
            relative_path: "workflow.toml".into(),
            digest: "queue".into(),
        };
        let mut workflow = crate::workflow::WorkflowRun::start(
            &loaded,
            "local".into(),
            "model".into(),
            chrono::Utc::now(),
        );
        workflow
            .begin_step(
                &loaded.definition,
                "active",
                "local".into(),
                "model".into(),
                chrono::Utc::now(),
            )
            .unwrap();
        state.workflow_run = Some(workflow);
        state.workflow_execution = Some(crate::workflow::WorkflowExecutionContext {
            step_id: "active".into(),
            provider: "local".into(),
            model: "model".into(),
            tools: Some(std::collections::HashSet::new()),
            grants: Vec::new(),
        });
        state.input = "pause after this".into();
        state.input_cursor = state.input.len();
        assert!(queue_composer_draft(&mut state));
        assert_eq!(
            state.workflow_run.as_ref().unwrap().status,
            crate::workflow::WorkflowRunStatus::Paused
        );
        assert!(state.workflow_pause_requested);
        assert!(state.workflow_execution.is_some());
    }

    #[tokio::test]
    async fn interrupt_turn_invalidates_events_and_holds_drafts_in_every_phase() {
        for phase in [
            activity::ActivityPhase::Sending,
            activity::ActivityPhase::Waiting,
            activity::ActivityPhase::Reasoning,
            activity::ActivityPhase::Responding,
            activity::ActivityPhase::Tool,
            activity::ActivityPhase::Interaction,
            activity::ActivityPhase::Paused,
        ] {
            let mut state = AppState::new(context::ShellHistory::in_memory());
            state.turn_lifecycle.begin();
            state.turn_lifecycle.set_phase(phase);
            state.stream_generation = 42;
            state.input = "keep this replacement draft".into();
            state.input_cursor = 4;
            let queued = state.input_queue.enqueue("do this later").unwrap();
            state.goal_evaluating = true;
            state.goal_resume_requested = true;
            state.goal_continuation_prompt = Some("old goal continuation".into());
            state.workflow_next_requested = true;
            state.soft_pause.request(true);
            let mut stream = Some(tokio::spawn(std::future::pending::<()>()));
            let mut tools = Some(tokio::spawn(std::future::pending::<()>()));
            let mut approval = Some(tokio::spawn(std::future::pending::<()>()));
            let mut goal = Some(tokio::spawn(std::future::pending::<()>()));
            let probes = [&stream, &tools, &approval, &goal]
                .map(|task| task.as_ref().unwrap().abort_handle());

            interrupt_active_turn(
                &mut state,
                TurnTaskHandles {
                    stream: &mut stream,
                    tools: &mut tools,
                    approval: &mut approval,
                    goal: &mut goal,
                },
            );
            tokio::task::yield_now().await;
            assert!(probes.iter().all(tokio::task::AbortHandle::is_finished));
            assert_eq!(
                state.stream_generation, 43,
                "late generation 42 must be rejected"
            );
            assert_eq!(
                state.turn_lifecycle.outcome,
                activity::TurnOutcome::Cancelled
            );
            assert!(!queue::should_drain_after(state.turn_lifecycle.outcome));
            assert_eq!(state.input, "keep this replacement draft");
            assert_eq!(state.input_cursor, 4);
            assert_eq!(state.input_queue.front().unwrap().id, queued);
            assert!(state.restored_queue_ids.contains(&queued));
            assert!(!state.goal_evaluating);
            assert!(!state.goal_resume_requested);
            assert!(state.goal_continuation_prompt.is_none());
            assert!(!state.workflow_next_requested);
            assert_eq!(state.soft_pause, activity::SoftPauseState::Inactive);
        }
    }

    #[test]
    fn global_interrupt_key_stops_with_overlays_and_approval() {
        use crossterm::event::{KeyCode, KeyModifiers};
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.turn_lifecycle.begin();
        state.model_picker_open = true;
        assert!(is_turn_stop_event(
            &state,
            &tui::Event::Key(KeyCode::Char('c'), KeyModifiers::CONTROL)
        ));
        assert!(!is_turn_stop_event(
            &state,
            &tui::Event::Key(KeyCode::Esc, KeyModifiers::NONE)
        ));
        state.model_picker_open = false;
        state.approval_queue.begin_batch(vec![PendingApproval {
            tool_name: "run_command".into(),
            tool_args: "{}".into(),
            tool_id: "old".into(),
            network_requested: false,
            email_preview: None,
            email_draft_ref: None,
        }]);
        assert!(is_turn_stop_event(
            &state,
            &tui::Event::Key(KeyCode::Esc, KeyModifiers::NONE)
        ));
        let mut stream = None;
        let mut tools = None;
        let mut approval = None;
        let mut goal = None;
        interrupt_active_turn(
            &mut state,
            TurnTaskHandles {
                stream: &mut stream,
                tools: &mut tools,
                approval: &mut approval,
                goal: &mut goal,
            },
        );
        assert!(!state.approval_queue.is_active());
        assert!(!state.manual_resolutions.is_active());
        assert!(state.interaction.is_none());
        assert!(!is_turn_stop_event(
            &state,
            &tui::Event::Key(KeyCode::Char('c'), KeyModifiers::CONTROL)
        ));
    }

    #[test]
    fn interrupt_submission_removes_only_selected_queue_item_and_preserves_images() {
        let temp = tempfile::tempdir().unwrap();
        let store = session::SessionStore::new(temp.path());
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.turn_lifecycle.begin();
        let selected = state.input_queue.enqueue("old draft").unwrap();
        let held = state.input_queue.enqueue("other draft").unwrap();
        state.pasted_images.push(
            crate::image_content::RawClipboardImage::new(1, 1, vec![0, 0, 0, 255])
                .unwrap()
                .normalize()
                .unwrap(),
        );
        let mut stream = None;
        let mut tools = None;
        let mut approval = None;
        let mut goal = None;
        assert_eq!(
            prepare_interrupt_submission(
                &mut state,
                "replacement",
                Some(selected),
                &store,
                TurnTaskHandles {
                    stream: &mut stream,
                    tools: &mut tools,
                    approval: &mut approval,
                    goal: &mut goal
                }
            ),
            Some("replacement".into())
        );
        assert_eq!(state.input_queue.len(), 1);
        assert_eq!(state.input_queue.front().unwrap().id, held);
        assert!(state.restored_queue_ids.contains(&held));
        assert_eq!(state.pasted_images.len(), 1);
        assert_eq!(state.input_history.last().unwrap(), "replacement");
        assert_eq!(
            state.turn_lifecycle.outcome,
            activity::TurnOutcome::Cancelled
        );
    }

