    /// Two identical tool calls denied by a persistent DenyTool rule must
    /// each produce their own typed error result.
    #[tokio::test]
    async fn duplicate_persistent_denial_preserves_error_status() {
        let rules = vec![config::ApprovalRule::DenyTool("write_file".into())];

        let tc_a = ToolCall {
            id: "call_1".into(),
            name: "write_file".into(),
            arguments: serde_json::json!({"path":"/tmp/ca-denied-a","content":"no"}).to_string(),
            status: ToolStatus::Pending,
            output: None,
        };
        let tc_b = ToolCall {
            id: "call_2".into(),
            name: "write_file".into(),
            arguments: serde_json::json!({"path":"/tmp/ca-denied-b","content":"no"}).to_string(),
            status: ToolStatus::Pending,
            output: None,
        };

        let workspace = workspace::WorkspaceContext::discover("/tmp").unwrap();
        let outcome = execute_pending_tools_async(
            &[tc_a, tc_b],
            &ApprovalMode::RunEverything,
            &workspace,
            30,
            &rules,
            &[],
            &[],
            sandbox::SandboxMode::PolicyOnly,
            jobs::JobOwner::process(),
            &test_skill_registry(),
            &test_work_state(),
            None,
            None,
            None,
            &test_hook_runner(),
            None,
        )
        .await;
        let results = outcome.results;

        // Must produce exactly two results with distinct tool IDs
        assert_eq!(results.len(), 2, "expected two results for two tool calls");
        assert_eq!(results[0].tool_id, "call_1");
        assert_eq!(results[1].tool_id, "call_2");

        // Both must carry the denial message
        for (i, r) in results.iter().enumerate() {
            assert!(
                r.output.contains("Denied"),
                "result {i} should contain denial text, got: {}",
                r.output
            );
        }

        // Both must have Error status — this is the critical assertion
        assert_eq!(
            results[0].status,
            ResolvedToolStatus::Error,
            "first denial should be Error"
        );
        assert_eq!(
            results[1].status,
            ResolvedToolStatus::Error,
            "second denial must also be Error, not Done"
        );

        assert!(outcome.pending.is_empty());
    }

    #[tokio::test]
    async fn tool_dispatch_fires_exact_pre_and_matching_post_hook_events() {
        let temp = tempfile::tempdir().unwrap();
        let input_path = temp.path().join("input.txt");
        let log_path = temp.path().join("events.log");
        std::fs::write(&input_path, "hello\n").unwrap();
        let command = format!(
            "printf '%s\\n' \"$CA_HOOK_EVENT\" >> \"{}\"",
            log_path.display()
        );
        let hook = |event: hooks::HookEvent| config::HookConfig {
            event: event.as_str().into(),
            command: command.clone(),
            enabled: true,
            timeout_secs: 5,
            fail_closed: true,
        };
        let runner = hooks::HookRunner::new(
            vec![
                hook(hooks::HookEvent::PreToolUse),
                hook(hooks::HookEvent::PostToolUse),
                hook(hooks::HookEvent::PostToolUseFailure),
            ],
            sandbox::SandboxMode::PolicyOnly,
        );
        let workspace = workspace::WorkspaceContext::discover(temp.path()).unwrap();

        let success = execute_tool_dispatch(
            "read_file",
            &serde_json::json!({"path": input_path}),
            &workspace,
            5,
            sandbox::SandboxMode::PolicyOnly,
            false,
            jobs::JobOwner::process(),
            &test_skill_registry(),
            &test_work_state(),
            None,
            None,
            None,
            &runner,
            Some("safe-session"),
        )
        .await;
        assert!(success.is_success());

        let failure = execute_tool_dispatch(
            "not_a_tool",
            &serde_json::json!({}),
            &workspace,
            5,
            sandbox::SandboxMode::PolicyOnly,
            false,
            jobs::JobOwner::process(),
            &test_skill_registry(),
            &test_work_state(),
            None,
            None,
            None,
            &runner,
            Some("safe-session"),
        )
        .await;
        assert!(!failure.is_success());
        assert_eq!(
            std::fs::read_to_string(log_path).unwrap(),
            "pre_tool_use\npost_tool_use\npre_tool_use\npost_tool_use_failure\n"
        );
    }

    #[tokio::test]
    async fn privilege_hook_payload_contains_only_exact_metadata_and_redacted_result() {
        let temp = tempfile::tempdir().unwrap();
        let log = temp.path().join("privilege-hook.json");
        let command = format!("/usr/bin/tee \"{}\" >/dev/null", log.display());
        let runner = hooks::HookRunner::new(
            vec![config::HookConfig {
                event: hooks::HookEvent::PostToolUseFailure.as_str().into(),
                command,
                enabled: true,
                timeout_secs: 5,
                fail_closed: true,
            }],
            sandbox::SandboxMode::PolicyOnly,
        );
        let invocation = crate::privilege::PreparedPrivilegeInvocation::display_fixture_for_test(
            "/usr/bin/id",
            vec!["space value".into(), "$(literal);&|".into()],
            temp.path().to_str().unwrap(),
            sandbox::SandboxMode::PolicyOnly,
            &"b".repeat(64),
        );
        let execution = crate::agent::registry::ToolExecutionResult::Failure(format!(
            "authentication output: {}",
            crate::privilege::REDACTION_MARKER
        ));
        run_privilege_post_hook(&invocation, &execution, &runner, Some("session-test")).await;

        let payload = std::fs::read_to_string(log).unwrap();
        assert!(payload.contains(crate::privilege::REDACTION_MARKER));
        assert!(payload.contains("/usr/bin/id"));
        assert!(payload.contains("space value"));
        assert!(!payload.contains("correct horse"));
        assert!(!format!("{invocation:?}{execution:?}").contains("correct horse"));
    }

