    #[tokio::test]
    async fn stale_hook_lifecycle_result_discards_only_its_captured_owner() {
        let temp = tempfile::tempdir().unwrap();
        let mut state = AppState {
            current_session: Some(session::SessionV4::new(
                "fixture",
                temp.path().to_string_lossy(),
                "fixture",
                "fixture",
                Vec::new(),
            )),
            active_agent_turn_id: Some(uuid::Uuid::new_v4()),
            stream_generation: 7,
            ..Default::default()
        };
        let current = interactive_hook_owner(&state);
        let runner = hooks::HookRunner::new(
            vec![config::HookConfig {
                event: "after_agent_response".into(),
                command: r#"printf '%s' '{"additional_context":"owner-isolated"}'"#.into(),
                enabled: true,
                timeout_secs: 5,
                fail_closed: true,
            }],
            sandbox::SandboxMode::PolicyOnly,
        );
        let payload = hooks::HookPayload {
            hook_event_name: hooks::HookEvent::AfterAgentResponse.as_str().into(),
            session_id: None,
            cwd: temp.path().to_string_lossy().into(),
            extra: serde_json::json!({}),
        };
        for stale in [
            hooks::HookOwner {
                session_id: Some(uuid::Uuid::new_v4()),
                ..current
            },
            hooks::HookOwner {
                pane_id: current.pane_id.saturating_add(1),
                ..current
            },
            hooks::HookOwner {
                turn_id: Some(uuid::Uuid::new_v4()),
                ..current
            },
            hooks::HookOwner {
                generation: current.generation + 1,
                ..current
            },
            hooks::HookOwner {
                child_id: Some(uuid::Uuid::new_v4()),
                ..current
            },
        ] {
            let old_invocation = hooks::HookInvocation::new(stale);
            let old_runner = runner.for_invocation(old_invocation);
            let current_runner = bind_hook_lifecycle(&mut state, &runner, 3);
            old_runner
                .run_event(
                    &stale,
                    hooks::HookEvent::AfterAgentResponse,
                    &payload,
                    &[temp.path().to_path_buf()],
                )
                .await;
            current_runner
                .run_event(
                    &current,
                    hooks::HookEvent::AfterAgentResponse,
                    &payload,
                    &[temp.path().to_path_buf()],
                )
                .await;
            let result = HookLifecycleResult {
                generation: 3,
                owner: stale,
                invocation_id: old_invocation.id,
                stage: HookLifecycleStage::SessionStart,
                batch: Default::default(),
            };
            assert!(!hook_lifecycle_matches(&state, &runner, &result));
            assert!(old_runner.take_contexts(&stale).is_empty());
            assert_eq!(current_runner.take_contexts(&current), ["owner-isolated"]);
        }
        let old_invocation = hooks::HookInvocation::new(current);
        let old_runner = runner.for_invocation(old_invocation);
        let current_runner = bind_hook_lifecycle(&mut state, &runner, 8);
        old_runner
            .run_event(
                &current,
                hooks::HookEvent::AfterAgentResponse,
                &payload,
                &[temp.path().to_path_buf()],
            )
            .await;
        current_runner
            .run_event(
                &current,
                hooks::HookEvent::AfterAgentResponse,
                &payload,
                &[temp.path().to_path_buf()],
            )
            .await;
        let late = HookLifecycleResult {
            generation: 7,
            owner: current,
            invocation_id: old_invocation.id,
            stage: HookLifecycleStage::Revalidate {
                event: hooks::HookEvent::AfterAgentResponse,
            },
            batch: Default::default(),
        };
        assert!(!hook_lifecycle_matches(&state, &runner, &late));
        assert_eq!(current_runner.take_contexts(&current), ["owner-isolated"]);
        let matching = HookLifecycleResult {
            generation: 8,
            owner: current,
            invocation_id: current_runner.invocation_id().unwrap(),
            stage: HookLifecycleStage::SessionStart,
            batch: Default::default(),
        };
        assert!(hook_lifecycle_matches(&state, &runner, &matching));
        let mut other_pane = AppState {
            pane_id: panes::PaneId::from(2),
            ..Default::default()
        };
        let other_runner = bind_hook_lifecycle(&mut other_pane, &runner, 9);
        assert!(
            hook_lifecycle_matches(&state, &runner, &matching),
            "newer lifecycle in another pane must not stale this pane"
        );
        let other_result = HookLifecycleResult {
            generation: 9,
            owner: other_runner.owner(),
            invocation_id: other_runner.invocation_id().unwrap(),
            stage: HookLifecycleStage::SessionStart,
            batch: Default::default(),
        };
        assert!(hook_lifecycle_matches(&other_pane, &runner, &other_result));
    }

    #[tokio::test]
    async fn cancelling_lifecycle_in_one_pane_keeps_other_panes_task_alive() {
        let mut left = AppState::default();
        let mut right = AppState {
            pane_id: panes::PaneId::from(2),
            ..Default::default()
        };
        let left_task = tokio::spawn(std::future::pending::<()>());
        let right_task = tokio::spawn(std::future::pending::<()>());
        left.active_hook_abort = Some(left_task.abort_handle());
        right.active_hook_abort = Some(right_task.abort_handle());
        let mut shared = Some(right_task);
        release_owned_hook_task(&mut left, &mut shared, true);
        assert!(
            tokio::time::timeout(std::time::Duration::from_secs(1), left_task)
                .await
                .unwrap()
                .unwrap_err()
                .is_cancelled()
        );
        assert!(shared.is_some());
        assert!(!right.active_hook_abort.as_ref().unwrap().is_finished());
        release_owned_hook_task(&mut right, &mut shared, true);
        assert!(shared.is_none());
    }

    #[tokio::test]
    async fn interrupting_active_turn_retires_owned_response_hook_and_keeps_draft() {
        let temp = tempfile::tempdir().unwrap();
        let store = session::SessionStore::new(temp.path());
        let runner = hooks::HookRunner::new(Vec::new(), sandbox::SandboxMode::PolicyOnly);
        let mut left = AppState {
            input: "replacement draft".into(),
            stream_generation: 7,
            active_agent_turn_id: Some(uuid::Uuid::new_v4()),
            hook_runner: Some(runner.clone()),
            ..Default::default()
        };
        left.turn_lifecycle.begin();
        let owned = bind_hook_lifecycle(&mut left, &runner, 3);
        let mut left_task = tokio::spawn(std::future::pending::<()>());
        left.active_hook_abort = Some(left_task.abort_handle());
        left.hook_running = true;
        let late_result = HookLifecycleResult {
            generation: 3,
            owner: owned.owner(),
            invocation_id: owned.invocation_id().unwrap(),
            stage: HookLifecycleStage::AfterResponse {
                has_tools: false,
                blocked_event: None,
            },
            batch: Default::default(),
        };
        let mut right = AppState {
            pane_id: panes::PaneId::from(2),
            hook_runner: Some(runner.clone()),
            ..Default::default()
        };
        let right_owned = bind_hook_lifecycle(&mut right, &runner, 4);
        let right_task = tokio::spawn(std::future::pending::<()>());
        right.active_hook_abort = Some(right_task.abort_handle());
        right.hook_running = true;
        let mut stream = None;
        let mut tools = None;
        let mut approval = None;
        let mut goal = None;
        stop_active_turn(
            &mut left,
            &store,
            TurnTaskHandles {
                stream: &mut stream,
                tools: &mut tools,
                approval: &mut approval,
                goal: &mut goal,
            },
        );
        let late_matches = hook_lifecycle_matches(&left, &runner, &late_result);
        let cancelled =
            tokio::time::timeout(std::time::Duration::from_secs(1), &mut left_task).await;
        let task_cancelled = matches!(&cancelled, Ok(Err(error)) if error.is_cancelled());
        if cancelled.is_err() {
            left_task.abort();
            let _ = left_task.await;
        }
        let other_task_alive = !right.active_hook_abort.as_ref().unwrap().is_finished();
        right_task.abort();
        let _ = right_task.await;

        assert!(
            !left.hook_running,
            "retired response hook must not block Enter"
        );
        assert!(left.active_hook_abort.is_none());
        assert!(left.active_hook_lifecycle.is_none());
        assert!(
            task_cancelled,
            "the retired pane-owned hook must be aborted"
        );
        assert!(!late_matches, "cancelled hook result must stay stale");
        assert!(!left.turn_lifecycle.is_active());
        assert_eq!(left.input, "replacement draft");
        assert!(other_task_alive);
        assert!(right.hook_running);
        assert_eq!(
            right.active_hook_lifecycle.unwrap().1,
            hooks::HookInvocation {
                owner: right_owned.owner(),
                id: right_owned.invocation_id().unwrap(),
            }
        );
    }

