    #[test]
    fn fail_closed_tool_hook_blocks_continuation_and_opens_repair_manager() {
        let mut state = AppState::default();
        state.turn_lifecycle.begin();
        state.active_turn_start_message_count = Some(3);
        state.goal_state = Some(
            goal::GoalState::start(
                "finish the recorded task".into(),
                goal::GoalLimits::from_config(goal::GoalConfig::default()).unwrap(),
                chrono::Utc::now(),
            )
            .unwrap(),
        );
        assert!(apply_tool_hook_block(
            &mut state,
            hooks::HookEvent::PostToolUse,
            "Hook failed (fail-closed)".into(),
        ));
        assert!(state.hook_blocked);
        assert_eq!(
            state.hook_blocked_event,
            Some(hooks::HookEvent::PostToolUse)
        );
        assert!(state.hook_manager.is_some());
        assert!(matches!(
            state.hook_manager_request,
            Some(crate::app::HookManagerRequest {
                operation: crate::app::HookManagerOperation::Reload,
                ..
            })
        ));
        assert_eq!(state.turn_lifecycle.outcome, activity::TurnOutcome::Failed);
        assert_eq!(state.retry_boundary, Some(RetryBoundary::replay(3)));
        assert_eq!(
            state.goal_state.as_ref().map(|goal| goal.status),
            Some(goal::GoalStatus::Paused)
        );
    }

    #[test]
    fn blocked_hook_requires_successful_exact_event_revalidation() {
        let mut state = AppState {
            hook_blocked: true,
            hook_blocked_event: Some(hooks::HookEvent::PostToolUse),
            ..AppState::default()
        };
        assert!(!apply_hook_revalidation_result(
            &mut state,
            hooks::HookEvent::PostToolUse,
            hooks::HookBatchResult {
                denied: Some("still failing".into()),
                contexts: Vec::new(),
                fail_closed: true,
            },
        ));
        assert!(state.hook_blocked);
        assert_eq!(
            state.hook_blocked_event,
            Some(hooks::HookEvent::PostToolUse)
        );
        assert!(apply_hook_revalidation_result(
            &mut state,
            hooks::HookEvent::PostToolUse,
            hooks::HookBatchResult::default(),
        ));
        assert!(!state.hook_blocked);
        assert!(state.hook_blocked_event.is_none());
    }

    #[tokio::test]
    async fn typed_plan_tool_applies_once_without_granting_user_approval() {
        let workspace = workspace::WorkspaceContext::discover("/tmp").unwrap();
        let work_state = test_work_state();
        let mut normalizer =
            agent::dsml::DsmlStreamNormalizer::new(Some(config::ToolCallFormat::DeepseekDsml));
        let payload = concat!(
            "<|DSML|tool_calls>",
            "<|DSML|invoke name=\"propose_plan\">",
            "<|DSML|parameter name=\"expected_revision\" string=\"false\">0</|DSML|parameter>",
            "<|DSML|parameter name=\"title\" string=\"true\">Implement</|DSML|parameter>",
            "<|DSML|parameter name=\"tasks\" string=\"false\">[\"Validate\"]</|DSML|parameter>",
            "</|DSML|invoke>",
            "</|DSML|tool_calls>",
        );
        assert!(normalizer
            .normalize(agent::stream::ProviderEvent::Text(payload.into()))
            .unwrap()
            .is_empty());
        let mut events = normalizer
            .normalize(agent::stream::ProviderEvent::Finish {
                reason: agent::stream::FinishReason::Stop,
                usage: None,
            })
            .unwrap();
        events.extend(
            normalizer
                .normalize(agent::stream::ProviderEvent::Done)
                .unwrap(),
        );
        let mut assembler = agent::stream::AssistantTurnAssembler::new();
        for event in &events {
            assembler.push(event).unwrap();
        }
        let turn = assembler.finish().unwrap();
        assert!(turn.content.is_empty());
        assert_eq!(turn.tool_calls.len(), 1);
        let assembled = &turn.tool_calls[0];
        let call = ToolCall {
            id: assembled.id.clone(),
            name: assembled.name.clone(),
            arguments: assembled.arguments.clone(),
            status: ToolStatus::Pending,
            output: None,
        };
        let outcome = execute_pending_tools_async(
            &[call],
            &ApprovalMode::RunEverything,
            &workspace,
            5,
            &[],
            &[],
            &[],
            sandbox::SandboxMode::PolicyOnly,
            jobs::JobOwner::process(),
            &test_skill_registry(),
            &work_state,
            None,
            None,
            None,
            &test_hook_runner(),
            None,
        )
        .await;

        assert_eq!(outcome.results[0].status, ResolvedToolStatus::Done);
        let work = work_state.lock().unwrap();
        let plan = work.plan.as_ref().unwrap();
        assert_eq!(plan.revision, 1);
        assert_eq!(plan.status, work::PlanStatus::Proposed);
        assert!(plan.approved_by.is_none());
    }

