    #[tokio::test]
    async fn plan_execute_rebuilds_request_tools_and_successfully_edits_with_empty_graph_grants() {
        let temp = tempfile::tempdir().unwrap();
        let root = temp.path().canonicalize().unwrap();
        let call_arguments =
            serde_json::json!({"path":"plan-proof.txt","content":"executed by current agent\n"});
        let event = serde_json::json!({"choices":[{"index":0,"delta":{"tool_calls":[{
            "index":0,"id":"plan-write","type":"function","function":{
                "name":"write_file","arguments":call_arguments.to_string()
            }
        }]},"finish_reason":"tool_calls"}]});
        let response = format!("data: {event}\n\ndata: [DONE]\n\n").into_bytes();
        let (base_url, captured) = test_provider_sequence(vec![("200 OK", response)]).await;
        let mut config = CaConfig::default_config();
        config.defaults.provider = "local".into();
        config.defaults.model = "plan-model".into();
        config.providers = HashMap::from([(
            "local".into(),
            config::ProviderConfig {
                google: None,
                tool_schema_policy: Default::default(),
                base_url,
                api_key: String::new(),
                protocol: agent::ProviderProtocol::default(),
                prompt_cache_mode: config::PromptCacheMode::Implicit,
                models: vec!["plan-model".into()],
                timeout: config::ProviderTimeoutConfig::default(),
            },
        )]);
        let sessions = session::SessionStore::new(root.join("sessions"));
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.cwd = root.display().to_string();
        state.workspace = workspace::WorkspaceContext::from_primary(root.clone(), root.clone());
        state.skills = test_skill_registry();
        state.mode = AgentMode::Plan;
        state.current_model = Some(ModelInfo {
            provider: "local".into(),
            id: "plan-model".into(),
            display_name: "plan-model".into(),
        });
        state.work_state = configured_test_graph(None).0;
        {
            let mut work = state.work_state.lock().unwrap();
            work.user_pause_agent_graph().unwrap();
            let revision = work.revision();
            work.apply_model_mutation(work::WorkMutation::Edit {
                expected_revision: revision,
                title: None,
                body: Some("Write plan-proof.txt and verify its contents.".into()),
                decisions: Vec::new(),
            })
            .unwrap();
            for task in &mut work.plan.as_mut().unwrap().tasks {
                let grant = &mut task.agent.as_mut().unwrap().grant;
                grant.tools.clear();
                grant.paths.clear();
                grant.commands.clear();
            }
        }
        state.turn_lifecycle.begin();
        state.plan_turn_start_revision = Some(0);
        state.active_turn_prompt = Some(crate::app::ActiveTurnPromptState {
            stable_system: "STALE PLANNING EPOCH".into(),
            logical_turn_system: "You are in PLAN mode. Do not execute filesystem tools.".into(),
            skill_prompt: String::new(),
            transient_user_prompts: Vec::new(),
            pasted_images: Vec::new(),
            canonical_tools: Some(
                agent::registry::ToolRegistry::builtins()
                    .definitions(agent::registry::ToolProfile::Plan),
            ),
        });
        plan::finish_response(&mut state);
        assert!(state.plan_proposal.is_some());
        assert!(!state.turn_lifecycle.is_active());
        assert!(state.active_turn_prompt.is_none());
        manage_plan_command(&mut state, "execute");
        let (tx, mut rx) = mpsc::unbounded_channel();
        let mut handle = None;
        plan::start_requested(&mut state, &config, &sessions, &tx, &mut handle);
        assert_eq!(state.mode, AgentMode::Agent);
        assert!(state.turn_lifecycle.is_active());
        assert!(plan::manage_command(&mut state, "execute").is_err());
        handle.take().expect("execution starts").await.unwrap();
        while let Ok(event) = rx.try_recv() {
            match event {
                StreamMsg::PromptToolsPrepared { tools, .. } => {
                    state.active_turn_prompt.as_mut().unwrap().canonical_tools = Some(tools)
                }
                StreamMsg::ContextPrepared(breakdown, names, _) => {
                    state.context_breakdown = Some(breakdown);
                    state.active_tool_names = names.into_iter().collect();
                }
                StreamMsg::Delta(delta, _) => handle_stream_delta(&mut state, delta),
                StreamMsg::Error { error, .. } => panic!("unexpected provider failure: {error:?}"),
                _ => {}
            }
        }
        assert!(state.active_tool_names.contains("write_file"));
        assert!(state.active_tool_names.contains("run_command"));
        assert!(!state.active_tool_names.contains("propose_plan"));
        let streaming = state.streaming.take().unwrap();
        let (calls, recovered) =
            finalize_streamed_tool_calls(streaming.tool_calls, &state.active_tool_names, false)
                .unwrap();
        assert!(!recovered);
        let result = execute_pending_tools_async_with_email(
            &calls,
            &ApprovalMode::RunEverything,
            &state.workspace,
            5,
            config::CommandOutputPolicy::Bounded,
            &[],
            &[],
            &[],
            sandbox::SandboxMode::PolicyOnly,
            state.job_owner,
            &state.skills,
            &state.work_state,
            None,
            None,
            None,
            None,
            false,
            &test_hook_runner(),
            None,
            None,
        )
        .await;
        assert!(result.pending.is_empty());
        assert_eq!(
            result.results[0].status,
            crate::app::ResolvedToolStatus::Done
        );
        assert_eq!(
            std::fs::read_to_string(root.join("plan-proof.txt")).unwrap(),
            "executed by current agent\n"
        );
        let requests = captured.await.unwrap();
        assert_eq!(requests.len(), 1);
        let request = String::from_utf8_lossy(&requests[0]);
        assert!(!request.contains("STALE PLANNING EPOCH"));
        assert!(!request.contains("You are in PLAN mode."));
        assert!(request.contains("Task-graph grants are only"));
        assert!(request.contains("Write plan-proof.txt and verify"));
        let saved = sessions
            .load(&state.current_session.as_ref().unwrap().id.to_string())
            .unwrap();
        assert_eq!(
            saved.work_state.plan.as_ref().unwrap().status,
            work::PlanStatus::Approved
        );
        let mut stream = None;
        let mut tools = None;
        let mut approval = None;
        let mut goal = None;
        interrupt_active_turn(
            &mut state,
            TurnTaskHandles {
                stream: &mut stream,
                tools: &mut tools,
                approval: &mut approval,
                goal: &mut goal,
            },
        );
        assert!(!state.turn_lifecycle.is_active());
        assert!(state.active_turn_prompt.is_none());
        assert!(state.plan_execute_requested.is_none());
        let review = saved.work_state.plan.as_ref().unwrap().review();
        state.plan_execute_requested = Some(review);
        state.plan_proposal = Some(review);
        state.plan_reader = Some(review);
        apply_session_state(&mut state, saved, false);
        assert!(state.plan_proposal.is_none());
        assert!(state.plan_reader.is_none());
        assert!(state.plan_execute_requested.is_none());
    }

