    #[tokio::test]
    async fn interactive_network_command_respects_one_explicit_ask_and_deny() {
        let temp = tempfile::tempdir().unwrap();
        let workspace = workspace::WorkspaceContext::discover(temp.path()).unwrap();
        let call = ToolCall {
            id: "call-network-policy".into(),
            name: "run_command".into(),
            arguments: serde_json::json!({
                "command":"printf network-command",
                "network":true,
            })
            .to_string(),
            status: ToolStatus::Pending,
            output: None,
        };
        let rule = |decision| crate::permission::PermissionRule {
            decision,
            matcher: crate::permission::PermissionMatcher::Tool {
                tool: "run_command".into(),
            },
        };

        let asked = execute_pending_tools_async(
            std::slice::from_ref(&call),
            &ApprovalMode::RunEverything,
            &workspace,
            5,
            &[],
            &[rule(crate::permission::PermissionDecision::Ask)],
            &[],
            sandbox::SandboxMode::PolicyOnly,
            jobs::JobOwner::process(),
            &test_skill_registry(),
            &test_work_state(),
            None,
            None,
            None,
            &test_hook_runner(),
            None,
        )
        .await;
        assert!(asked.results.is_empty());
        assert!(matches!(
            asked.pending.as_slice(),
            [crate::interaction::PendingManualResolution::Approval(
                PendingApproval {
                    network_requested: true,
                    ..
                }
            )]
        ));

        let denied = execute_pending_tools_async(
            &[call],
            &ApprovalMode::RunEverything,
            &workspace,
            5,
            &[],
            &[rule(crate::permission::PermissionDecision::Deny)],
            &[],
            sandbox::SandboxMode::PolicyOnly,
            jobs::JobOwner::process(),
            &test_skill_registry(),
            &test_work_state(),
            None,
            None,
            None,
            &test_hook_runner(),
            None,
        )
        .await;
        assert!(denied.pending.is_empty());
        assert_eq!(denied.results.len(), 1);
        assert_eq!(denied.results[0].status, ResolvedToolStatus::Error);
        assert!(denied.results[0].output.contains("Denied"));
    }

