    #[cfg(any(target_os = "macos", target_os = "linux", target_os = "freebsd"))]
    #[test]
    fn privilege_tool_surface_is_limited_to_interactive_agent_mode() {
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.mode = AgentMode::Agent;
        assert_eq!(
            privilege_tool_enabled(&state),
            crate::privilege::capability_available()
        );

        for mode in [
            AgentMode::Ask,
            AgentMode::Debug,
            AgentMode::Plan,
            AgentMode::Custom("review".into()),
        ] {
            state.mode = mode;
            assert!(!privilege_tool_enabled(&state));
        }

        state.mode = AgentMode::Agent;
        state.workflow_execution = Some(crate::workflow::WorkflowExecutionContext {
            step_id: "privilege-negative-surface".into(),
            provider: "local".into(),
            model: "model".into(),
            tools: None,
            grants: Vec::new(),
        });
        assert!(!privilege_tool_enabled(&state));
    }

