    #[test]
    fn permission_delete_failure_preserves_manager_filter_selection_and_confirmation() {
        let mut state = AppState {
            permission_manager_generation: 7,
            permission_manager: Some(crate::app::PermissionManagerState {
                filter: "cargo".into(),
                selected_idx: 1,
                entries: vec![
                    crate::app::PermissionManagerEntry {
                        source: crate::app::PermissionEntrySource::Rich(0),
                        decision: crate::permission::PermissionDecision::Ask,
                        matcher: "run_command · cargo test".into(),
                    },
                    crate::app::PermissionManagerEntry {
                        source: crate::app::PermissionEntrySource::Session(0),
                        decision: crate::permission::PermissionDecision::Allow,
                        matcher: "read_file".into(),
                    },
                ],
                confirmation: Some(crate::app::PermissionDeleteConfirmation {
                    source: crate::app::PermissionEntrySource::Rich(0),
                    label: "Ask · run_command · cargo test".into(),
                    delete_selected: true,
                }),
                busy: true,
                writes_enabled: true,
                generation: 7,
                error: None,
                notice: None,
            }),
            ..AppState::default()
        };
        let mut config = CaConfig::default_config();
        config.permission_rules = vec![crate::permission::PermissionRule {
            decision: crate::permission::PermissionDecision::Ask,
            matcher: crate::permission::PermissionMatcher::CommandPrefix {
                prefix: vec!["cargo".into(), "test".into()],
            },
        }];

        apply_permission_delete_result(
            &mut state,
            &mut config,
            PermissionDeleteTaskResult {
                generation: 7,
                source: crate::app::PermissionEntrySource::Rich(0),
                result: Err("simulated filesystem failure".into()),
            },
        );

        let manager = state.permission_manager.as_ref().unwrap();
        assert_eq!(manager.filter, "cargo");
        assert_eq!(manager.selected_idx, 1);
        assert!(manager.confirmation.is_some());
        assert!(!manager.busy);
        assert!(manager.error.as_deref().unwrap().contains("filesystem"));
        assert_eq!(config.permission_rules.len(), 1);
    }

