    #[test]
    fn pending_approvals_reclassify_only_after_matching_live_authority() {
        let root = tempfile::tempdir().unwrap();
        let path = root.path().join("sample.rs");
        std::fs::write(&path, "old\n").unwrap();
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.workspace = workspace::WorkspaceContext::discover(root.path()).unwrap();
        state.approval = ApprovalMode::Allowlist;
        let mut config = CaConfig::default();
        let approval = PendingApproval {
            tool_name: "edit_file".into(),
            tool_args: serde_json::json!({
                "path": path,
                "old_string": "old",
                "new_string": "new"
            })
            .to_string(),
            tool_id: "call-1".into(),
            network_requested: false,
            email_preview: None,
            email_draft_ref: None,
        };
        assert!(reclassify_pending_approval(&state, &config, &approval).is_none());

        let arguments: serde_json::Value = serde_json::from_str(&approval.tool_args).unwrap();
        state
            .session_grants
            .lock()
            .unwrap()
            .add(permission::derive_session_grant("edit_file", &arguments).unwrap())
            .unwrap();
        let execution = reclassify_pending_approval(&state, &config, &approval).unwrap();
        assert!(execution.pre_resolved.is_none());
        for (id, old, new) in [("call-2", "new", "newer"), ("call-3", "newer", "newest")] {
            let later = PendingApproval {
                tool_id: id.into(),
                tool_args: serde_json::json!({
                    "path": path,
                    "old_string": old,
                    "new_string": new
                })
                .to_string(),
                ..approval.clone()
            };
            assert!(reclassify_pending_approval(&state, &config, &later).is_some());
        }
        let different_path = root.path().join("different.rs");
        std::fs::write(&different_path, "old\n").unwrap();
        let different = PendingApproval {
            tool_id: "call-4".into(),
            tool_args: serde_json::json!({
                "path": different_path,
                "old_string": "old",
                "new_string": "new"
            })
            .to_string(),
            ..approval.clone()
        };
        assert!(reclassify_pending_approval(&state, &config, &different).is_none());

        config.permission_rules.push(permission::PermissionRule {
            decision: permission::PermissionDecision::Ask,
            matcher: permission::PermissionMatcher::Path {
                tool: "edit_file".into(),
                path_pattern: format!("{}/**", root.path().display()),
            },
        });
        assert!(reclassify_pending_approval(&state, &config, &approval).is_none());

        config.permission_rules.clear();
        config.permission_rules.push(permission::PermissionRule {
            decision: permission::PermissionDecision::Deny,
            matcher: permission::PermissionMatcher::Path {
                tool: "edit_file".into(),
                path_pattern: format!("{}/**", root.path().display()),
            },
        });
        let denied = reclassify_pending_approval(&state, &config, &approval).unwrap();
        assert!(matches!(
            denied.pre_resolved,
            Some(crate::agent::registry::ToolExecutionResult::Denied(_))
        ));
    }

    #[test]
    fn modes_and_exact_current_run_grants_reclassify_compound_shell_without_widening() {
        let root = tempfile::tempdir().unwrap();
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.workspace = workspace::WorkspaceContext::discover(root.path()).unwrap();
        state.approval = ApprovalMode::RunEverything;
        let config = CaConfig::default();
        let arguments = serde_json::json!({
            "command":"cargo fmt --all --check && cargo build",
            "cwd":root.path(),
            "background":false,
            "network":false
        });
        let approval = PendingApproval {
            tool_name: "run_command".into(),
            tool_args: arguments.to_string(),
            tool_id: "call-shell".into(),
            network_requested: false,
            email_preview: None,
            email_draft_ref: None,
        };
        assert!(reclassify_pending_approval(&state, &config, &approval).is_some());
        let network_approval = PendingApproval {
            network_requested: true,
            ..approval.clone()
        };
        let network_execution =
            reclassify_pending_approval(&state, &config, &network_approval).unwrap();
        assert!(network_execution.network_allowed);
        state
            .session_grants
            .lock()
            .unwrap()
            .add(permission::derive_session_grant("run_command", &arguments).unwrap())
            .unwrap();
        assert!(reclassify_pending_approval(&state, &config, &approval).is_some());
        state.approval = ApprovalMode::Allowlist;
        assert!(reclassify_pending_approval(&state, &config, &approval).is_some());

        let mut other = approval.clone();
        other.tool_args = serde_json::json!({
            "command":"cargo fmt --all",
            "cwd":root.path(),
            "background":false,
            "network":false
        })
        .to_string();
        assert!(reclassify_pending_approval(&state, &config, &other).is_none());
    }

    #[test]
    fn interaction_answer_resolves_exact_call_once_without_user_message_or_draft_mutation() {
        let request =
            crate::interaction::InteractionRequest::from_legacy_question("Explain".into()).unwrap();
        let pending = crate::interaction::PendingInteraction::model("call-1".into(), request);
        let interaction_id = pending.id;
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.input = "composer draft".into();
        state.input_cursor = state.input.len();
        state.input_queue.enqueue("queued draft");
        state.kill_ring.push("keep me".into());
        state.messages.push(Message {
            role: Role::Assistant,
            content: String::new(),
            tool_calls: Some(vec![ToolCall {
                id: "call-1".into(),
                name: "request_user_input".into(),
                arguments: "{}".into(),
                status: ToolStatus::Running,
                output: None,
            }]),
            thinking: None,
            timestamp: chrono::Utc::now(),
            response_items: Vec::new(),
        });
        state.manual_resolutions.begin(vec![
            crate::interaction::PendingManualResolution::Interaction(pending.clone()),
        ]);
        let mut interaction = crate::interaction::InteractionState::from_pending(pending);
        interaction.handle_key(KeyCode::Char('o'), KeyModifiers::NONE);
        interaction.handle_key(KeyCode::Char('k'), KeyModifiers::NONE);
        let resolution = interaction
            .handle_key(KeyCode::Enter, KeyModifiers::NONE)
            .unwrap();

        assert!(apply_interaction_resolution(&mut state, resolution));
        let call = &state.messages[0].tool_calls.as_ref().unwrap()[0];
        assert_eq!(call.output.as_deref(), Some(r#"{"text":"ok"}"#));
        assert_eq!(call.status, ToolStatus::Done);
        assert_eq!(state.messages.len(), 1);
        assert!(!state
            .messages
            .iter()
            .any(|message| message.role == Role::User));
        assert_eq!(state.input, "composer draft");
        assert_eq!(state.input_queue.selected().unwrap().text, "queued draft");
        assert_eq!(state.kill_ring, ["keep me"]);

        let stale = crate::interaction::InteractionResolution {
            id: interaction_id,
            tool_call_id: Some("call-1".into()),
            outcome: crate::interaction::InteractionOutcome::Cancelled,
        };
        assert!(!apply_interaction_resolution(&mut state, stale));
        assert_eq!(
            state.messages[0].tool_calls.as_ref().unwrap()[0]
                .output
                .as_deref(),
            Some(r#"{"text":"ok"}"#)
        );
    }

    #[test]
    fn later_automatic_tool_waits_for_earlier_interaction_resolution() {
        let request =
            crate::interaction::InteractionRequest::from_legacy_question("Continue?".into())
                .unwrap();
        let pending = crate::interaction::PendingInteraction::model("call-1".into(), request);
        let interaction_id = pending.id;
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.turn_lifecycle.begin();
        state.manual_resolutions.begin(vec![
            crate::interaction::PendingManualResolution::Interaction(pending),
            crate::interaction::PendingManualResolution::Execution(
                crate::interaction::PendingExecution {
                    tool_name: "read_file".into(),
                    tool_args: r#"{"path":"Cargo.toml"}"#.into(),
                    tool_id: "call-2".into(),
                    network_allowed: false,
                    pre_resolved: None,
                },
            ),
        ]);
        let (tx, mut rx) = mpsc::unbounded_channel();
        let mut cancel_handle = None;

        activate_next_manual_resolution(&mut state, &CaConfig::default(), &tx, &mut cancel_handle);
        assert!(state.interaction.is_some());
        assert!(rx.try_recv().is_err());

        assert!(apply_interaction_resolution(
            &mut state,
            crate::interaction::InteractionResolution {
                id: interaction_id,
                tool_call_id: Some("call-1".into()),
                outcome: crate::interaction::InteractionOutcome::Cancelled,
            },
        ));
        activate_next_manual_resolution(&mut state, &CaConfig::default(), &tx, &mut cancel_handle);
        assert!(matches!(
            rx.try_recv().unwrap(),
            StreamMsg::ExecuteOrderedTool(execution, _) if execution.tool_id == "call-2"
        ));
        assert!(cancel_handle.is_none());
    }

    #[test]
    fn auto_review_runs_local_commands_and_owned_job_controls_without_reprompting() {
        for (name, arguments) in [
            ("run_command", serde_json::json!({"command":"cargo test"})),
            ("await_job", serde_json::json!({"job_id":"job-1"})),
            (
                "write_shell_stdin",
                serde_json::json!({"job_id":"job-1","input":"x"}),
            ),
            ("kill_job", serde_json::json!({"job_id":"job-1"})),
        ] {
            assert!(tool_needs_approval(
                name,
                &arguments,
                &ApprovalMode::Allowlist
            ));
            assert!(!tool_needs_approval(
                name,
                &arguments,
                &ApprovalMode::AutoReview
            ));
            assert!(!tool_needs_approval(
                name,
                &arguments,
                &ApprovalMode::RunEverything
            ));
        }
    }

    #[test]
    fn auto_review_runs_prepared_local_builtins_but_preserves_explicit_boundaries() {
        for (name, arguments) in [
            ("list_dir", serde_json::json!({"path":"."})),
            (
                "search_files",
                serde_json::json!({"path":".","pattern":"needle"}),
            ),
            ("read_file", serde_json::json!({"path":"Cargo.toml"})),
        ] {
            assert!(!tool_needs_approval(
                name,
                &arguments,
                &ApprovalMode::AutoReview,
            ));
        }
        assert!(!tool_needs_approval(
            "read_file",
            &serde_json::json!({"path":"Cargo.toml"}),
            &ApprovalMode::AutoReview,
        ));
        assert!(!tool_needs_approval(
            "run_command",
            &serde_json::json!({"command":"ps auxww | grep '[r]sync'"}),
            &ApprovalMode::AutoReview,
        ));
        assert!(!tool_needs_approval(
            "run_command",
            &serde_json::json!({"command":"find src -maxdepth 3 -type f | sort"}),
            &ApprovalMode::AutoReview,
        ));
        assert!(!tool_needs_approval(
            "spawn_agent",
            &serde_json::json!({"task":"inspect", "tools":["read_file", "list_dir"]}),
            &ApprovalMode::AutoReview,
        ));
        assert!(!tool_needs_approval(
            "spawn_agent",
            &serde_json::json!({"task":"edit", "tools":["write_file"]}),
            &ApprovalMode::AutoReview,
        ));
        assert!(tool_needs_approval(
            "spawn_agent",
            &serde_json::json!({"task":"inspect", "tools":["read_file"]}),
            &ApprovalMode::Allowlist,
        ));
        assert!(tool_needs_approval(
            "apply_automation_setup",
            &serde_json::json!({
                "draft": {
                    "template":"remote_automation",
                    "manifest_name":"seedbox",
                    "ssh_hosts":[{"name":"server","destination":"ops@example.test"}],
                    "transmission":[],
                    "syncs":[]
                },
                "accepted_plan_digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
            }),
            &ApprovalMode::AutoReview,
        ));
        for command in ["cargo test", "cat Cargo.toml > copy"] {
            assert!(!tool_needs_approval(
                "run_command",
                &serde_json::json!({"command":command}),
                &ApprovalMode::AutoReview,
            ));
        }
        assert!(!tool_needs_approval(
            "write_file",
            &serde_json::json!({"path":"copy", "content":"ok"}),
            &ApprovalMode::AutoReview,
        ));
        assert!(!tool_needs_approval(
            "activate_skill",
            &serde_json::json!({"id":"skill"}),
            &ApprovalMode::AutoReview,
        ));
        for (name, arguments) in [
            ("browser", serde_json::json!({"action":"start"})),
            ("missing", serde_json::json!({})),
        ] {
            assert!(tool_needs_approval(
                name,
                &arguments,
                &ApprovalMode::AutoReview,
            ));
        }
        assert!(tool_needs_approval(
            "run_command",
            &serde_json::json!({"command":"rg needle src"}),
            &ApprovalMode::Allowlist,
        ));
    }

    #[test]
    fn auto_review_command_persists_strict_and_safe_modes_but_bare_is_process_only() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("config.toml");
        std::fs::write(&path, "[agent]\napproval_mode = \"auto-review\"\n").unwrap();
        let store = ConfigStore::new(&path);
        let config = store.load().unwrap();
        let sessions = session::SessionStore::new(temp.path().join("sessions"));
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.approval = ApprovalMode::AutoReview;

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::AutoReview,
                args: String::new(),
            },
            &sessions,
            &config,
            &store,
        );
        assert_eq!(state.approval, ApprovalMode::Allowlist);
        assert_eq!(store.load().unwrap().agent.approval_mode, "ask");

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::AutoReview,
                args: String::new(),
            },
            &sessions,
            &config,
            &store,
        );
        assert_eq!(state.approval, ApprovalMode::AutoReview);
        assert_eq!(store.load().unwrap().agent.approval_mode, "auto-review");

        let bare_path = temp.path().join("bare.toml");
        std::fs::write(&bare_path, "[agent]\napproval_mode = \"ask\"\n").unwrap();
        let bare_store = ConfigStore::for_profile(&bare_path, runtime::ActiveProfile::Bare);
        let bare_config = bare_store.load().unwrap();
        let mut bare_state = AppState::new(context::ShellHistory::in_memory());
        bare_state.run_capabilities.config_writes = true;
        bare_state.approval = ApprovalMode::AutoReview;
        execute_command_action(
            &mut bare_state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::AutoReview,
                args: String::new(),
            },
            &sessions,
            &bare_config,
            &bare_store,
        );
        assert_eq!(bare_state.approval, ApprovalMode::AutoReview);
        assert!(bare_state
            .status_message
            .as_deref()
            .is_some_and(|message| message.starts_with("Could not save approval mode:")));

        bare_state.run_capabilities.config_writes = false;
        bare_state.approval = ApprovalMode::Allowlist;
        execute_command_action(
            &mut bare_state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::AutoReview,
                args: String::new(),
            },
            &sessions,
            &bare_config,
            &bare_store,
        );
        assert_eq!(bare_state.approval, ApprovalMode::AutoReview);
        assert_eq!(
            std::fs::read_to_string(bare_path).unwrap(),
            "[agent]\napproval_mode = \"ask\"\n"
        );
    }

    #[test]
    fn direct_shell_prefixes_select_foreground_silent_and_background_modes() {
        assert_eq!(
            parse_direct_shell_input("! cargo test"),
            Some(DirectShellInput {
                command: "cargo test".into(),
                silent: false,
                background: false,
                network: false,
            })
        );
        assert_eq!(
            parse_direct_shell_input("!!printf quiet"),
            Some(DirectShellInput {
                command: "printf quiet".into(),
                silent: true,
                background: false,
                network: false,
            })
        );
        assert_eq!(
            parse_direct_shell_input("!& sleep 1"),
            Some(DirectShellInput {
                command: "sleep 1".into(),
                silent: false,
                background: true,
                network: false,
            })
        );
        assert_eq!(
            parse_direct_shell_input("! --network curl localhost"),
            Some(DirectShellInput {
                command: "curl localhost".into(),
                silent: false,
                background: false,
                network: true,
            })
        );
        assert_eq!(parse_direct_shell_input("!  "), None);
    }

    #[test]
    fn foreground_promotion_requires_same_job_second_key_within_window() {
        let first = jobs::JobId::new();
        let second = jobs::JobId::new();
        let start = std::time::Instant::now();
        let mut armed = None;
        assert!(!confirm_foreground_promotion(&mut armed, first, start));
        assert!(!confirm_foreground_promotion(
            &mut armed,
            second,
            start + std::time::Duration::from_millis(500)
        ));
        assert!(confirm_foreground_promotion(
            &mut armed,
            second,
            start + std::time::Duration::from_millis(1_000)
        ));
        assert!(armed.is_none());
        assert!(!confirm_foreground_promotion(&mut armed, first, start));
        assert!(!confirm_foreground_promotion(
            &mut armed,
            first,
            start + std::time::Duration::from_millis(1_501)
        ));
    }

    #[test]
    fn session_delete_result_preserves_filter_and_clamps_visible_selection() {
        let deleted_id = uuid::Uuid::new_v4();
        let remaining_id = uuid::Uuid::new_v4();
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.session_picker_open = true;
        state.session_filter = "keep".into();
        state.selected_session_idx = 1;
        state.session_delete_confirmation = Some(crate::app::SessionDeleteConfirmation {
            storage_key: "deleted".into(),
            session_id: deleted_id,
            title: "Keep deleted".into(),
            archived: false,
            delete_selected: true,
            busy: true,
            error: None,
        });
        let remaining = session::SessionSummary {
            storage_key: "remaining".into(),
            id: remaining_id,
            title: "Keep remaining".into(),
            pinned: false,
            workspace: "/workspace".into(),
            updated_at: chrono::Utc::now(),
        };

        apply_session_delete_result(
            &mut state,
            SessionDeleteTaskResult {
                storage_key: "deleted".into(),
                expected_id: deleted_id,
                outcome: SessionDeleteOutcome::Deleted {
                    archived: false,
                    refreshed: Ok(vec![remaining.clone()]),
                },
            },
        );

        assert_eq!(state.session_filter, "keep");
        assert_eq!(state.selected_session_idx, 0);
        assert_eq!(state.session_list, vec![remaining]);
        assert!(state.session_picker_open);
        assert!(state.session_delete_confirmation.is_none());
        assert_eq!(state.status_message.as_deref(), Some("Session purged"));
    }

