    #[test]
    fn session_delete_failure_keeps_confirmation_and_defaults_back_to_cancel() {
        let id = uuid::Uuid::new_v4();
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.session_picker_open = true;
        state.session_filter = "saved".into();
        state.selected_session_idx = 2;
        state.session_delete_confirmation = Some(crate::app::SessionDeleteConfirmation {
            storage_key: "saved".into(),
            session_id: id,
            title: "Saved".into(),
            archived: false,
            delete_selected: true,
            busy: true,
            error: None,
        });

        apply_session_delete_result(
            &mut state,
            SessionDeleteTaskResult {
                storage_key: "saved".into(),
                expected_id: id,
                outcome: SessionDeleteOutcome::Failed("Session deletion failed: denied".into()),
            },
        );

        let confirmation = state.session_delete_confirmation.unwrap();
        assert!(!confirmation.busy);
        assert!(!confirmation.delete_selected);
        assert_eq!(
            confirmation.error.as_deref(),
            Some("Session deletion failed: denied")
        );
        assert_eq!(state.session_filter, "saved");
        assert_eq!(state.selected_session_idx, 2);
    }

