    async fn read_test_http_request(stream: &mut tokio::net::TcpStream) -> Vec<u8> {
        let mut request = Vec::new();
        let mut buffer = [0_u8; 4096];
        let mut required = None;
        loop {
            let read = stream.read(&mut buffer).await.unwrap();
            if read == 0 {
                break;
            }
            request.extend_from_slice(&buffer[..read]);
            if required.is_none() {
                if let Some(header_end) = request.windows(4).position(|bytes| bytes == b"\r\n\r\n")
                {
                    let headers = String::from_utf8_lossy(&request[..header_end]);
                    let content_length = headers
                        .lines()
                        .find_map(|line| {
                            let (name, value) = line.split_once(':')?;
                            name.eq_ignore_ascii_case("content-length")
                                .then(|| value.trim().parse::<usize>().ok())
                                .flatten()
                        })
                        .unwrap_or(0);
                    required = Some(header_end + 4 + content_length);
                }
            }
            if required.is_some_and(|required| request.len() >= required) {
                break;
            }
            assert!(request.len() < 256 * 1024, "test request exceeded bound");
        }
        request
    }

    async fn btw_one_shot_server(
        status: &str,
        body: Vec<u8>,
    ) -> (String, tokio::task::JoinHandle<Vec<u8>>) {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let status = status.to_string();
        let server = tokio::spawn(async move {
            let (mut stream, _) = listener.accept().await.unwrap();
            let request = read_test_http_request(&mut stream).await;
            let headers = format!(
                "HTTP/1.1 {status}\r\nContent-Type: text/event-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                body.len()
            );
            stream.write_all(headers.as_bytes()).await.unwrap();
            stream.write_all(&body).await.unwrap();
            request
        });
        (format!("http://{address}/v1"), server)
    }

    fn finish_failed_recovery_turn(
        state: &mut AppState,
        store: &session::SessionStore,
        tx: &mpsc::UnboundedSender<StreamMsg>,
        handle: &mut Option<tokio::task::JoinHandle<()>>,
    ) {
        state.turn_recovery.pending = true;
        let completion = state.turn_lifecycle.take_completion().unwrap();
        let changed = record_turn_completion_annotation(state, completion);
        restore_one_turn_route_after(state, completion.outcome);
        persist_completed_turn(state, store, changed, completion.outcome, tx, handle);
    }

