        let store = session::SessionStore::new(temp.path().join("sessions"));
        state.cwd = temp.path().to_string_lossy().into_owned();
        state
            .turn_recovery
            .context
            .as_mut()
            .unwrap()
            .effects_started = false;
        let source_id = save_current_session(&mut state, &store).unwrap();
        state.session_writer = Some(store.try_writer_lease(source_id).unwrap());
        let error = agent::stream::ProviderError::PrematureEof;
        assert!(reserve_turn_replacement(&mut state, &error));
        apply_stream_failure(&mut state, "frozen-provider", &error);
