    #[tokio::test]
    async fn bug257_replacement_preserves_source_and_frozen_request_once() {
        let partial = b"data: {\"choices\":[{\"delta\":{\"content\":\"partial answer\",\"reasoning_content\":\"partial thought\"},\"finish_reason\":null}]}\n\n".to_vec();
        let (base_url, server) = test_provider_sequence(vec![
            ("200 OK", partial),
            ("200 OK", btw_complete_stream("replacement answer")),
        ])
        .await;
        let (mut state, config) = btw_state_and_config(base_url);
        let temp = tempfile::tempdir().unwrap();
        let store = session::SessionStore::new(temp.path().join("sessions"));
        state.cwd = temp.path().to_string_lossy().into_owned();
        state.messages.truncate(1);
        state.messages[0].content = "frozen user request".into();
        state.streaming = None;
        state.pasted_images.clear();
        state.btw = None;
        state.input_queue = Default::default();
        state.turn_lifecycle.reset();
        state.pending_attachment_context = Some("frozen attachment marker".into());
        state.active_profile = runtime::ActiveProfile::Bare;
        // Explicit disposable persistence: exercise both durable branches, never real runtime state.
        let (tx, mut rx) = mpsc::unbounded_channel();
        let mut handle = None;
        start_llm_turn(&mut state, &config, &tx, &mut handle);
        let source_id = state.current_session.as_ref().unwrap().id;
        handle.take().unwrap().await.unwrap();
        let mut failed = None;
        while let Ok(message) = rx.try_recv() {
            match message {
                StreamMsg::RecoveryPrepared(frozen, generation) => {
                    capture_recovery_request(&mut state, *frozen, generation)
                }
                StreamMsg::Delta(delta, _) => handle_stream_delta(&mut state, delta),
                StreamMsg::Error { error, .. } => failed = Some(error),
                _ => {}
            }
        }
        let error = failed.expect("partial stream must fail");
        assert!(reserve_turn_replacement(&mut state, &error));
        apply_stream_failure(&mut state, "local", &error);
        assert!(state
            .turn_recovery
            .notice
            .as_ref()
            .unwrap()
            .contains("stream ended early"));
        finish_failed_recovery_turn(&mut state, &store, &tx, &mut handle);
        handle.take().unwrap().await.unwrap();
        let branch = loop {
            match rx.recv().await.unwrap() {
                StreamMsg::RecoveryBranchReady(result, _) => break (*result).unwrap(),
                StreamMsg::RecoveryTurnRetired {
                    session_id,
                    turn_id,
                    warning,
                } => {
                    assert_eq!(session_id, Some(source_id));
                    assert!(warning.is_none());
                    save_current_session(&mut state, &store).unwrap();
                    apply_recovery_retirement(&mut state, session_id, turn_id, warning);
                }
                _ => panic!("expected retirement or recovery branch"),
            }
        };
        start_frozen_replacement(&mut state, branch, &tx, &mut handle);
        assert_ne!(state.current_session.as_ref().unwrap().id, source_id);
        assert_eq!(state.messages.len(), 1);
        assert_eq!(
            state.active_attachment_context.as_deref(),
            Some("frozen attachment marker")
        );
        handle.take().unwrap().await.unwrap();
        let requests = tokio::time::timeout(std::time::Duration::from_secs(2), server)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(requests.len(), 2);
        fn body(request: &[u8]) -> serde_json::Value {
            let split = request
                .windows(4)
                .position(|bytes| bytes == b"\r\n\r\n")
                .unwrap()
                + 4;
            serde_json::from_slice(&request[split..]).unwrap()
        }
        assert_eq!(
            body(&requests[0]),
            body(&requests[1]),
            "replacement must not rebuild attachments, tools or prompts"
        );
        let saved = store.load(&source_id.to_string()).unwrap();
        assert!(saved
            .messages
            .iter()
            .any(|message| message.content == "partial answer"));
        assert!(!state
            .messages
            .iter()
            .any(|message| message.content == "partial answer"));
        assert!(!reserve_turn_replacement(
            &mut state,
            &agent::stream::ProviderError::PrematureEof
        ));
        assert_eq!(state.turn_recovery.context.as_ref().unwrap().attempt, 1);
    }

