    #[tokio::test]
    async fn btw_failure_is_safe_and_cancelled_task_closes_usage_once() {
        let marker = "RESPONSE-BODY-MUST-NOT-ESCAPE";
        let (base_url, captured) =
            btw_one_shot_server("401 Unauthorized", marker.as_bytes().to_vec()).await;
        let (mut failed_state, config) = btw_state_and_config(base_url);
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        let handle = start_btw(&mut failed_state, &config, &tx).unwrap();
        let failure = loop {
            match tokio::time::timeout(std::time::Duration::from_secs(2), rx.recv())
                .await
                .unwrap()
                .unwrap()
            {
                StreamMsg::BtwFailed(error, generation) => {
                    assert!(apply_btw_stream_update(
                        &mut failed_state,
                        BtwStreamUpdate::Failed(error.clone()),
                        generation
                    ));
                    break error;
                }
                StreamMsg::BtwDelta(_, _) => {}
                _ => panic!("unexpected BTW event"),
            }
        };
        handle.await.unwrap();
        captured.await.unwrap();
        assert!(failure.contains("Authentication rejected for local"));
        assert!(!failure.contains(marker));
        assert_eq!(
            failed_state.usage_ledger.lock().unwrap().snapshot().records[0].outcome,
            usage::UsageOutcome::Failed
        );

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let base_url = format!("http://{}/v1", listener.local_addr().unwrap());
        let (accepted_tx, accepted_rx) = tokio::sync::oneshot::channel();
        let server = tokio::spawn(async move {
            let (_stream, _) = listener.accept().await.unwrap();
            let _ = accepted_tx.send(());
            tokio::time::sleep(std::time::Duration::from_secs(30)).await;
        });
        let (mut cancelled_state, config) = btw_state_and_config(base_url);
        let (tx, _rx) = tokio::sync::mpsc::unbounded_channel();
        let task = start_btw(&mut cancelled_state, &config, &tx).unwrap();
        accepted_rx.await.unwrap();
        task.abort();
        assert!(task.await.unwrap_err().is_cancelled());
        tokio::task::yield_now().await;
        server.abort();
        let records = cancelled_state
            .usage_ledger
            .lock()
            .unwrap()
            .snapshot()
            .records;
        assert_eq!(records.len(), 1);
        assert_eq!(records[0].outcome, usage::UsageOutcome::Cancelled);
    }

    #[test]
    fn btw_stream_updates_reject_stale_closed_and_non_running_generations() {
        let mut state = AppState::new(context::ShellHistory::in_memory());
        tui::input::open_btw(&mut state, "question".into(), "safe".into(), "model".into());
        let generation = state.btw.as_ref().unwrap().generation;

        assert!(!apply_btw_stream_update(
            &mut state,
            BtwStreamUpdate::Delta("stale".into()),
            generation.wrapping_add(1)
        ));
        assert!(state.btw.as_ref().unwrap().answer.is_empty());
        assert!(apply_btw_stream_update(
            &mut state,
            BtwStreamUpdate::Delta("current".into()),
            generation
        ));
        assert!(apply_btw_stream_update(
            &mut state,
            BtwStreamUpdate::Finished,
            generation
        ));
        assert!(!apply_btw_stream_update(
            &mut state,
            BtwStreamUpdate::Delta("late".into()),
            generation
        ));
        assert_eq!(state.btw.as_ref().unwrap().answer, "current");
        state.btw = None;
        assert!(!apply_btw_stream_update(
            &mut state,
            BtwStreamUpdate::Finished,
            generation
        ));
    }

    #[test]
    fn submitted_image_history_keeps_only_an_unavailable_safe_marker() {
        let image = crate::image_content::normalize_rgba(1, 1, vec![2, 4, 6, 255]).unwrap();
        let content =
            user_content_with_image_markers("inspect".into(), std::slice::from_ref(&image));
        assert!(content.contains("image/png 1×1"));
        assert!(content.contains("unavailable after this process"));
        assert!(!content.contains(&image.base64()));

        let message = Message {
            role: Role::User,
            content,
            tool_calls: None,
            thinking: None,
            timestamp: chrono::Utc::now(),
            response_items: Vec::new(),
        };
        let persisted = serde_json::to_string(&message).unwrap();
        assert!(persisted.contains("unavailable after this process"));
        assert!(!persisted.contains(&image.base64()));
    }

