    #[tokio::test]
    async fn lifecycle_hook_continuation_retry_preserves_exact_parent() {
        let temporary = tempfile::tempdir().unwrap();
        let root = temporary.path().canonicalize().unwrap();
        let log = root.join("child-hooks.log");
        let manager = agent::subagent::AgentManager::new(
            Arc::new(GraphWorkspaceRunner {
                roots: Arc::new(Mutex::new(Vec::new())),
            }),
            agent::subagent::AgentLimits::default(),
        );
        let runner = hooks::HookRunner::new(
            vec![config::HookConfig {
                event: "subagent_start".into(),
                command: format!("printf 'started\\n' >> '{}'", log.display()),
                enabled: true,
                timeout_secs: 5,
                fail_closed: true,
            }],
            sandbox::SandboxMode::PolicyOnly,
        );
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.cwd = root.display().to_string();
        state.workspace = workspace::WorkspaceContext::discover(&root).unwrap();
        state.agents = Some(manager.clone());
        state.hook_runner = Some(runner);
        state.messages = vec![
            Message {
                role: Role::User,
                content: "continue safely".into(),
                tool_calls: None,
                thinking: None,
                timestamp: chrono::Utc::now(),
                response_items: Vec::new(),
            },
            Message {
                role: Role::Assistant,
                content: String::new(),
                tool_calls: Some(vec![ToolCall {
                    id: "read".into(),
                    name: "read_file".into(),
                    arguments: "{}".into(),
                    status: ToolStatus::Done,
                    output: Some("observed".into()),
                }]),
                thinking: None,
                timestamp: chrono::Utc::now(),
                response_items: Vec::new(),
            },
        ];
        begin_interactive_parent_task(&mut state);
        let owner = state.active_agent_turn_id.unwrap();
        state.turn_lifecycle.begin();
        bind_interactive_child_lifecycle_hooks(&state).unwrap();
        state.retry_boundary = Some(RetryBoundary::continuation(0, 2));
        prepare_retry_branch(
            &mut state,
            &session::SessionStore::new(root.join("sessions")),
        )
        .unwrap();
        assert_eq!(state.active_agent_turn_id, Some(owner));
        assert_eq!(manager.current_parent_turn(), owner);
        bind_interactive_child_lifecycle_hooks(&state).unwrap();
        let child = manager
            .spawn(agent::subagent::AgentSpawnRequest {
                parent: None,
                parent_turn: owner,
                task_id: None,
                task: "read fixture".into(),
                context_mode: agent::subagent::AgentContextMode::Summary,
                context_summary: "read-only".into(),
                grants: agent::subagent::AgentGrant {
                    tools: vec!["read_file".into()],
                    workspace_root_ids: state
                        .workspace
                        .roots()
                        .iter()
                        .map(|root| root.id.to_string())
                        .collect(),
                    path_scopes: Vec::new(),
                    command_scopes: Vec::new(),
                    network: false,
                },
                workspace: state.workspace.clone(),
                depth: 1,
                route: None,
                purpose: agent::subagent::AgentRunPurpose::Subagent,
                output_contract: None,
                isolation: agent::subagent::AgentIsolation::Shared,
            })
            .await
            .unwrap();
        let result = manager.await_agent_bounded(child, Some(5)).await.unwrap();
        assert_eq!(result.status, agent::subagent::AgentStatus::Completed);
        assert_eq!(std::fs::read_to_string(log).unwrap(), "started\n");
        state.active_agent_turn_id = None;
        assert!(bind_interactive_child_lifecycle_hooks(&state).is_err());
        assert_eq!(manager.current_parent_turn(), owner);
    }

