    struct MultiRunTestRunner {
        requests: Arc<Mutex<Vec<(String, std::path::PathBuf, agent::subagent::AgentRoute)>>>,
    }

    fn multi_run_structured_stream(name: &str, arguments: serde_json::Value) -> Vec<u8> {
        let delta = serde_json::json!({
            "choices": [{
                "delta": {"tool_calls": [{
                    "index": 0,
                    "id": format!("{name}-call"),
                    "function": {"name": name, "arguments": arguments.to_string()}
                }]},
                "finish_reason": null
            }]
        });
        let finish = serde_json::json!({
            "choices": [{"delta": {}, "finish_reason": "tool_calls"}],
            "usage": {"prompt_tokens": 20, "completion_tokens": 5, "total_tokens": 25}
        });
        format!("data: {delta}\n\ndata: {finish}\n\ndata: [DONE]\n\n").into_bytes()
    }

    fn test_http_json(request: &[u8]) -> serde_json::Value {
        let header_end = request
            .windows(4)
            .position(|bytes| bytes == b"\r\n\r\n")
            .expect("HTTP headers");
        serde_json::from_slice(&request[header_end + 4..]).expect("JSON request body")
    }

    fn init_walkthrough_repository() -> tempfile::TempDir {
        let root = tempfile::tempdir().unwrap();
        let run = |args: &[&str]| {
            let status = std::process::Command::new("git")
                .args(args)
                .current_dir(root.path())
                .status()
                .unwrap();
            assert!(status.success(), "git failed: {args:?}");
        };
        run(&["init", "-q"]);
        std::fs::write(root.path().join("lib.rs"), "pub fn value() -> u8 { 1 }\n").unwrap();
        run(&["add", "."]);
        run(&[
            "-c",
            "user.name=Test",
            "-c",
            "user.email=test@example.com",
            "commit",
            "-qm",
            "base",
        ]);
        std::fs::write(root.path().join("lib.rs"), "pub fn value() -> u8 { 2 }\n").unwrap();
        root
    }

    fn open_test_walkthrough(state: &mut AppState) {
        state.change_walkthrough_generation = 1;
        state.change_walkthrough = Some(change_walkthrough::ChangeWalkthroughState {
            target: changes::ReviewTarget::Working,
            provider: "local".into(),
            model: "side-model".into(),
            status: change_walkthrough::ChangeWalkthroughStatus::Capturing,
            source_hash: None,
            included_files: Vec::new(),
            refusal: None,
            result: None,
            error: None,
            freshness_error: None,
            scroll: 0,
            generation: 1,
        });
    }

    #[tokio::test]
    async fn walkthrough_task_is_isolated_and_stale_monitor_detects_exact_source_change() {
        let report = serde_json::json!({
            "summary":"The function now returns the new value.",
            "steps":[{"order":1,"title":"Update value","files":["lib.rs"],"explanation":"The return literal changes from one to two."}],
            "notes":[]
        });
        let (base_url, server) = btw_one_shot_server(
            "200 OK",
            multi_run_structured_stream("submit_change_walkthrough", report),
        )
        .await;
        let (mut state, config) = btw_state_and_config(base_url);
        let root = init_walkthrough_repository();
        state.cwd = root.path().to_string_lossy().into_owned();
        state.messages = vec![Message {
            role: Role::User,
            content: "CANONICAL-CHAT-MUST-NOT-LEAK".into(),
            tool_calls: None,
            thinking: None,
            timestamp: chrono::Utc::now(),
            response_items: Vec::new(),
        }];
        open_test_walkthrough(&mut state);
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        let task = start_change_walkthrough(&mut state, &config, &tx).unwrap();

        let (source_hash, result) = loop {
            match rx.recv().await.unwrap() {
                StreamMsg::ChangeWalkthroughPrepared {
                    source_hash,
                    included_files,
                    generation,
                } => {
                    assert_eq!(generation, 1);
                    assert_eq!(included_files, ["lib.rs"]);
                    assert_eq!(source_hash.len(), 64);
                }
                StreamMsg::ChangeWalkthroughFinished(task_result) => {
                    let ChangeWalkthroughTaskOutcome::Complete {
                        source_hash,
                        included_files,
                        result,
                    } = task_result.outcome
                    else {
                        panic!("expected complete walkthrough")
                    };
                    assert_eq!(included_files, ["lib.rs"]);
                    break (source_hash, result);
                }
                _ => panic!("unexpected walkthrough event"),
            }
        };
        task.await.unwrap();
        assert_eq!(result.steps[0].files, ["lib.rs"]);

        let request = server.await.unwrap();
        let payload = test_http_json(&request);
        assert_eq!(payload["messages"].as_array().unwrap().len(), 2);
        assert_eq!(payload["tools"].as_array().unwrap().len(), 1);
        assert_eq!(
            payload["tools"][0]["function"]["name"],
            "submit_change_walkthrough"
        );
        let serialized = payload.to_string();
        assert!(serialized.contains(&source_hash));
        assert!(serialized.contains("lib.rs"));
        assert!(!serialized.contains("CANONICAL-CHAT-MUST-NOT-LEAK"));
        assert!(!String::from_utf8_lossy(&request).contains("Authorization:"));

        std::fs::write(root.path().join("lib.rs"), "pub fn value() -> u8 { 3 }\n").unwrap();
        let monitor = start_change_walkthrough_stale_monitor(
            root.path().to_string_lossy().into_owned(),
            changes::ReviewTarget::Working,
            source_hash,
            1,
            &tx,
        );
        match tokio::time::timeout(std::time::Duration::from_secs(3), rx.recv())
            .await
            .unwrap()
            .unwrap()
        {
            StreamMsg::ChangeWalkthroughStale {
                result: Ok(true),
                generation: 1,
            } => {}
            _ => panic!("expected exact-source stale event"),
        }
        monitor.await.unwrap();
    }

    #[tokio::test]
    async fn incomplete_walkthrough_finishes_without_provider_traffic() {
        let (mut state, mut config) = btw_state_and_config("http://127.0.0.1:9/v1".into());
        let root = init_walkthrough_repository();
        std::fs::write(root.path().join("untracked.txt"), "not sent\n").unwrap();
        state.cwd = root.path().to_string_lossy().into_owned();
        config.providers.get_mut("local").unwrap().base_url = "http://127.0.0.1:9/v1".into();
        open_test_walkthrough(&mut state);
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        let task = start_change_walkthrough(&mut state, &config, &tx).unwrap();
        match rx.recv().await.unwrap() {
            StreamMsg::ChangeWalkthroughFinished(task_result) => {
                let ChangeWalkthroughTaskOutcome::Refused(refusal) = task_result.outcome else {
                    panic!("expected local refusal")
                };
                assert_eq!(refusal.untracked_files, ["untracked.txt"]);
            }
            _ => panic!("incomplete input must not enter generating state"),
        }
        task.await.unwrap();
    }

    #[async_trait::async_trait]
    impl agent::subagent::AgentRunner for MultiRunTestRunner {
        async fn run(&self, context: agent::subagent::AgentRunContext) -> Result<String, String> {
            let root = context
                .request
                .workspace
                .primary()
                .expect("candidate root")
                .path
                .clone();
            let route = context.request.route.expect("candidate route");
            self.requests
                .lock()
                .unwrap()
                .push((context.request.task.clone(), root.clone(), route));
            Ok(format!("completed in {}", root.display()))
        }
    }

    #[tokio::test]
    async fn multi_run_start_uses_same_request_and_distinct_owned_worktrees_without_attaching() {
        let temp = tempfile::tempdir().unwrap();
        let repository = temp.path().join("repository");
        std::fs::create_dir_all(&repository).unwrap();
        for arguments in [
            vec!["init", "-q"],
            vec!["config", "user.name", "ca test"],
            vec!["config", "user.email", "ca-test@example.invalid"],
        ] {
            assert!(std::process::Command::new("git")
                .args(arguments)
                .current_dir(&repository)
                .status()
                .unwrap()
                .success());
        }
        std::fs::write(repository.join("README.md"), "unchanged main\n").unwrap();
        assert!(std::process::Command::new("git")
            .args(["add", "README.md"])
            .current_dir(&repository)
            .status()
            .unwrap()
            .success());
        assert!(std::process::Command::new("git")
            .args(["commit", "-qm", "initial"])
            .current_dir(&repository)
            .status()
            .unwrap()
            .success());

        let current = ModelInfo {
            provider: "alpha".into(),
            id: "one".into(),
            display_name: "one".into(),
        };
        let other = ModelInfo {
            provider: "beta".into(),
            id: "two".into(),
            display_name: "two".into(),
        };
        let definition = crate::multi_run::MultiRunDefinition::build(
            "implement the exact same task",
            2,
            Some(&current),
            &[current.clone(), other],
        )
        .unwrap();
        let run = crate::multi_run::MultiRunState::preview(definition, "frozen context".into());
        let store = worktree::WorktreeStore::new(temp.path().join("profile-worktrees"), true);
        let requests = Arc::new(Mutex::new(Vec::new()));
        let manager = agent::subagent::AgentManager::new(
            Arc::new(MultiRunTestRunner {
                requests: requests.clone(),
            }),
            agent::subagent::AgentLimits {
                max_concurrent: 2,
                max_children_per_turn: 5,
                ..agent::subagent::AgentLimits::default()
            },
        );

        let started =
            perform_multi_run_start(run, store.clone(), repository.clone(), manager.clone())
                .await
                .unwrap();
        assert_eq!(started.status, crate::multi_run::MultiRunStatus::Running);
        for candidate in &started.candidates {
            manager
                .await_agent(candidate.agent_id.unwrap())
                .await
                .unwrap();
        }
        let refreshed = perform_multi_run_refresh(started, manager, store.clone())
            .await
            .unwrap();
        assert_eq!(
            refreshed.status,
            crate::multi_run::MultiRunStatus::ReadyToJudge
        );
        assert!(refreshed
            .candidates
            .iter()
            .all(|candidate| candidate.evidence.is_some()));
        {
            let requests = requests.lock().unwrap();
            assert_eq!(requests.len(), 2);
            assert!(requests
                .iter()
                .all(|(task, _, _)| task == "implement the exact same task"));
            assert_ne!(requests[0].1, requests[1].1);
            assert_ne!(requests[0].2, requests[1].2);
            assert!(requests
                .iter()
                .all(|(_, root, _)| root != &repository.canonicalize().unwrap()));
        }
        assert_eq!(store.records().unwrap().len(), 2);
        assert_eq!(
            std::fs::read_to_string(repository.join("README.md")).unwrap(),
            "unchanged main\n"
        );
        let (base_url, provider_requests) = test_provider_sequence(vec![
            (
                "200 OK",
                multi_run_structured_stream(
                    "report_multi_run_judgment",
                    serde_json::json!({
                        "winner": 2,
                        "rationale": "Candidate 2 is the better evidence-backed result"
                    }),
                ),
            ),
            (
                "200 OK",
                multi_run_structured_stream(
                    "report_multi_run_fusion",
                    serde_json::json!({
                        "source": 2,
                        "plan": "Inspect candidate 2 and integrate it explicitly"
                    }),
                ),
            ),
        ])
        .await;
        let request_store = crate::request::RequestStore::default();
        let client = agent::AgentClient::with_request_store(
            "judge-provider",
            &config::ProviderConfig {
                google: None,
                tool_schema_policy: Default::default(),
                base_url,
                api_key: String::new(),
                protocol: agent::ProviderProtocol::ChatCompletions,
                prompt_cache_mode: crate::config::PromptCacheMode::Implicit,
                models: vec!["judge-model".into()],
                timeout: config::ProviderTimeoutConfig::default(),
            },
            "judge-model",
            request_store.clone(),
        );
        let ledger = Arc::new(Mutex::new(usage::UsageLedger::default()));
        let judged = perform_multi_run_judge(
            refreshed,
            store.clone(),
            client.clone(),
            usage::UsageRecorder::new(
                ledger.clone(),
                usage::UsageKind::MultiRunJudge,
                "judge-provider",
                "judge-model",
            ),
        )
        .await
        .unwrap();
        assert_eq!(judged.status, crate::multi_run::MultiRunStatus::Judged);
        assert_eq!(
            judged.judgment.as_ref().unwrap().winner,
            crate::multi_run::CandidateId(2)
        );
        let fused = perform_multi_run_fusion(
            judged,
            store,
            client,
            usage::UsageRecorder::new(
                ledger.clone(),
                usage::UsageKind::MultiRunFusion,
                "judge-provider",
                "judge-model",
            ),
        )
        .await
        .unwrap();
        assert_eq!(fused.status, crate::multi_run::MultiRunStatus::Complete);
        assert_eq!(
            fused.fusion.as_ref().unwrap().source,
            crate::multi_run::CandidateId(2)
        );

        let provider_requests = provider_requests.await.unwrap();
        assert_eq!(provider_requests.len(), 2);
        for (request, expected) in provider_requests
            .iter()
            .zip(["report_multi_run_judgment", "report_multi_run_fusion"])
        {
            let body = test_http_json(request);
            let tools = body["tools"].as_array().expect("one structured schema");
            assert_eq!(tools.len(), 1);
            assert_eq!(tools[0]["function"]["name"], expected);
            let serialized = body.to_string();
            assert!(!serialized.contains("read_file"));
            assert!(!serialized.contains("run_command"));
            assert!(!serialized.contains("apply_patch"));
        }
        let usage = ledger.lock().unwrap().snapshot();
        assert_eq!(usage.records.len(), 2);
        assert_eq!(usage.records[0].kind, usage::UsageKind::MultiRunJudge);
        assert_eq!(usage.records[1].kind, usage::UsageKind::MultiRunFusion);
        assert!(usage
            .records
            .iter()
            .all(|record| record.outcome == usage::UsageOutcome::Completed));
        assert_eq!(
            request_store.snapshot().unwrap().kind,
            crate::request::RequestKind::MultiRunFusion
        );
    }

    #[test]
    fn paged_session_history_prepends_in_order_and_blocks_partial_save() {
        let temp = tempfile::tempdir().unwrap();
        let store = session::SessionStore::new(temp.path());
        let mut state = AppState::new(context::ShellHistory::in_memory());
        let recent = vec![
            Message {
                role: Role::User,
                content: "recent user".into(),
                tool_calls: None,
                thinking: None,
                timestamp: chrono::DateTime::from_timestamp(3, 0).unwrap(),
                response_items: Vec::new(),
            },
            Message {
                role: Role::Assistant,
                content: "recent answer".into(),
                tool_calls: None,
                thinking: None,
                timestamp: chrono::DateTime::from_timestamp(4, 0).unwrap(),
                response_items: Vec::new(),
            },
        ];
        let session =
            session::SessionV2::new("Paged", "/workspace", "local", "coder", recent.clone());
        let id = session.id;
        state.messages = recent;
        state.current_session = Some(session);
        state.session_history = Some(crate::app::SessionHistoryState {
            storage_key: id.to_string(),
            session_id: id,
            storage_generation: uuid::Uuid::nil(),
            start_index: 2,
            total_messages: 4,
            busy: true,
            request_older: false,
            request_full: false,
            resume_submit: false,
            generation: 7,
            error: None,
        });
        state.transcript_scroll.observe_rendered_maximum(40);
        state.transcript_scroll.page_up(11);
        let error = save_current_session(&mut state, &store).unwrap_err();
        assert_eq!(error.kind(), std::io::ErrorKind::WouldBlock);
        assert!(!temp.path().join(format!("{id}.json")).exists());

        let older = vec![
            Message {
                role: Role::User,
                content: "old user".into(),
                tool_calls: None,
                thinking: None,
                timestamp: chrono::DateTime::from_timestamp(1, 0).unwrap(),
                response_items: Vec::new(),
            },
            Message {
                role: Role::Assistant,
                content: "old answer".into(),
                tool_calls: None,
                thinking: None,
                timestamp: chrono::DateTime::from_timestamp(2, 0).unwrap(),
                response_items: Vec::new(),
            },
        ];
        apply_session_history_result(
            &mut state,
            SessionHistoryTaskResult {
                generation: 7,
                outcome: Ok(SessionHistoryTaskOutcome::Page(
                    session::SessionHistoryPage {
                        storage_key: id.to_string(),
                        session_id: id,
                        storage_generation: uuid::Uuid::nil(),
                        start_index: 0,
                        total_messages: 4,
                        messages: older,
                    },
                )),
            },
        );
        assert_eq!(
            state
                .messages
                .iter()
                .map(|message| message.content.as_str())
                .collect::<Vec<_>>(),
            ["old user", "old answer", "recent user", "recent answer"]
        );
        assert_eq!(state.session_history.as_ref().unwrap().start_index, 0);
        assert_eq!(
            state.transcript_scroll.bottom_offset(),
            11,
            "prepend must retain bottom anchor"
        );
        save_current_session(&mut state, &store).unwrap();
        assert_eq!(store.load(&id.to_string()).unwrap().messages.len(), 4);
    }

    #[tokio::test]
    async fn resumed_bundle_hydrates_complete_history_on_the_blocking_worker() {
        let temp = tempfile::tempdir().unwrap();
        let store = session::SessionStore::new(temp.path().join("sessions"));
        let mut saved = session::SessionV2::new(
            "Long",
            temp.path().to_string_lossy(),
            "local",
            "coder",
            (0..130)
                .map(|index| Message {
                    role: if index % 2 == 0 {
                        Role::User
                    } else {
                        Role::Assistant
                    },
                    content: format!("message-{index:03}"),
                    tool_calls: None,
                    thinking: None,
                    timestamp: chrono::DateTime::from_timestamp(index + 1, 0).unwrap(),
                    response_items: Vec::new(),
                })
                .collect(),
        );
        store.save(&mut saved).unwrap();
        let mut state = AppState::new(context::ShellHistory::in_memory());
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        let mut load_handle = None;
        let mut history_handle = None;
        start_session_load(
            &mut state,
            &store,
            saved.id.to_string(),
            &tx,
            &mut load_handle,
            &mut history_handle,
        );
        assert!(state.session_load_busy);
        let StreamMsg::SessionLoaded { result, generation } = rx.recv().await.unwrap() else {
            panic!("expected session load result")
        };
        apply_session_load_result(&mut state, *result, generation);
        load_handle.take().unwrap().await.unwrap();
        assert_eq!(state.messages.len(), 64);
        let history = state.session_history.as_mut().unwrap();
        history.request_full = true;
        history.resume_submit = true;
        start_pending_session_history(&mut state, &store, &tx, &mut history_handle);
        assert!(state.session_history.as_ref().unwrap().busy);

        let StreamMsg::SessionHistory(result) = rx.recv().await.unwrap() else {
            panic!("expected history result")
        };
        apply_session_history_result(&mut state, result);
        history_handle.take().unwrap().await.unwrap();
        assert_eq!(state.messages.len(), 130);
        assert_eq!(state.messages[0].content, "message-000");
        assert!(state.session_history.as_ref().unwrap().is_complete());
        assert!(state.session_history.as_ref().unwrap().resume_submit);
        assert_eq!(state.current_session.as_ref().unwrap().messages.len(), 130);
    }

    #[test]
    fn multi_run_command_rejects_bare_and_invalid_counts_before_activity() {
        let config = CaConfig::default_config();
        let mut bare = AppState::new(context::ShellHistory::in_memory());
        bare.active_profile = runtime::ActiveProfile::Bare;
        bare.run_capabilities =
            runtime::RunCapabilities::for_profile(&runtime::ActiveProfile::Bare);
        open_multi_run_manager(&mut bare, &config, "2 never start");
        assert!(bare.multi_run_manager.is_none());
        assert!(bare
            .status_message
            .as_deref()
            .is_some_and(|message| message.contains("persistent profile-owned worktrees")));

        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.current_model = Some(ModelInfo {
            provider: "mimo".into(),
            id: "mimo-v2.5-pro".into(),
            display_name: "mimo-v2.5-pro".into(),
        });
        state.model_list = vec![state.current_model.clone().unwrap()];
        open_multi_run_manager(&mut state, &config, "6 never start");
        let manager = state.multi_run_manager.unwrap();
        assert!(manager.editing);
        assert!(manager.run.is_none());
        assert!(manager
            .error
            .as_deref()
            .is_some_and(|error| error.contains("2-5 candidates")));
        assert!(state.multi_run_stashed.is_none());
    }

    #[test]
    fn undo_and_redo_commands_use_generation_safe_process_history_only() {
        let root = tempfile::tempdir().unwrap();
        let path = root.path().join("tracked.txt");
        std::fs::write(&path, "after").unwrap();
        let config_path = root.path().join("config.toml");
        let config_store = ConfigStore::new(&config_path);
        let config = CaConfig::default_config();
        let session_store = session::SessionStore::new(root.path().join("sessions"));
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.messages.push(Message {
            role: Role::User,
            content: "canonical stays".into(),
            tool_calls: None,
            thinking: None,
            timestamp: chrono::Utc::now(),
            response_items: Vec::new(),
        });
        state
            .undo_stack
            .record(crate::undo::FileMutationReceipt::new(
                path.clone(),
                "write_file",
                crate::undo::FileState::Utf8("before".into()),
                crate::undo::FileState::Utf8("after".into()),
            ));

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::Undo,
                args: String::new(),
            },
            &session_store,
            &config,
            &config_store,
        );
        assert_eq!(state.undo_request, Some(crate::undo::UndoDirection::Undo));
        let operation = state
            .undo_stack
            .prepare(crate::undo::UndoDirection::Undo)
            .unwrap();
        crate::undo::perform(&operation).unwrap();
        state.undo_generation = 7;
        state.undo_busy = true;
        assert!(apply_undo_task_result(
            &mut state,
            UndoTaskResult {
                generation: 7,
                operation,
                result: Ok(()),
                diagnostics: Some(
                    "LSP diagnostics [rust]: 1\n- warning [rustc] 1:1-1:2 — restored".into(),
                ),
                durable: None,
            },
        ));
        assert_eq!(std::fs::read_to_string(&path).unwrap(), "before");
        assert!(!state.undo_busy);
        assert_eq!(state.messages.len(), 1);
        assert_eq!(state.messages[0].content, "canonical stays");
        assert!(state.current_session.is_none());
        assert!(state.pager_open);
        assert!(state.pager_content.contains("restored"));

        state.undo_request = None;
        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::Redo,
                args: String::new(),
            },
            &session_store,
            &config,
            &config_store,
        );
        assert_eq!(state.undo_request, Some(crate::undo::UndoDirection::Redo));
    }

