    #[test]
    fn retaining_a_mutation_records_exact_process_only_activity_metadata() {
        let root = tempfile::tempdir().unwrap();
        let root_path = root.path().canonicalize().unwrap();
        let receipt = crate::undo::FileMutationReceipt::new(
            root_path.join("new.rs"),
            "write_file",
            crate::undo::FileState::Missing,
            crate::undo::FileState::Utf8("new".into()),
        );
        let result = crate::agent::registry::ToolExecutionResult::SuccessMutation {
            marker: "@@ new.rs (Created, 3 bytes) @@\n+new".into(),
            mutation: receipt.into(),
        };
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.workspace =
            workspace::WorkspaceContext::from_primary(root_path.clone(), root_path.clone());

        retain_file_mutation(&mut state, "write-call", &result);

        assert_eq!(
            state.file_activity_presentations.get("write-call"),
            Some(&crate::app::FileActivityPresentation {
                path: root_path.join("new.rs"),
                kind: crate::app::FileActivityKind::Created,
            })
        );
        assert_eq!(
            state.mechanistic_changed_paths,
            std::collections::BTreeSet::from(["new.rs".to_string()])
        );
        assert!(state
            .undo_stack
            .prepare(crate::undo::UndoDirection::Undo)
            .is_some());
        assert_eq!(state.artifact_ledger.entries().len(), 1);
        assert_eq!(state.artifact_ledger.entries()[0].relative_path, "new.rs");

        let edited = crate::app::FileActivityPresentation::from_receipt(
            &crate::undo::FileMutationReceipt::new(
                "/workspace/edited.rs".into(),
                "edit_file",
                crate::undo::FileState::Utf8("before".into()),
                crate::undo::FileState::Utf8("after".into()),
            ),
        );
        let deleted = crate::app::FileActivityPresentation::from_receipt(
            &crate::undo::FileMutationReceipt::new(
                "/workspace/deleted.rs".into(),
                "delete_file",
                crate::undo::FileState::Utf8("before".into()),
                crate::undo::FileState::Missing,
            ),
        );
        assert_eq!(edited.kind, crate::app::FileActivityKind::Edited);
        assert_eq!(deleted.kind, crate::app::FileActivityKind::Deleted);
    }

