    #[test]
    fn artifacts_command_lists_revalidates_views_and_untracks_metadata_only() {
        let root = tempfile::tempdir().unwrap();
        let root_path = root.path().canonicalize().unwrap();
        let path = root_path.join("artifact.txt");
        std::fs::write(&path, "visible artifact").unwrap();
        let mut state = AppState::new(crate::context::ShellHistory::in_memory());
        state.cwd = root_path.to_string_lossy().into_owned();
        state.workspace =
            workspace::WorkspaceContext::from_primary(root_path.clone(), root_path.clone());
        state.current_model = Some(ModelInfo {
            provider: "local".into(),
            id: "coder".into(),
            display_name: "coder".into(),
        });
        let receipt =
            crate::undo::FileMutationBatchReceipt::single(crate::undo::FileMutationReceipt::new(
                path.clone(),
                "write_file",
                crate::undo::FileState::Missing,
                crate::undo::FileState::Utf8("visible artifact".into()),
            ));
        state.artifact_ledger.record_mutation_batch(
            &state.workspace,
            &receipt,
            0,
            chrono::Utc::now(),
        );
        let store = session::SessionStore::new(root_path.join("sessions"));

        manage_artifacts_command(&mut state, &store, "");
        assert!(state
            .pager_content
            .contains("artifact.txt · created · tracked"));
        manage_artifacts_command(&mut state, &store, "inspect 1");
        assert!(state.pager_content.contains("State: available"));
        manage_artifacts_command(&mut state, &store, "view 1");
        assert_eq!(state.pager_content, "visible artifact");

        state.run_capabilities.session_persistence = false;
        manage_artifacts_command(&mut state, &store, "untrack 1");
        assert!(state.artifact_ledger.is_empty());
        assert_eq!(std::fs::read_to_string(path).unwrap(), "visible artifact");
        assert!(state
            .status_message
            .as_deref()
            .is_some_and(|message| message.contains("file unchanged")));
    }

