    #[test]
    fn stale_or_failed_undo_results_do_not_consume_history() {
        let root = tempfile::tempdir().unwrap();
        let path = root.path().join("tracked.txt");
        std::fs::write(&path, "external").unwrap();
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state
            .undo_stack
            .record(crate::undo::FileMutationReceipt::new(
                path,
                "edit_file",
                crate::undo::FileState::Utf8("before".into()),
                crate::undo::FileState::Utf8("after".into()),
            ));
        let operation = state
            .undo_stack
            .prepare(crate::undo::UndoDirection::Undo)
            .unwrap();
        state.undo_generation = 4;
        state.undo_busy = true;
        assert!(!apply_undo_task_result(
            &mut state,
            UndoTaskResult {
                generation: 3,
                operation: operation.clone(),
                result: Ok(()),
                diagnostics: None,
                durable: None,
            },
        ));
        assert!(state.undo_busy);
        assert!(state
            .undo_stack
            .prepare(crate::undo::UndoDirection::Undo)
            .is_some());

        let error = crate::undo::perform(&operation).unwrap_err();
        assert!(apply_undo_task_result(
            &mut state,
            UndoTaskResult {
                generation: 4,
                operation,
                result: Err(error),
                diagnostics: None,
                durable: None,
            },
        ));
        assert!(!state.undo_busy);
        assert!(state
            .undo_stack
            .prepare(crate::undo::UndoDirection::Undo)
            .is_some());
        assert!(state.undo_stack.redo_is_empty());
        assert_eq!(
            std::fs::read_to_string(root.path().join("tracked.txt")).unwrap(),
            "external"
        );
    }

    #[test]
    fn soft_pause_commands_are_idempotent_and_keep_cancellation_distinct() {
        let root = tempfile::tempdir().unwrap();
        let config_store = ConfigStore::new(root.path().join("config.toml"));
        let config = CaConfig::default_config();
        let session_store = session::SessionStore::new(root.path().join("sessions"));
        let mut state = AppState::new(context::ShellHistory::in_memory());
        let command = |state: &mut AppState, id| {
            execute_command_action(
                state,
                tui::commands::CommandAction {
                    id,
                    args: String::new(),
                },
                &session_store,
                &config,
                &config_store,
            );
        };

        command(&mut state, tui::commands::CommandId::Pause);
        assert_eq!(state.soft_pause, activity::SoftPauseState::Inactive);
        assert_eq!(
            state.status_message.as_deref(),
            Some("No active turn to pause")
        );

        state.turn_lifecycle.begin();
        command(&mut state, tui::commands::CommandId::Pause);
        assert_eq!(state.soft_pause, activity::SoftPauseState::Requested);
        command(&mut state, tui::commands::CommandId::Pause);
        assert_eq!(state.soft_pause, activity::SoftPauseState::Requested);
        command(&mut state, tui::commands::CommandId::Unpause);
        assert_eq!(state.soft_pause, activity::SoftPauseState::Requested);
        assert_eq!(
            state.status_message.as_deref(),
            Some("Pause has not reached a safe boundary yet")
        );

        assert!(reach_soft_pause(
            &mut state,
            activity::SoftPauseBoundary::Tools
        ));
        assert_eq!(state.turn_lifecycle.phase, activity::ActivityPhase::Paused);
        assert!(state.turn_lifecycle.is_active());
        command(&mut state, tui::commands::CommandId::Pause);
        assert_eq!(
            state.soft_pause,
            activity::SoftPauseState::Paused(activity::SoftPauseBoundary::Tools)
        );
        command(&mut state, tui::commands::CommandId::Unpause);
        assert_eq!(
            state.soft_pause.take_resume(),
            Some(activity::SoftPauseBoundary::Tools)
        );

        state.soft_pause = activity::SoftPauseState::Requested;
        state.soft_pause.clear();
        state.turn_lifecycle.cancel();
        state.outcome_tracker.record_interrupt();
        assert_eq!(state.soft_pause, activity::SoftPauseState::Inactive);
        assert_eq!(
            state.turn_lifecycle.outcome,
            activity::TurnOutcome::Cancelled
        );
    }

    #[test]
    fn completed_tool_boundary_retains_results_without_starting_provider() {
        let mut state = AppState::new(context::ShellHistory::in_memory());
        state.turn_lifecycle.begin();
        state.soft_pause = activity::SoftPauseState::Requested;
        state.messages.push(Message {
            role: Role::Assistant,
            content: String::new(),
            tool_calls: Some(vec![ToolCall {
                id: "call-1".into(),
                name: "read_file".into(),
                arguments: r#"{"path":"kept.txt"}"#.into(),
                status: ToolStatus::Done,
                output: Some("retained output".into()),
            }]),
            thinking: None,
            timestamp: chrono::Utc::now(),
            response_items: Vec::new(),
        });
        let config = CaConfig::default_config();
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        let mut provider_task = None;

        continue_after_tool_resolutions(&mut state, &config, &tx, &mut provider_task);

        assert!(provider_task.is_none());
        assert!(rx.try_recv().is_err());
        assert_eq!(state.messages.len(), 1);
        assert_eq!(
            state.messages[0].tool_calls.as_ref().unwrap()[0]
                .output
                .as_deref(),
            Some("retained output")
        );
        assert_eq!(
            state.soft_pause,
            activity::SoftPauseState::Paused(activity::SoftPauseBoundary::Provider)
        );
        assert_eq!(state.turn_lifecycle.phase, activity::ActivityPhase::Paused);
    }

