    #[test]
    fn model_once_and_preset_commands_keep_routes_process_scoped_and_cancel_first() {
        let temp = tempfile::tempdir().unwrap();
        let store = ConfigStore::new(temp.path().join("config.toml"));
        let sessions = session::SessionStore::new(temp.path().join("sessions"));
        let mut config = CaConfig::default_config();
        config.providers = std::collections::HashMap::from([
            (
                "primary".into(),
                config::ProviderConfig {
                    google: None,
                    tool_schema_policy: Default::default(),
                    base_url: "http://127.0.0.1:1/v1".into(),
                    api_key: String::new(),
                    protocol: agent::ProviderProtocol::default(),
                    prompt_cache_mode: crate::config::PromptCacheMode::Implicit,
                    models: vec!["base".into()],
                    timeout: config::ProviderTimeoutConfig::default(),
                },
            ),
            (
                "alternate".into(),
                config::ProviderConfig {
                    google: None,
                    tool_schema_policy: Default::default(),
                    base_url: "http://127.0.0.1:1/v1".into(),
                    api_key: String::new(),
                    protocol: agent::ProviderProtocol::default(),
                    prompt_cache_mode: crate::config::PromptCacheMode::Implicit,
                    models: vec!["first".into(), "replacement".into()],
                    timeout: config::ProviderTimeoutConfig::default(),
                },
            ),
        ]);
        config.route_presets.insert(
            "daily".into(),
            config::RoutePreset {
                provider: "alternate".into(),
                model: "replacement".into(),
                reasoning_effort: None,
            },
        );
        let baseline = ModelInfo {
            provider: "primary".into(),
            id: "base".into(),
            display_name: "base".into(),
        };
        let mut state = AppState {
            current_model: Some(baseline.clone()),
            model_list: vec![
                baseline.clone(),
                ModelInfo {
                    provider: "alternate".into(),
                    id: "first".into(),
                    display_name: "first".into(),
                },
                ModelInfo {
                    provider: "alternate".into(),
                    id: "replacement".into(),
                    display_name: "replacement".into(),
                },
            ],
            ..AppState::default()
        };

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::Model,
                args: "first --once".into(),
            },
            &sessions,
            &config,
            &store,
        );
        assert_eq!(state.current_model.as_ref().unwrap().id, "first");
        assert_eq!(
            state
                .one_turn_route
                .as_ref()
                .unwrap()
                .baseline
                .model
                .as_ref(),
            Some(&baseline)
        );
        assert_eq!(config.defaults.provider, "deepseek");

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::Model,
                args: "replacement --once".into(),
            },
            &sessions,
            &config,
            &store,
        );
        assert_eq!(state.current_model.as_ref().unwrap().id, "replacement");
        assert_eq!(
            state
                .one_turn_route
                .as_ref()
                .unwrap()
                .baseline
                .model
                .as_ref(),
            Some(&baseline)
        );

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::Preset,
                args: "daily".into(),
            },
            &sessions,
            &config,
            &store,
        );
        assert!(state.one_turn_route.is_none());
        assert_eq!(state.current_model.as_ref().unwrap().id, "replacement");

        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::PresetSave,
                args: "daily".into(),
            },
            &sessions,
            &config,
            &store,
        );
        assert!(!state.route_preset_overwrite.as_ref().unwrap().save_selected);
    }

