    #[test]
    fn preset_save_validates_names_refuses_bare_and_keeps_route_on_save_failure() {
        let temp = tempfile::tempdir().unwrap();
        let store = ConfigStore::new(temp.path().join("config.toml"));
        let sessions = session::SessionStore::new(temp.path().join("sessions"));
        let config = CaConfig::default_config();
        let route = ModelInfo {
            provider: "deepseek".into(),
            id: "deepseek-v4-flash".into(),
            display_name: "DeepSeek".into(),
        };
        let mut state = AppState {
            current_model: Some(route.clone()),
            reasoning_effort: Some(config::ReasoningEffort::Medium),
            ..AppState::default()
        };

        for invalid in ["", "Upper", "has space"] {
            execute_command_action(
                &mut state,
                tui::commands::CommandAction {
                    id: tui::commands::CommandId::PresetSave,
                    args: invalid.into(),
                },
                &sessions,
                &config,
                &store,
            );
            assert!(state.pending_input_action.is_none());
        }

        state.run_capabilities =
            runtime::RunCapabilities::for_profile(&runtime::ActiveProfile::Bare);
        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::PresetSave,
                args: "daily".into(),
            },
            &sessions,
            &config,
            &store,
        );
        assert!(state
            .status_message
            .as_deref()
            .unwrap()
            .contains("bare mode"));
        assert!(state.pending_input_action.is_none());

        state.run_capabilities =
            runtime::RunCapabilities::for_profile(&runtime::ActiveProfile::Default);
        execute_command_action(
            &mut state,
            tui::commands::CommandAction {
                id: tui::commands::CommandId::PresetSave,
                args: "daily".into(),
            },
            &sessions,
            &config,
            &store,
        );
        assert!(matches!(
            state.pending_input_action,
            Some(tui::commands::InputAction::SaveRoutePreset { ref name, .. }) if name == "daily"
        ));

        state.pending_input_action = None;
        state.status_message = Some("Saving route preset…".into());
        let before = (state.current_model.clone(), state.reasoning_effort);
        apply_ui_save_result(&mut state, &mut config.clone(), Err("disk full".into()));
        assert_eq!(
            (state.current_model.clone(), state.reasoning_effort),
            before
        );
        assert_eq!(
            state.status_message.as_deref(),
            Some("Could not save route preset: disk full")
        );
    }

    #[tokio::test]
    async fn one_turn_override_prepares_the_selected_route_then_restores() {
        let mut config = CaConfig::default_config();
        config.providers = std::collections::HashMap::from([
            (
                "primary".into(),
                config::ProviderConfig {
                    google: None,
                    tool_schema_policy: Default::default(),
                    base_url: "http://127.0.0.1:1/v1".into(),
                    api_key: "${CA_CFG124_PRIMARY_MISSING}".into(),
                    protocol: agent::ProviderProtocol::default(),
                    prompt_cache_mode: crate::config::PromptCacheMode::Implicit,
                    models: vec!["base".into()],
                    timeout: config::ProviderTimeoutConfig::default(),
                },
            ),
            (
                "alternate".into(),
                config::ProviderConfig {
                    google: None,
                    tool_schema_policy: Default::default(),
                    base_url: "http://127.0.0.1:1/v1".into(),
                    api_key: "${CA_CFG124_ALTERNATE_MISSING}".into(),
                    protocol: agent::ProviderProtocol::default(),
                    prompt_cache_mode: crate::config::PromptCacheMode::Implicit,
                    models: vec!["once".into()],
                    timeout: config::ProviderTimeoutConfig::default(),
                },
            ),
        ]);
        let baseline = ModelInfo {
            provider: "primary".into(),
            id: "base".into(),
            display_name: "base".into(),
        };
        let mut state = AppState {
            current_model: Some(baseline.clone()),
            ..AppState::default()
        };
        state.messages.push(Message {
            role: Role::User,
            content: "use the one-turn route".into(),
            tool_calls: None,
            thinking: None,
            timestamp: chrono::Utc::now(),
            response_items: Vec::new(),
        });
        set_one_turn_route(
            &mut state,
            ModelInfo {
                provider: "alternate".into(),
                id: "once".into(),
                display_name: "once".into(),
            },
            None,
        );
        let (tx, _rx) = tokio::sync::mpsc::unbounded_channel();
        let mut handle = None;

        start_llm_turn(&mut state, &config, &tx, &mut handle);
        handle.take().unwrap().await.unwrap();
        let snapshot = state.request_store.snapshot().unwrap();
        assert_eq!(
            (snapshot.provider.as_str(), snapshot.model.as_str()),
            ("alternate", "once")
        );
        assert!(state.one_turn_route.as_ref().unwrap().consumed);

        state.turn_lifecycle.fail();
        state.outcome_tracker.record_failure();
        let completion = state.turn_lifecycle.take_completion().unwrap();
        assert!(restore_one_turn_route_after(&mut state, completion.outcome));
        assert_eq!(state.current_model.as_ref(), Some(&baseline));
    }

    #[test]
    fn file_picker_snapshots_reject_stale_or_closed_generations() {
        let mut state = AppState {
            file_picker_open: true,
            file_picker_generation: 4,
            ..AppState::default()
        };
        let stale_index = attachments::FileIndexSnapshot {
            generation: 3,
            files: Arc::new(vec![attachments::IndexedFile {
                root_id: "root".into(),
                root_label: "workspace".into(),
                relative: "stale.rs".into(),
                reference: "stale.rs".into(),
                read_only: false,
            }]),
            discovered: 1,
            truncated: false,
            error: None,
        };
        assert!(!apply_file_picker_index_snapshot(&mut state, stale_index));
        assert!(state.file_picker_index.is_empty());

        let current_index = attachments::FileIndexSnapshot {
            generation: 4,
            files: Arc::new(Vec::new()),
            discovered: 0,
            truncated: false,
            error: None,
        };
        assert!(apply_file_picker_index_snapshot(&mut state, current_index));
        assert!(state.file_picker_index_ready);
        assert_eq!(state.file_picker_generation, 5);

        let stale_match = attachments::MatchSnapshot {
            generation: 4,
            entries: Vec::new(),
            total_matches: 99,
        };
        assert!(!apply_file_picker_match_snapshot(&mut state, stale_match));
        assert_eq!(state.file_picker_matches, 0);

        let current_match = attachments::MatchSnapshot {
            generation: 5,
            entries: Vec::new(),
            total_matches: 7,
        };
        assert!(apply_file_picker_match_snapshot(&mut state, current_match));
        assert_eq!(state.file_picker_matches, 7);
        state.file_picker_open = false;
        assert!(!apply_file_picker_match_snapshot(
            &mut state,
            attachments::MatchSnapshot {
                generation: 5,
                entries: Vec::new(),
                total_matches: 8,
            }
        ));
    }

    #[test]
    fn path_completion_results_reject_stale_tokens_and_closed_surfaces() {
        let mut state = AppState::default();
        state.composer_ui.path_completion.open = true;
        state.composer_ui.path_completion.generation = 8;
        state.composer_ui.path_completion.token = "./src".into();
        let result = |generation, token: &str| tui::composer::PathCompletionResult {
            generation,
            token: token.into(),
            entries: vec![tui::composer::PathCompletionEntry {
                display: "src/".into(),
                replacement: "./src/".into(),
                is_dir: true,
            }],
            error: None,
        };

        assert!(!apply_path_completion_result(
            &mut state,
            result(7, "./src")
        ));
        assert!(!apply_path_completion_result(
            &mut state,
            result(8, "./spec")
        ));
        assert!(state.composer_ui.path_completion.entries.is_empty());
        assert!(apply_path_completion_result(&mut state, result(8, "./src")));
        state.composer_ui.path_completion.open = false;
        assert!(!apply_path_completion_result(
            &mut state,
            result(8, "./src")
        ));
    }

    #[tokio::test]
    async fn pane_stream_channels_preserve_origin_identity() {
        let (router, mut receiver) = mpsc::unbounded_channel();
        let (first, first_forwarder) = pane_stream_channel(panes::PaneId::PRIMARY, router.clone());
        let second_id = panes::PaneId::from(2);
        let (second, second_forwarder) = pane_stream_channel(second_id, router);

        first.send(StreamMsg::AwaitingProvider(11)).unwrap();
        second.send(StreamMsg::AwaitingProvider(22)).unwrap();
        let mut routed = [
            receiver.recv().await.unwrap(),
            receiver.recv().await.unwrap(),
        ];
        routed.sort_by_key(|message| message.pane);
        assert_eq!(routed[0].pane, panes::PaneId::PRIMARY);
        assert!(matches!(routed[0].message, StreamMsg::AwaitingProvider(11)));
        assert_eq!(routed[1].pane, second_id);
        assert!(matches!(routed[1].message, StreamMsg::AwaitingProvider(22)));

        first_forwarder.abort();
        second_forwarder.abort();
    }

    #[test]
    fn background_mutations_wait_for_focused_approval() {
        let mut state = AppState::default();
        let area = ratatui::layout::Rect::new(0, 0, 120, 32);
        let mut deck = state.pane_deck.take().unwrap();
        let second = deck
            .split(
                &state,
                panes::SplitAxis::Vertical,
                state.new_pane_from(),
                area,
            )
            .unwrap();
        state.pane_deck = Some(deck);
        panes::focus(&mut state, second).unwrap();
        panes::materialize(&mut state, panes::PaneId::PRIMARY).unwrap();
        state.turn_lifecycle.begin();
        state.manual_resolutions.begin(vec![
            crate::interaction::PendingManualResolution::Execution(
                crate::interaction::PendingExecution {
                    tool_name: "write_file".into(),
                    tool_args: serde_json::json!({"path":"owned.txt","content":"safe"}).to_string(),
                    tool_id: "call-write".into(),
                    network_allowed: false,
                    pre_resolved: None,
                },
            ),
        ]);
        let (sender, mut receiver) = mpsc::unbounded_channel();
        let mut stream = None;

        activate_next_manual_resolution(&mut state, &CaConfig::default(), &sender, &mut stream);

        assert_eq!(
            state
                .approval_queue
                .current()
                .map(|approval| approval.tool_id.as_str()),
            Some("call-write")
        );
        assert!(receiver.try_recv().is_err());
        assert!(state
            .status_message
            .as_deref()
            .is_some_and(|message| message.contains("needs approval")));
    }

    #[test]
    fn simultaneous_pane_streams_keep_text_and_generations_isolated() {
        fn streaming() -> StreamingState {
            StreamingState {
                provider_text: Default::default(),
                content: String::new(),
                tool_calls: Vec::new(),
                thinking: None,
                response_items: Vec::new(),
                last_usage: None,
                usage_handle: usage::UsageHandle::test_handle(),
                reasoning_started_at: None,
                reasoning_duration: None,
                generation_started_at: None,
            }
        }

        let mut state = AppState {
            stream_generation: 41,
            streaming: Some(streaming()),
            ..AppState::default()
        };
        let area = ratatui::layout::Rect::new(0, 0, 120, 32);
        let mut second_state = state.new_pane_from();
        second_state.stream_generation = 73;
        second_state.streaming = Some(streaming());
        let mut deck = state.pane_deck.take().unwrap();
        let second = deck
            .split(&state, panes::SplitAxis::Vertical, second_state, area)
            .unwrap();
        state.pane_deck = Some(deck);

        handle_stream_delta(&mut state, agent::ChatDelta::Text("left".into()));
        panes::focus(&mut state, second).unwrap();
        handle_stream_delta(&mut state, agent::ChatDelta::Text("right".into()));

        assert_eq!(state.stream_generation, 73);
        assert_eq!(state.streaming.as_ref().unwrap().content, "right");
        let deck = state.pane_deck.as_ref().unwrap();
        let first = deck.pane(&state, panes::PaneId::PRIMARY).unwrap();
        assert_eq!(first.stream_generation, 41);
        assert_eq!(first.streaming.as_ref().unwrap().content, "left");
    }

    #[test]
    fn yolo_and_auto_review_cli_flags_are_mutually_exclusive() {
        use clap::Parser as _;
        let err = RawCliArgs::try_parse_from(["ca", "--yolo", "--auto-review", "-p", "hello"])
            .expect_err("yolo and auto-review must not combine");
        let message = err.to_string();
        assert!(
            message.contains("cannot be used with") || message.contains("conflict"),
            "unexpected clap conflict message: {message}"
        );
    }

    #[test]
    fn yolo_flag_alone_and_auto_review_flag_alone_parse() {
        use clap::Parser as _;
        let yolo = RawCliArgs::try_parse_from(["ca", "--yolo", "-p", "hello"]).unwrap();
        assert!(yolo.yolo);
        assert!(!yolo.auto_review);
        let auto = RawCliArgs::try_parse_from(["ca", "--auto-review", "-p", "hello"]).unwrap();
        assert!(auto.auto_review);
        assert!(!auto.yolo);
    }

    #[test]
    fn headless_trust_cannot_combine_with_continue() {
        let err = parse_cli_args(["ca", "--trust", "--continue", "-p", "hello"])
            .expect_err("--trust must not combine with --continue");
        let message = err.to_string();
        assert!(
            message.contains("--trust") && message.contains("continue"),
            "unexpected validation message: {message}"
        );
    }

