        let id = left.current_session.as_ref().unwrap().id;
        let before = serde_json::to_vec(&left.current_session).unwrap();
        let left_task = tokio::spawn(std::future::pending::<()>());
        let right_task = tokio::spawn(std::future::pending::<()>());
        left.checkpoint_abort = Some(left_task.abort_handle());
        right.checkpoint_abort = Some(right_task.abort_handle());
        left.checkpoint_writer = Some(store.try_writer_lease(id).unwrap());
        left.checkpoint_in_flight = true;
        left.checkpoint_generation = 5;
        right.checkpoint_in_flight = true;
        right.checkpoint_generation = 8;
