        assert_eq!(right.checkpoint_generation, 8);
        assert!(!left.checkpoint_in_flight);
        assert_eq!(left.checkpoint_generation, 6);
        assert_eq!(serde_json::to_vec(&left.current_session).unwrap(), before);
        assert!(store.try_writer_lease(id).is_ok());
        right_task.abort();
